INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80910f66-39da-4bc3-a42e-fabe2efd9c63', '郊廟歌辭 祀九宮貴神樂章 肅和', '郊廟歌辞 祀九宮貴神乐章 肅和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["精意嚴恭，明祠豐潔。","獻酬既備，俎豆斯撤。","日麗天儀，風和樂節。","事光祀典，福覃有截。"]', '["精意嚴恭，明祠豐潔。","獻酬既備，俎豆斯撤。","日丽天儀，风和乐節。","事光祀典，福覃有截。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祀九宮貴神樂章 肅和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bf5642a-503b-4b19-93bb-9e18f20df141', '郊廟歌辭 祀九宮貴神樂章 豫和', '郊廟歌辞 祀九宮貴神乐章 豫和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["享申百禮，慶洽百靈。","上排閶闔，洞入杳冥。","奠玉高壇，燔柴廣庭。","神之降福，萬國咸寧。"]', '["享申百禮，慶洽百靈。","上排閶闔，洞入杳冥。","奠玉高壇，燔柴廣庭。","神之降福，万国咸寧。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祀九宮貴神樂章 豫和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48e87201-2f41-4e2d-bb1a-f3e1c828757d', '郊廟歌辭 祀風師樂章 迎神', '郊廟歌辞 祀风師乐章 迎神', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["太皞御氣，句芒肇功。","蒼龍青旗，爰候祥風。","律以和應，神以感通。","鼎俎修蠁，時惟禮崇。"]', '["太皞御氣，句芒肇功。","蒼龙青旗，爰候祥风。","律以和應，神以感通。","鼎俎修蠁，时惟禮崇。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祀風師樂章 迎神 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a0560ff-22f2-451a-a75e-e3d32640240e', '郊廟歌辭 祀風師樂章 奠幣登歌', '郊廟歌辞 祀风師乐章 奠幣登歌', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["旨酒告絜，青蘋應候。","禮陳瑤幣，樂獻金奏。","彈弦自昔，解凍惟舊。","仰瞻肸蠁，羣祥來湊。"]', '["旨酒告絜，青蘋應候。","禮陳瑤幣，乐獻金奏。","彈弦自昔，解凍惟旧。","仰瞻肸蠁，羣祥来湊。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祀風師樂章 奠幣登歌 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed30bc82-7666-4957-9e8b-6cda14f46dac', '郊廟歌辭 祀風師樂章 迎俎酌獻', '郊廟歌辞 祀风師乐章 迎俎酌獻', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["德盛昭臨，迎拜巽方。","爰候發生，式薦馨香。","酌醴具舉，工歌載揚。","神歆六律，恩降百祥。"]', '["德盛昭臨，迎拜巽方。","爰候發生，式薦馨香。","酌醴具舉，工歌載揚。","神歆六律，恩降百祥。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祀風師樂章 迎俎酌獻 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76ea75c2-9fce-4c89-9452-c7f53343d43f', '郊廟歌辭 祀風師樂章 亞獻終獻', '郊廟歌辞 祀风師乐章 亞獻終獻', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["膋薌備，玉帛陳。","風動物，樂感神。","三獻終，百神臻。","草木榮，天下春。"]', '["膋薌備，玉帛陳。","风动物，乐感神。","三獻終，百神臻。","草木榮，天下春。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祀風師樂章 亞獻終獻 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd76be6d-7ece-4852-94d3-381fae092e8f', '郊廟歌辭 祀風師樂章 送神', '郊廟歌辞 祀风師乐章 送神', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["微穆敷華能應節，飄揚發彩宜行慶。","送迎靈駕神心享，跪拜靈壇禮容盛。","氣和草木發萌芽，德暢禽魚遂翔泳。","永望翠蓋逐流雲，自茲率土調春令。"]', '["微穆敷华能應節，飄揚發彩宜行慶。","送迎靈駕神心享，跪拜靈壇禮容盛。","氣和草木發萌芽，德暢禽鱼遂翔泳。","永望翠蓋逐流云，自茲率土調春令。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祀風師樂章 送神 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e40f240c-8c10-410d-ba39-157d186b593b', '郊廟歌辭 祀雨師樂章 迎神', '郊廟歌辞 祀雨師乐章 迎神', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["陟降左右，誠達幽圜。","作解之功，樂惟有年。","雲軿戾止，灑霧飄煙。","惟馨展禮，爰列豆籩。"]', '["陟降左右，誠達幽圜。","作解之功，乐惟有年。","云軿戾止，灑霧飄煙。","惟馨展禮，爰列豆籩。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祀雨師樂章 迎神 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c721f02a-3227-4c0e-8506-8f7aa683399d', '郊廟歌辭 祀雨師樂章 奠幣登歌', '郊廟歌辞 祀雨師乐章 奠幣登歌', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["歲正朱明，禮布元制。","惟樂能感，與神合契。","陰霧離翍，靈馭搖裔。","膏澤之慶，期於稔歲。"]', '["歲正朱明，禮布元制。","惟乐能感，與神合契。","陰霧離翍，靈馭搖裔。","膏澤之慶，期於稔歲。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祀雨師樂章 奠幣登歌 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63f19307-80fe-4569-9f60-7c69d85d3672', '郊廟歌辭 祀雨師樂章 迎俎酌獻', '郊廟歌辞 祀雨師乐章 迎俎酌獻', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["陽開幽蟄，躬奉鬱鬯。","禮備節應，震來靈降。","動植求聲，飛沈允望。","時康氣茂，惟神之貺。"]', '["陽开幽蟄，躬奉鬱鬯。","禮備節應，震来靈降。","动植求声，飞沈允望。","时康氣茂，惟神之貺。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祀雨師樂章 迎俎酌獻 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cb6c10b-4d17-4b83-99d8-f29cbdb84529', '郊廟歌辭 祀雨師樂章 亞獻終獻', '郊廟歌辞 祀雨師乐章 亞獻終獻', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["奠既備，獻將終。","神行令，瑞飛空。","迎乾德，祈歲功。","乘煙燎，儼從風。"]', '["奠既備，獻將終。","神行令，瑞飞空。","迎乾德，祈歲功。","乘煙燎，儼從风。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祀雨師樂章 亞獻終獻 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e2bb285-70d5-4a1c-9fc4-78be6c5f811d', '郊廟歌辭 祀雨師樂章 送神', '郊廟歌辞 祀雨師乐章 送神', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["整駕昇車望寥廓，垂陰薦祉蕩昏氛。","饗時靈貺僾如在，樂罷餘聲遙可聞。","飲福陳誠禮容備，撤俎終獻曙光分。","跪拜臨壇結空想，年年應節候油雲。"]', '["整駕昇车望寥廓，垂陰薦祉蕩昏氛。","饗时靈貺僾如在，乐罷餘声遙可闻。","饮福陳誠禮容備，撤俎終獻曙光分。","跪拜臨壇結空想，年年應節候油云。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祀雨師樂章 送神 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4e88f07-0b85-4b8d-b243-ff17ce413e33', '郊廟歌辭 祭方丘樂章 順和', '郊廟歌辞 祭方丘乐章 順和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["萬方資以化，交泰屬昇平。","易從業惟簡，得一道斯寧。","具儀光玉帛，送舞變咸英。","黍稷良非貴，明德信惟馨。"]', '["万方資以化，交泰屬昇平。","易從業惟簡，得一道斯寧。","具儀光玉帛，送舞变咸英。","黍稷良非貴，明德信惟馨。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祭方丘樂章 順和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44cc1286-e8d7-4374-8cb6-96067c6a09fa', '郊廟歌辭 祭方丘樂章 肅和', '郊廟歌辞 祭方丘乐章 肅和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["至矣坤德，皇哉地祇。","開元統紐，合大承規。","九宮肅列，六典相儀。","永言配命，長保無虧。"]', '["至矣坤德，皇哉地祇。","开元統紐，合大承規。","九宮肅列，六典相儀。","永言配命，长保無虧。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祭方丘樂章 肅和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e817249e-2008-482a-b5b9-b1afeb1fead6', '郊廟歌辭 祭方丘樂章 雍和', '郊廟歌辞 祭方丘乐章 雍和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["柔而能方，直而能敬。","載厚以德，大亨以正。","有滌斯牷，有馨斯盛。","介茲景福，祚我休慶。"]', '["柔而能方，直而能敬。","載厚以德，大亨以正。","有滌斯牷，有馨斯盛。","介茲景福，祚我休慶。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祭方丘樂章 雍和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfb12894-0564-4e10-af0e-17f0d58cec07', '郊廟歌辭 祭方丘樂章 舒和', '郊廟歌辞 祭方丘乐章 舒和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["玉幣牲牷分薦享，羽旄干鏚遰成容。","一德惟寧兩儀泰，三才保合四時邕。"]', '["玉幣牲牷分薦享，羽旄干鏚遰成容。","一德惟寧兩儀泰，三才保合四时邕。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祭方丘樂章 舒和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98035eea-d155-46b8-aca0-45c7a343993c', '郊廟歌辭 祭方丘樂章 順和', '郊廟歌辞 祭方丘乐章 順和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["陰祇協贊，厚載方貞。","牲幣具舉，簫管備成。","其禮惟肅，其德惟明。","神之聽矣，式鑒虔誠。"]', '["陰祇協贊，厚載方貞。","牲幣具舉，簫管備成。","其禮惟肅，其德惟明。","神之听矣，式鑒虔誠。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祭方丘樂章 順和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6aa54435-8335-4fff-959a-c6b92f8d9080', '郊廟歌辭 武后大享拜洛樂章 昭和', '郊廟歌辞 武后大享拜洛乐章 昭和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["九玄眷命，三聖基隆。","奉承先旨，明臺畢功。","宗祀展敬，冀表深衷。","永昌帝業，式播淳風。"]', '["九玄眷命，三聖基隆。","奉承先旨，明台畢功。","宗祀展敬，冀表深衷。","永昌帝業，式播淳风。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后大享拜洛樂章 昭和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67cecd8e-3739-47ab-a664-a3181bc2fc5c', '郊廟歌辭 武后大享拜洛樂章 致和', '郊廟歌辞 武后大享拜洛乐章 致和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["神功不測兮運陰陽，包藏萬宇兮孕八荒。","天符既出兮帝業昌，願臨明祀兮降禎祥。"]', '["神功不測兮運陰陽，包藏万宇兮孕八荒。","天符既出兮帝業昌，願臨明祀兮降禎祥。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后大享拜洛樂章 致和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c7a41e6-d997-46f3-a6b2-bac41d354e35', '郊廟歌辭 武后大享拜洛樂章 咸和', '郊廟歌辞 武后大享拜洛乐章 咸和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["坎澤祠容備舉，坤壇祭典爰申。","靈睠遙行祕躅，嘉貺荐委殊珍。","肅禮恭禋載展，翹襟邈志逾殷。","方期交際懸應。"]', '["坎澤祠容備舉，坤壇祭典爰申。","靈睠遙行祕躅，嘉貺荐委殊珍。","肅禮恭禋載展，翹襟邈志逾殷。","方期交際懸應。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后大享拜洛樂章 咸和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e23a8660-0f59-4a83-8593-28fe70439e76', '郊廟歌辭 武后大享拜洛樂章 九和', '郊廟歌辞 武后大享拜洛乐章 九和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["祗荷坤德，欽若乾靈。","慙惕罔寘，興居匪寧。","恭崇禮則，肅奉儀形。","惟憑展敬，敢薦非馨。"]', '["祗荷坤德，欽若乾靈。","慙惕罔寘，兴居匪寧。","恭崇禮則，肅奉儀形。","惟憑展敬，敢薦非馨。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后大享拜洛樂章 九和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('327ba2ad-484a-4131-b902-17b0938ea157', '郊廟歌辭 武后大享拜洛樂章 顯和', '郊廟歌辞 武后大享拜洛乐章 显和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["菲躬承睿顧，薄德忝坤儀。","乾乾遵後命，翼翼奉先規。","撫俗勤雖切，還淳化尚虧。","未能弘至道，何以契明祇。"]', '["菲躬承睿顧，薄德忝坤儀。","乾乾遵後命，翼翼奉先規。","撫俗勤雖切，還淳化尚虧。","未能弘至道，何以契明祇。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后大享拜洛樂章 顯和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b815af7f-d48d-4db1-9b2f-22cb3117497d', '郊廟歌辭 武后大享拜洛樂章 顯和', '郊廟歌辞 武后大享拜洛乐章 显和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["顧德有慙虛菲，明祇屢降禎符。","汜水初呈祕象，溫洛薦表昌圖。","玄澤流恩載洽，丹襟荷渥增愉。"]', '["顧德有慙虛菲，明祇屢降禎符。","汜水初呈祕象，溫洛薦表昌圖。","玄澤流恩載洽，丹襟荷渥增愉。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后大享拜洛樂章 顯和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a86c51e-e062-44b9-bf59-a3f54c997775', '郊廟歌辭 武后大享拜洛樂章 昭和', '郊廟歌辞 武后大享拜洛乐章 昭和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["舒陰致養，合大資生。","德以恆固，功由永貞。","升歌薦序，垂幣翹誠。","虹開玉照，鳳引金聲。"]', '["舒陰致養，合大資生。","德以恆固，功由永貞。","升歌薦序，垂幣翹誠。","虹开玉照，鳳引金声。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后大享拜洛樂章 昭和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c1c4e9f-9c4c-45e6-8931-886636ca1ce8', '郊廟歌辭 武后大享拜洛樂章 敬和', '郊廟歌辞 武后大享拜洛乐章 敬和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["蘭俎既昇，蘋羞可薦。","金石載設，咸英已變。","林澤斯總，山川是遍。","敢用敷誠，實惟忘倦。"]', '["蘭俎既昇，蘋羞可薦。","金石載設，咸英已变。","林澤斯總，山川是遍。","敢用敷誠，實惟忘倦。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后大享拜洛樂章 敬和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47041f69-1316-4058-9660-f47427973d22', '郊廟歌辭 武后大享拜洛樂章 齊和', '郊廟歌辞 武后大享拜洛乐章 齊和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["沈潛演貺分三極，廣大凝禎總萬方。","既薦羽旌文化啓，還呈干鏚武威揚。"]', '["沈潛演貺分三極，廣大凝禎總万方。","既薦羽旌文化啓，還呈干鏚武威揚。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后大享拜洛樂章 齊和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a69e1314-b376-449b-9db5-58233b8c54d0', '郊廟歌辭 武后大享拜洛樂章 德和', '郊廟歌辞 武后大享拜洛乐章 德和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["夕惕司龍契，晨兢當鳳扆。","崇儒習舊規，偃伯循先旨。","絕壤飛冠蓋，遐區麗山水。","幸承三聖餘，忻屬千年始。"]', '["夕惕司龙契，晨兢當鳳扆。","崇儒習旧規，偃伯循先旨。","絕壤飞冠蓋，遐區丽山水。","幸承三聖餘，忻屬千年始。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后大享拜洛樂章 德和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dad4a5b3-fa77-4fd3-8967-62bc7ca721ac', '郊廟歌辭 武后大享拜洛樂章 禋和', '郊廟歌辞 武后大享拜洛乐章 禋和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["百禮崇容，千官肅事。","靈降無兆，神凝有粹。","奠享咸周，威儀畢備。","奏夏登列，歌雍徹肆。"]', '["百禮崇容，千官肅事。","靈降無兆，神凝有粹。","奠享咸周，威儀畢備。","奏夏登列，歌雍徹肆。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后大享拜洛樂章 禋和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca5a942e-3be3-43f9-b962-847374e44b02', '郊廟歌辭 武后大享拜洛樂章 通和', '郊廟歌辞 武后大享拜洛乐章 通和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["皇皇靈睠，穆穆神心。","暫動凝質，還歸積陰。","功玄樞紐，理寂高深。","銜恩佩德，聳志翹襟。"]', '["皇皇靈睠，穆穆神心。","暫动凝質，還归積陰。","功玄樞紐，理寂高深。","銜恩佩德，聳志翹襟。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后大享拜洛樂章 通和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('903b1584-af9d-4ac6-a017-4df18161929c', '郊廟歌辭 武后大享拜洛樂章 歸和', '郊廟歌辞 武后大享拜洛乐章 归和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["言旋雲洞兮躡煙途，永寧中宇兮安下都。","包涵動植兮順榮枯，長貽寶貺兮贊璇圖。"]', '["言旋云洞兮躡煙途，永寧中宇兮安下都。","包涵动植兮順榮枯，长貽寶貺兮贊璇圖。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后大享拜洛樂章 歸和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c4d57af-c114-4c20-afc4-5f7d1c79c9c6', '郊廟歌辭 武后大享拜洛樂章 又歸和', '郊廟歌辞 武后大享拜洛乐章 又归和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["調雲闋兮神座興，驂雲駕兮儼將昇。","騰絳霄兮垂景祐，翹丹懇兮荷休徵。"]', '["調云闋兮神座兴，驂云駕兮儼將昇。","腾絳霄兮垂景祐，翹丹懇兮荷休徵。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后大享拜洛樂章 又歸和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5616d09-2763-4ec5-9f72-1eb3992c6bff', '郊廟歌辭 祭方丘樂章 順和', '郊廟歌辞 祭方丘乐章 順和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["坤厚載物，德柔垂祉。","九域咸雍，四溟爲紀。","敬因良節，虔修陰祀。","廣樂式張，靈其降止。"]', '["坤厚載物，德柔垂祉。","九域咸雍，四溟爲紀。","敬因良節，虔修陰祀。","廣乐式張，靈其降止。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祭方丘樂章 順和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c643aeb-d85f-4619-87e5-ba68c9880228', '郊廟歌辭 祭方丘樂章 金奏', '郊廟歌辞 祭方丘乐章 金奏', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["坤元至德，品物資生。","神凝博厚，道協高明。","列鎮五嶽，環流四瀛。","于何不載，萬寶斯成。"]', '["坤元至德，品物資生。","神凝博厚，道協高明。","列鎮五嶽，环流四瀛。","于何不載，万寶斯成。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祭方丘樂章 金奏 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c17456c2-eeda-45aa-a9ae-41981d4dca57', '郊廟歌辭 祭方丘樂章 順和', '郊廟歌辞 祭方丘乐章 順和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["樂備金石，禮光尊俎。","大享爰終，洪休是舉。","雨零感節，雲飛應序。","纓紱載辭，皇靈具舉。"]', '["乐備金石，禮光尊俎。","大享爰終，洪休是舉。","雨零感節，云飞應序。","纓紱載辞，皇靈具舉。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祭方丘樂章 順和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ad5a5b5-d7d7-4678-a728-02e11204bc29', '郊廟歌辭 祭汾陰樂章 順和', '郊廟歌辞 祭汾陰乐章 順和', '92d95179-7b00-4710-8e44-c4cd0464adf0', '唐', '["大樂和暢，殷薦明神。","一降通感，八變必臻。","有求斯應，無德不親。","降靈醉止，休徵萬人。"]', '["大乐和暢，殷薦明神。","一降通感，八变必臻。","有求斯應，無德不親。","降靈醉止，休徵万人。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祭汾陰樂章 順和 林鍾宮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b82134e2-ef7b-41be-be33-96703019de32', '郊廟歌辭 祭汾陰樂章 太簇角', '郊廟歌辞 祭汾陰乐章 太簇角', '1e8f1e33-674e-418a-b3de-0d384def500b', '唐', '["坤元載物，陽樂發生。","播殖資始，品彙咸亨。","列俎棋布，方壇砥平。","神歆禋祀，后德惟明。"]', '["坤元載物，陽乐發生。","播殖資始，品彙咸亨。","列俎棋布，方壇砥平。","神歆禋祀，后德惟明。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祭汾陰樂章 太簇角 盧從愿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5a37461-128d-40ab-ac19-dc2231d5fc61', '郊廟歌辭 祭汾陰樂章 姑洗徵', '郊廟歌辞 祭汾陰乐章 姑洗徵', 'e37bda55-e80e-45af-847e-13c6e480ee30', '唐', '["大君出震，有事郊禋。","齋戒既肅，馨香畢陳。","樂和禮備，候暖風春。","恭惟降福，實賴明神。"]', '["大君出震，有事郊禋。","斋戒既肅，馨香畢陳。","乐和禮備，候暖风春。","恭惟降福，實賴明神。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祭汾陰樂章 姑洗徵 劉晃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce5de9eb-170d-4efc-a629-caf1172d66ab', '郊廟歌辭 祭汾陰樂章 南呂羽', '郊廟歌辞 祭汾陰乐章 南呂羽', '7295782d-8e11-4ef1-909a-fcdc2015fdfa', '唐', '["於穆濬哲，維清緝熙。","肅事昭配，永言孝思。","滌濯靜嘉，馨香在茲。","神之聽之，用受福釐。"]', '["於穆濬哲，維清緝熙。","肅事昭配，永言孝思。","滌濯静嘉，馨香在茲。","神之听之，用受福釐。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祭汾陰樂章 南呂羽 韓休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8d19e39-7b1f-4e69-89b9-65c63ac96963', '郊廟歌辭 祭汾陰樂章 太和', '郊廟歌辞 祭汾陰乐章 太和', '1bde6696-25d3-479f-ba91-c623f7b16eeb', '唐', '["於穆聖皇，六葉重光。","太原刻頌，后土疎場。","寶鼎呈符，歊雲孕祥。","禮樂備矣，降福穰穰。"]', '["於穆聖皇，六葉重光。","太原刻頌，后土疎場。","寶鼎呈符，歊云孕祥。","禮乐備矣，降福穰穰。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祭汾陰樂章 太和 王晙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2ed282e-8ac4-43a9-bc5c-14aa2b39591d', '郊廟歌辭 祭汾陰樂章 肅和', '郊廟歌辞 祭汾陰乐章 肅和', '8c252403-53fe-49c3-9a7e-8648fffebe31', '唐', '["聿修嚴配，展事禋宗。","祥符寶鼎，禮備黃琮。","[祝]詞以信，明德惟聰。","介茲景福，永永無窮。"]', '["聿修嚴配，展事禋宗。","祥符寶鼎，禮備黄琮。","[祝]词以信，明德惟聰。","介茲景福，永永無窮。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祭汾陰樂章 肅和 崔玄童 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c9b601a-649e-4380-8ce3-14e8d40b841f', '郊廟歌辭 祭汾陰樂章 雍和', '郊廟歌辞 祭汾陰乐章 雍和', 'c0242ea8-7b56-403e-8a5c-03f8da1ddade', '唐', '["蠲我饎餴，絜我膋薌。","有豆孔碩，爲羞既臧。","至誠無昧，精意惟芳。","神其醉止，欣欣樂康。"]', '["蠲我饎餴，絜我膋薌。","有豆孔碩，爲羞既臧。","至誠無昧，精意惟芳。","神其醉止，欣欣乐康。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祭汾陰樂章 雍和 賈曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9e54c24-f9ba-454c-872f-356e5bbe0986', '郊廟歌辭 祭汾陰樂章 壽和', '郊廟歌辞 祭汾陰乐章 壽和', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["禮物斯具，樂章乃陳。","誰其作主，皇考聖真。","對越在天，聖明佐神。","窅然汾上，厚澤如春。"]', '["禮物斯具，乐章乃陳。","誰其作主，皇考聖真。","对越在天，聖明佐神。","窅然汾上，厚澤如春。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祭汾陰樂章 壽和 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb7ce140-36ff-4da2-b753-c91987b4aec6', '郊廟歌辭 祭汾陰樂章 舒和', '郊廟歌辞 祭汾陰乐章 舒和', '3638eca4-3c1c-4fb9-956a-4cc6d090ba08', '唐', '["樂奏云闋，禮章載虔。","禋宗於地，昭假於天。","惟馨薦矣，既醉歆焉。","神之降福，永永萬年。"]', '["乐奏云闋，禮章載虔。","禋宗於地，昭假於天。","惟馨薦矣，既醉歆焉。","神之降福，永永万年。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祭汾陰樂章 舒和 何鸞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e263b90b-b39e-4eb7-a648-5f7f2b74db68', '郊廟歌辭 祭汾陰樂章 凱安', '郊廟歌辞 祭汾陰乐章 凱安', '7db52c03-4a80-45fa-b9a7-b36297fc15d9', '唐', '["維歲之吉，維辰之良。","聖君紱冕，肅事壇場。","大禮已備，大樂斯[張]。","神其醉止，降福無疆。"]', '["維歲之吉，維辰之良。","聖君紱冕，肅事壇場。","大禮已備，大乐斯[張]。","神其醉止，降福無疆。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祭汾陰樂章 凱安 蔣挺 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7ba4362-047b-40e8-8a43-17e6a1d93ca2', '郊廟歌辭 祭汾陰樂章 順和', '郊廟歌辞 祭汾陰乐章 順和', 'ea8de934-8013-48e1-a3a9-c819b39d3769', '唐', '["方丘既膳，嘉饗載謐。","齊敬畢誠，陶匏貴質。","秀畢豐薦，芳俎盈實。","永永福流，其昇如日。"]', '["方丘既膳，嘉饗載謐。","齊敬畢誠，陶匏貴質。","秀畢豐薦，芳俎盈實。","永永福流，其昇如日。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祭汾陰樂章 順和 源光裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('089b535d-2b28-486b-b58d-d8a3670c83b2', '郊廟歌辭 禪社首樂章 順和', '郊廟歌辞 禪社首乐章 順和', 'e83d5c63-7639-44b3-89fc-94e55b76e2a5', '唐', '["至哉含柔德，萬物資以生。","常順稱厚載，流謙通變盈。","聖心事能察，增廣陳厥誠。","黃祇僾如在，泰折俟咸亨。"]', '["至哉含柔德，万物資以生。","常順稱厚載，流謙通变盈。","聖心事能察，增廣陳厥誠。","黄祇僾如在，泰折俟咸亨。"]', '诗', 'shi', '', NULL, '郊廟歌辭 禪社首樂章 順和 賀知章、源乾曜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('187bb2c5-4648-43a5-9361-e1b3a8aa65f8', '郊廟歌辭 禪社首樂章 太和', '郊廟歌辞 禪社首乐章 太和', 'e83d5c63-7639-44b3-89fc-94e55b76e2a5', '唐', '["肅我成命，於昭黃祇。","裘冕而祀，陟降在斯。","五音克備，八音聿施。","緝熙肆靖，厥心匪離。"]', '["肅我成命，於昭黄祇。","裘冕而祀，陟降在斯。","五音克備，八音聿施。","緝熙肆靖，厥心匪離。"]', '诗', 'shi', '', NULL, '郊廟歌辭 禪社首樂章 太和 賀知章、源乾曜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22e1c91f-ce17-4cb1-8ea4-b10773525c5c', '郊廟歌辭 禪社首樂章 肅和', '郊廟歌辞 禪社首乐章 肅和', 'e83d5c63-7639-44b3-89fc-94e55b76e2a5', '唐', '["黃祇是[祗]，我其夙夜。","寅畏誠絜，匪遑寧舍。","禮以琮玉，薦厥茅藉。","念茲降康，胡寧克暇。"]', '["黄祇是[祗]，我其夙夜。","寅畏誠絜，匪遑寧舍。","禮以琮玉，薦厥茅藉。","念茲降康，胡寧克暇。"]', '诗', 'shi', '', NULL, '郊廟歌辭 禪社首樂章 肅和 賀知章、源乾曜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3ef6911-ab4b-41fb-9614-1fc519b996d1', '郊廟歌辭 禪社首樂章 雍和', '郊廟歌辞 禪社首乐章 雍和', 'e83d5c63-7639-44b3-89fc-94e55b76e2a5', '唐', '["夙夜宥密，不敢寧宴。","五齊既陳，八音在縣。","粢盛以潔，房俎斯薦。","惟德惟馨，尚茲克徧。"]', '["夙夜宥密，不敢寧宴。","五齊既陳，八音在縣。","粢盛以潔，房俎斯薦。","惟德惟馨，尚茲克徧。"]', '诗', 'shi', '', NULL, '郊廟歌辭 禪社首樂章 雍和 賀知章、源乾曜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e110a26e-5f86-457d-838d-2566c1d9269e', '郊廟歌辭 禪社首樂章 壽和', '郊廟歌辞 禪社首乐章 壽和', 'e83d5c63-7639-44b3-89fc-94e55b76e2a5', '唐', '["惟以明發，有懷載殷。","樂盈而反，禮順其禋。","立清以獻，薦欲是親。","於穆不已，裒對斯臻。"]', '["惟以明發，有懷載殷。","乐盈而反，禮順其禋。","立清以獻，薦欲是親。","於穆不已，裒对斯臻。"]', '诗', 'shi', '', NULL, '郊廟歌辭 禪社首樂章 壽和 賀知章、源乾曜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c19217c-7f07-45f9-b317-3744725dc11c', '郊廟歌辭 禪社首樂章 福和', '郊廟歌辞 禪社首乐章 福和', 'e83d5c63-7639-44b3-89fc-94e55b76e2a5', '唐', '["穆穆天子，告成岱宗。","大裘如濡，執珽有顒。","樂以平志，禮以和容。","上帝臨我，云胡肅邕。"]', '["穆穆天子，告成岱宗。","大裘如濡，執珽有顒。","乐以平志，禮以和容。","上帝臨我，云胡肅邕。"]', '诗', 'shi', '', NULL, '郊廟歌辭 禪社首樂章 福和 賀知章、源乾曜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab812eee-9ec2-43c1-8f1e-98ccbe583ede', '郊廟歌辭 禪社首樂章 太和', '郊廟歌辞 禪社首乐章 太和', 'e83d5c63-7639-44b3-89fc-94e55b76e2a5', '唐', '["昭昭有唐，天俾萬國。","列祖應命，四宗順則。","申錫無疆，宗我同德。","曾孫繼序，享神配極。"]', '["昭昭有唐，天俾万国。","列祖應命，四宗順則。","申錫無疆，宗我同德。","曾孫繼序，享神配極。"]', '诗', 'shi', '', NULL, '郊廟歌辭 禪社首樂章 太和 賀知章、源乾曜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e1af8d7-0b33-4175-b3a3-4ddeebe8703a', '郊廟歌辭 禪社首樂章 靈具醉', '郊廟歌辞 禪社首乐章 靈具醉', 'e83d5c63-7639-44b3-89fc-94e55b76e2a5', '唐', '["靈具醉，杳熙熙。","靈將往，眇禗禗。","顧明德，吐正辭。","爛遺光，流禎祺。"]', '["靈具醉，杳熙熙。","靈將往，眇禗禗。","顧明德，吐正辞。","爛遺光，流禎祺。"]', '诗', 'shi', '', NULL, '郊廟歌辭 禪社首樂章 靈具醉 賀知章、源乾曜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f969fcea-2dd7-4d7b-8257-8f228da97489', '郊廟歌辭 祭神州樂章 肅和', '郊廟歌辞 祭神州乐章 肅和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["大矣坤儀，至哉神縣。","包含日域，牢籠月竁。","露絜三清，風調六變。","皇祇介祉，式歆恭薦。"]', '["大矣坤儀，至哉神縣。","包含日域，牢籠月竁。","露絜三清，风調六变。","皇祇介祉，式歆恭薦。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祭神州樂章 肅和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06d1e418-5974-47f5-9855-5b2976a02345', '郊廟歌辭 祭神州樂章 雍和', '郊廟歌辞 祭神州乐章 雍和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["泰折嚴享，陰郊展敬。","禮以導神，樂以和性。","黝牲在列，黃琮俯暎。","九土既平，萬邦貽慶。"]', '["泰折嚴享，陰郊展敬。","禮以導神，乐以和性。","黝牲在列，黄琮俯暎。","九土既平，万邦貽慶。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祭神州樂章 雍和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad3c4762-ee21-4eaf-a31d-d553075afdfb', '郊廟歌辭 祭神州樂章 舒和', '郊廟歌辞 祭神州乐章 舒和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["坤道降祥和庶品，靈心載德厚羣生。","水土既調三極泰，文武畢備九區平。"]', '["坤道降祥和庶品，靈心載德厚羣生。","水土既調三極泰，文武畢備九區平。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祭神州樂章 舒和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7b4ab4c-0e3f-4fa0-b1e1-09b4e98fc4ac', '郊廟歌辭 祭神州樂章 迎神', '郊廟歌辞 祭神州乐章 迎神', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["黃輿厚載，赤寰歸德。","含育九區，保安萬國。","誠敬無怠，禋祀有則。","樂以迎神，其儀不忒。"]', '["黄輿厚載，赤寰归德。","含育九區，保安万国。","誠敬無怠，禋祀有則。","乐以迎神，其儀不忒。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祭神州樂章 迎神 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d70c3690-62ad-4004-b45e-6bb39c53f844', '郊廟歌辭 祭神州樂章 送神', '郊廟歌辞 祭神州乐章 送神', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["神州陰祀，洪恩廣濟。","草樹霑和，飛沈沐惠。","禮修鼎俎，奠歆瑤幣。","送樂有章，靈軒其逝。"]', '["神州陰祀，洪恩廣濟。","草樹霑和，飞沈沐惠。","禮修鼎俎，奠歆瑤幣。","送乐有章，靈軒其逝。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祭神州樂章 送神 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5d4951c-59b8-4760-986a-7148a540990f', '郊廟歌辭 祭[太]社樂章 肅和', '郊廟歌辞 祭[太]社乐章 肅和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["后土凝德，神功協契。","九域底平，兩儀交際。","戊期應序，陰墉展幣。","靈車少留，俯歆樽桂。"]', '["后土凝德，神功協契。","九域底平，兩儀交際。","戊期應序，陰墉展幣。","靈车少留，俯歆樽桂。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祭[太]社樂章 肅和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e16514b-49db-4319-a118-d8a6e866e300', '郊廟歌辭 祭[太]社樂章 雍和', '郊廟歌辞 祭[太]社乐章 雍和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["美報崇本，嚴恭展事。","受露疎壇，承風啓地。","絜粢登俎，醇犧入饋。","介福遠流，羣生畢遂。"]', '["美報崇本，嚴恭展事。","受露疎壇，承风啓地。","絜粢登俎，醇犧入饋。","介福远流，羣生畢遂。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祭[太]社樂章 雍和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ea3afb2-2d7f-49c2-86d7-f7bc456a95b0', '郊廟歌辭 祭[太]社樂章 舒和', '郊廟歌辞 祭[太]社乐章 舒和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["神道發生敷九稼，陰極乘仁暢八埏。","緯武經文隆景化，登祥薦祉啓豐年。"]', '["神道發生敷九稼，陰極乘仁暢八埏。","緯武經文隆景化，登祥薦祉啓豐年。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祭[太]社樂章 舒和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5d1f782-e5e2-44b0-9b08-7aff1e502a52', '郊廟歌辭 祭大社樂章 迎神', '郊廟歌辞 祭大社乐章 迎神', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["烈山有子，后土有臣。","播種百穀，濟育兆人。","春官緝禮，宗伯司禋。","戊爲吉日，迎享茲辰。"]', '["烈山有子，后土有臣。","播種百穀，濟育兆人。","春官緝禮，宗伯司禋。","戊爲吉日，迎享茲辰。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祭大社樂章 迎神 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24cd0f32-73a5-4845-b3ad-91745863b6c9', '郊廟歌辭 祭大社樂章 送神', '郊廟歌辞 祭大社乐章 送神', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["吉祥式就，酬功載畢。","親地尊天，禮文經術。","貺徵令序，福流初日。","神馭爰歸，祠官其出。"]', '["吉祥式就，酬功載畢。","親地尊天，禮文經術。","貺徵令序，福流初日。","神馭爰归，祠官其出。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祭大社樂章 送神 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8006371c-8fd6-4529-973b-8c10b8b0d68b', '郊廟歌辭 蜡百神樂章 肅和', '郊廟歌辞 蜡百神乐章 肅和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["序迫歲陰，日躔星紀。","爰稽茂典，聿崇清祀。","綺幣霞舒，瑞珪虹起。","百禩垂裕，萬靈薦祉。"]', '["序迫歲陰，日躔星紀。","爰稽茂典，聿崇清祀。","綺幣霞舒，瑞珪虹起。","百禩垂裕，万靈薦祉。"]', '诗', 'shi', '', NULL, '郊廟歌辭 蜡百神樂章 肅和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d441fe0d-554f-42aa-9e65-272f75f506e3', '郊廟歌辭 蜡百神樂章 雍和', '郊廟歌辞 蜡百神乐章 雍和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["緹籥勁序，玄英晚候。","姬蜡開儀，豳歌入奏。","蕙馥雕俎，蘭芬玉酎。","大享明祇，永綏多祐。"]', '["緹籥勁序，玄英晚候。","姬蜡开儀，豳歌入奏。","蕙馥雕俎，蘭芬玉酎。","大享明祇，永綏多祐。"]', '诗', 'shi', '', NULL, '郊廟歌辭 蜡百神樂章 雍和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('743645c1-d6de-4101-8366-5863356dfb22', '郊廟歌辭 蜡百神樂章 舒和', '郊廟歌辞 蜡百神乐章 舒和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["經緯兩儀文化洽，削平方域武功成。","瑤弦自樂乾坤泰，玉鏚長歡區宇寧。"]', '["經緯兩儀文化洽，削平方域武功成。","瑤弦自乐乾坤泰，玉鏚长歡區宇寧。"]', '诗', 'shi', '', NULL, '郊廟歌辭 蜡百神樂章 舒和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bce616a3-7b02-4cbd-a8da-7138e7c8114e', '郊廟歌辭 蜡百神樂章 迎神', '郊廟歌辞 蜡百神乐章 迎神', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["八蜡開祭，萬物合祀。","上極天維，下窮坤紀。","鼎俎流芬，罇彝薦美。","有靈有祇，咸希來止。"]', '["八蜡开祭，万物合祀。","上極天維，下窮坤紀。","鼎俎流芬，罇彝薦美。","有靈有祇，咸希来止。"]', '诗', 'shi', '', NULL, '郊廟歌辭 蜡百神樂章 迎神 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2018c223-52fe-41f5-bdb9-68c152fb4835', '郊廟歌辭 蜡百神樂章 送神', '郊廟歌辞 蜡百神乐章 送神', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["十旬歡洽，一日祠終。","澄彝拂俎，報德酬功。","慮虔容肅，禮縟儀豐。","神其降祉，整馭隨風。"]', '["十旬歡洽，一日祠終。","澄彝拂俎，報德酬功。","慮虔容肅，禮縟儀豐。","神其降祉，整馭隨风。"]', '诗', 'shi', '', NULL, '郊廟歌辭 蜡百神樂章 送神 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f2d62ab-804e-46d4-b5c9-567328452dc4', '郊廟歌辭 享先農樂章 咸和', '郊廟歌辞 享先農乐章 咸和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["粒食伊始，農之所先。","古今攸賴，是曰人天。","耕斯帝籍，播厥公田。","式崇明祀，神其福焉。"]', '["粒食伊始，農之所先。","古今攸賴，是曰人天。","耕斯帝籍，播厥公田。","式崇明祀，神其福焉。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享先農樂章 咸和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be5e396e-7e85-43bd-95e9-b016642f6186', '郊廟歌辭 享先農樂章 肅和', '郊廟歌辞 享先農乐章 肅和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["樽彝既列，瑚簋方薦。","歌工載登，幣禮斯奠。","肅肅享祀，顒顒纓弁。","神之聽之，福流寰縣。"]', '["樽彝既列，瑚簋方薦。","歌工載登，幣禮斯奠。","肅肅享祀，顒顒纓弁。","神之听之，福流寰縣。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享先農樂章 肅和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c509642d-6de2-48b7-89dd-cc55ee3d84a3', '郊廟歌辭 享先農樂章 雍和', '郊廟歌辞 享先農乐章 雍和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["前夕視牲，質明奉俎。","沐芳整弁，其儀式序。","盛禮畢陳，嘉樂備舉。","歆我懿德，非馨稷黍。"]', '["前夕視牲，質明奉俎。","沐芳整弁，其儀式序。","盛禮畢陳，嘉乐備舉。","歆我懿德，非馨稷黍。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享先農樂章 雍和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c8af1df-4b92-4010-b723-32326a23bf82', '郊廟歌辭 享先農樂章 舒和', '郊廟歌辞 享先農乐章 舒和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["羽籥低昂文綴已，干戚蹈厲武行初。","望歲祈農神所聽，延祥介福豈云虛。"]', '["羽籥低昂文綴已，干戚蹈厲武行初。","望歲祈農神所听，延祥介福豈云虛。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享先農樂章 舒和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c59b71b4-9c2a-4ee1-9fa7-385f8fe27ad9', '郊廟歌辭 享先農樂章 咸和', '郊廟歌辞 享先農乐章 咸和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["三推禮就，萬庾祈凝。","夤賓志遠，藨衮惟興。","降歆肅薦，垂祐祗膺。","送神有樂，神其上昇。"]', '["三推禮就，万庾祈凝。","夤賓志远，藨衮惟兴。","降歆肅薦，垂祐祗膺。","送神有乐，神其上昇。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享先農樂章 咸和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2768e7c5-c9dd-4054-8ce2-a0a82e063ba1', '郊廟歌辭 享先蠶樂章 永和', '郊廟歌辞 享先蠶乐章 永和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["芳春開令序，韶苑暢和風。","惟靈申廣祐，利物表神功。","綺會周天宇，黼黻藻寰中。","庶幾承慶節，歆奠下帷宮。"]', '["芳春开令序，韶苑暢和风。","惟靈申廣祐，利物表神功。","綺會周天宇，黼黻藻寰中。","庶幾承慶節，歆奠下帷宮。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享先蠶樂章 永和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21ecddbf-197c-4098-be7b-c79a907408f0', '郊廟歌辭 享先蠶樂章 肅和', '郊廟歌辞 享先蠶乐章 肅和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["明靈光至德，深功掩百神。","祥源應節啓，福緒逐年新。","萬宇承恩覆，七廟佇恭禋。","于茲申至懇，方期遠慶臻。"]', '["明靈光至德，深功掩百神。","祥源應節啓，福緒逐年新。","万宇承恩覆，七廟佇恭禋。","于茲申至懇，方期远慶臻。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享先蠶樂章 肅和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad1c2f33-55e1-410d-a3f1-5d661498c129', '郊廟歌辭 享先蠶樂章 展敬', '郊廟歌辞 享先蠶乐章 展敬', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["霞莊列寶衛，雲集動和聲。","金卮薦綺席，玉幣委芳庭。","因心罄丹款，先己勵蒼生。","所冀延明福，於茲享至誠。"]', '["霞莊列寶衛，云集动和声。","金卮薦綺席，玉幣委芳庭。","因心罄丹款，先己勵蒼生。","所冀延明福，於茲享至誠。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享先蠶樂章 展敬 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95f75391-e77c-421b-9cc0-6b96cc319e1c', '郊廟歌辭 享先蠶樂章 絜誠', '郊廟歌辞 享先蠶乐章 絜誠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["桂筵開玉俎，蘭圃薦瓊芳。","八音調鳳曆，三獻奉鸞觴。","絜粢申大享，庭宇冀降祥。","神其覃有慶，契福永無疆。"]', '["桂筵开玉俎，蘭圃薦瓊芳。","八音調鳳曆，三獻奉鸾觴。","絜粢申大享，庭宇冀降祥。","神其覃有慶，契福永無疆。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享先蠶樂章 絜誠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3df7186e-9419-4cd7-81b0-3f8eafda73e1', '郊廟歌辭 享先蠶樂章 昭慶', '郊廟歌辞 享先蠶乐章 昭慶', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["仙壇禮既畢，神駕儼將昇。","佇屬深祥起，方期庶績凝。","虔誠資宇內，務本勖黎蒸。","靈心昭備享，率土洽休徵。"]', '["仙壇禮既畢，神駕儼將昇。","佇屬深祥起，方期庶績凝。","虔誠資宇內，務本勖黎蒸。","靈心昭備享，率土洽休徵。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享先蠶樂章 昭慶 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fa19c0d-5c19-4494-bcca-e56c3151c36b', '郊廟歌辭 釋奠文宣王樂章 誠和', '郊廟歌辞 釋奠文宣王乐章 誠和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["聖道日用，神幾不測。","金石以陳，弦歌載陟。","爰釋其菜，匪馨于稷。","來顧來享，是宗是極。"]', '["聖道日用，神幾不測。","金石以陳，弦歌載陟。","爰釋其菜，匪馨于稷。","来顧来享，是宗是極。"]', '诗', 'shi', '', NULL, '郊廟歌辭 釋奠文宣王樂章 誠和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8b5b494-9707-4004-8646-caf765ef20b8', '郊廟歌辭 釋奠文宣王樂章 承和', '郊廟歌辞 釋奠文宣王乐章 承和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["萬國以貞光上嗣，三善茂德表重輪。","視膳寢門尊要道，高闢崇賢引正人。"]', '["万国以貞光上嗣，三善茂德表重輪。","視膳寢门尊要道，高闢崇賢引正人。"]', '诗', 'shi', '', NULL, '郊廟歌辭 釋奠文宣王樂章 承和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5c8f884-6a1c-4336-b457-9f84b56797a3', '郊廟歌辭 釋奠文宣王樂章 肅和', '郊廟歌辞 釋奠文宣王乐章 肅和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["粤惟上聖，有縱自天。","傍周萬物，俯應千年。","舊章允著，嘉贄孔虔。","王化茲首，儒風是宣。"]', '["粤惟上聖，有縱自天。","傍周万物，俯應千年。","旧章允著，嘉贄孔虔。","王化茲首，儒风是宣。"]', '诗', 'shi', '', NULL, '郊廟歌辭 釋奠文宣王樂章 肅和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf401a0e-dbe5-49ad-837f-403e55314b41', '郊廟歌辭 釋奠文宣王樂章 雍和', '郊廟歌辞 釋奠文宣王乐章 雍和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["堂獻瑤篚，庭敷璆縣。","禮備其容，樂和其變。","肅肅親享，雍雍執奠。","明德惟馨，蘋蘩可薦。"]', '["堂獻瑤篚，庭敷璆縣。","禮備其容，乐和其变。","肅肅親享，雍雍執奠。","明德惟馨，蘋蘩可薦。"]', '诗', 'shi', '', NULL, '郊廟歌辭 釋奠文宣王樂章 雍和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b5f1748-0c57-4ee8-8e49-980d85ba3fa0', '郊廟歌辭 釋奠文宣王樂章 舒和', '郊廟歌辞 釋奠文宣王乐章 舒和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["隼集龜開昭聖烈，龍蹲鳳跱肅神儀。","尊儒敬業宏圖闡，緯武經文盛德施。"]', '["隼集龟开昭聖烈，龙蹲鳳跱肅神儀。","尊儒敬業宏圖闡，緯武經文盛德施。"]', '诗', 'shi', '', NULL, '郊廟歌辭 釋奠文宣王樂章 舒和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c42c018c-b12b-4cd5-8cda-b3141fdbd036', '郊廟歌辭 享孔子廟樂章 迎神', '郊廟歌辞 享孔子廟乐章 迎神', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["通吳表聖，問老探真。","三千弟子，五百賢人。","億齡規法，萬載嗣禋。","潔誠以祭，奏樂迎神。"]', '["通吳表聖，问老探真。","三千弟子，五百賢人。","億齡規法，万載嗣禋。","潔誠以祭，奏乐迎神。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享孔子廟樂章 迎神 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51112703-7fe7-4e72-afa1-c0f46be39947', '郊廟歌辭 享孔子廟樂章 送神', '郊廟歌辞 享孔子廟乐章 送神', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["醴溢犧象，羞陳俎豆。","魯壁類聞，泗川入覯。","里校覃福，胄筵承祐。","雅樂清音，送神具奏。"]', '["醴溢犧象，羞陳俎豆。","魯壁類闻，泗川入覯。","里校覃福，胄筵承祐。","雅乐清音，送神具奏。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享孔子廟樂章 送神 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07dfbf80-7b02-4ce1-8bf5-db426350aeed', '郊廟歌辭 釋奠武成王樂章 迎神', '郊廟歌辞 釋奠武成王乐章 迎神', '7848102d-1bab-4ecf-91c5-6b13f7e9c511', '唐', '["卜畋不從，兆發非熊。","乃傾荒政，爰佐一戎。","盛烈載垂，命祀惟崇。","日練上戊，宿嚴閟宮。","迎奏嘉至，感而遂通。"]', '["卜畋不從，兆發非熊。","乃傾荒政，爰佐一戎。","盛烈載垂，命祀惟崇。","日練上戊，宿嚴閟宮。","迎奏嘉至，感而遂通。"]', '诗', 'shi', '', NULL, '郊廟歌辭 釋奠武成王樂章 迎神 于邵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06ac6e8f-cc16-4f18-8e80-709cf2282987', '郊廟歌辭 釋奠武成王樂章 奠幣登歌', '郊廟歌辞 釋奠武成王乐章 奠幣登歌', '7848102d-1bab-4ecf-91c5-6b13f7e9c511', '唐', '["管磬升，羶薌集。","上公進，嘉幣執。","信以通，僾如及。","恢帝功，錫后邑。","四維張，百度立。","綿億載，邈難挹。"]', '["管磬升，羶薌集。","上公進，嘉幣執。","信以通，僾如及。","恢帝功，錫后邑。","四維張，百度立。","綿億載，邈难挹。"]', '诗', 'shi', '', NULL, '郊廟歌辭 釋奠武成王樂章 奠幣登歌 于邵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9d3edd9-a17c-47ce-b299-241f611917cd', '郊廟歌辭 釋奠武成王樂章 迎俎酌獻', '郊廟歌辞 釋奠武成王乐章 迎俎酌獻', '7848102d-1bab-4ecf-91c5-6b13f7e9c511', '唐', '["五齊潔，九牢碩。","梡橛循，罍斝滌。","進具物，揚鴻績。","和奏發，高靈寂。","虔告終，繁祉錫。","昭秩祀，永無易。"]', '["五齊潔，九牢碩。","梡橛循，罍斝滌。","進具物，揚鴻績。","和奏發，高靈寂。","虔告終，繁祉錫。","昭秩祀，永無易。"]', '诗', 'shi', '', NULL, '郊廟歌辭 釋奠武成王樂章 迎俎酌獻 于邵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12ec2d0d-8a04-46d8-873b-b3ed0b88b4d8', '郊廟歌辭 釋奠武成王樂章 亞獻終獻', '郊廟歌辞 釋奠武成王乐章 亞獻終獻', '7848102d-1bab-4ecf-91c5-6b13f7e9c511', '唐', '["貳觴以獻，三變其終。","顧此非馨，尚達斯衷。","茅縮可致，神歆載融。","始神翊周，拯溺除凶。","時維降祐，永絕興戎。"]', '["貳觴以獻，三变其終。","顧此非馨，尚達斯衷。","茅縮可致，神歆載融。","始神翊周，拯溺除凶。","时維降祐，永絕兴戎。"]', '诗', 'shi', '', NULL, '郊廟歌辭 釋奠武成王樂章 亞獻終獻 于邵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdd061fc-2394-4fa9-8664-3adf4f36da02', '郊廟歌辭 釋奠武成王樂章 送神', '郊廟歌辞 釋奠武成王乐章 送神', '7848102d-1bab-4ecf-91c5-6b13f7e9c511', '唐', '["明祀方終，備樂斯闋。","黝纁就瘞，豆籩告撤。","肸蠁尚餘，光景云滅。","返歸虛極，神心則悅。"]', '["明祀方終，備乐斯闋。","黝纁就瘞，豆籩告撤。","肸蠁尚餘，光景云滅。","返归虛極，神心則悅。"]', '诗', 'shi', '', NULL, '郊廟歌辭 釋奠武成王樂章 送神 于邵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b01eb82d-f629-456b-ba87-1573a9bfadd8', '郊廟歌辭 享龍池樂章 第一章', '郊廟歌辞 享龙池乐章 第一章', '824609f5-419a-4fe3-ac98-159c5bc9931d', '唐', '["恭聞帝里生靈沼，應報明君鼎業新。","既協翠泉光寶命，還符白水出真人。","此時舜海潛龍躍，此地堯河帶馬巡。","獨有前池一小雁，叨承舊惠入天津。"]', '["恭闻帝里生靈沼，應報明君鼎業新。","既協翠泉光寶命，還符白水出真人。","此时舜海潛龙躍，此地堯河带马巡。","独有前池一小雁，叨承旧惠入天津。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享龍池樂章 第一章 姚崇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a39a755-afc4-4c50-95d7-49c2edf85494', '郊廟歌辭 享龍池樂章 第二章', '郊廟歌辞 享龙池乐章 第二章', '41885324-7aab-40d5-9f60-d2d3a49f5ea3', '唐', '["帝宅王家大道邊，神馬龍龜涌聖泉。","昔日昔時經此地，看來看去漸成川。","歌臺舞榭宜正月，柳岸梅洲勝往年。","莫言波上春雲少，祗爲從龍直上天。"]', '["帝宅王家大道邊，神马龙龟涌聖泉。","昔日昔时經此地，看来看去漸成川。","歌台舞榭宜正月，柳岸梅洲勝往年。","莫言波上春云少，祗爲從龙直上天。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享龍池樂章 第二章 蔡孚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d291f734-2ec4-4eed-9c5e-8f14c4d11921', '郊廟歌辭 享龍池樂章 第三章', '郊廟歌辞 享龙池乐章 第三章', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["龍池躍龍龍已飛，龍德[光]天天不違。","池開天漢分黃道，龍向天門入紫微。","邸第樓臺多氣色，君王鳧雁有光輝。","爲報寰中百川水，來朝此地莫東歸。"]', '["龙池躍龙龙已飞，龙德[光]天天不違。","池开天漢分黄道，龙向天门入紫微。","邸第楼台多氣色，君王鳧雁有光輝。","爲報寰中百川水，来朝此地莫东归。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享龍池樂章 第三章 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a201161-2e55-4ad6-a9ff-8db614d1cd00', '郊廟歌辭 享龍池樂章 第四章', '郊廟歌辞 享龙池乐章 第四章', '4ed8f683-7f3d-40a7-ab93-0b9fc01daca4', '唐', '["代邸東南龍躍泉，清漪碧浪遠浮天。","樓臺影就波中出，日月光疑鏡裏懸。","雁沼回流成舜海，龜書薦祉應堯年。","大川既濟慙爲檝，報德空思奉細涓。"]', '["代邸东南龙躍泉，清漪碧浪远浮天。","楼台影就波中出，日月光疑镜裏懸。","雁沼回流成舜海，龟书薦祉應堯年。","大川既濟慙爲檝，報德空思奉細涓。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享龍池樂章 第四章 盧懷慎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('037a76e5-2949-43de-850c-5bf8f5010ffd', '郊廟歌辭 享龍池樂章 第五章', '郊廟歌辞 享龙池乐章 第五章', '8d472220-48a8-47cb-8921-181c3be51277', '唐', '["龍池初出此龍山，常經此地謁龍顏。","日日芙蓉生夏水，年年楊柳變春灣。","堯壇寶匣餘煙霧，舜海漁舟尚往還。","願似飄颻五雲影，從來從去九天間。"]', '["龙池初出此龙山，常經此地謁龙顏。","日日芙蓉生夏水，年年楊柳变春灣。","堯壇寶匣餘煙霧，舜海漁舟尚往還。","願似飄颻五云影，從来從去九天间。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享龍池樂章 第五章 姜皎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e38b8c76-9f0b-484c-8791-34340abf20b1', '郊廟歌辭 享龍池樂章 第六章', '郊廟歌辞 享龙池乐章 第六章', 'b93f3304-6cb5-42e4-923f-9928d32ae301', '唐', '["龍興白水漢興符，聖主時乘運斗樞。","岸上丰茸五花樹，波中的皪千金珠。","操環昔聞迎夏啓，發匣先來瑞有虞。","風色雲光隨隱見，赤雲神化象江湖。"]', '["龙兴白水漢兴符，聖主时乘運斗樞。","岸上丰茸五花樹，波中的皪千金珠。","操环昔闻迎夏啓，發匣先来瑞有虞。","风色云光隨隐见，赤云神化象江湖。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享龍池樂章 第六章 崔日用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53bfd457-c415-4a5e-8022-547f6d3ee63e', '郊廟歌辭 享龍池樂章 第七章', '郊廟歌辞 享龙池乐章 第七章', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["西京鳳邸躍龍泉，佳氣休光鎮在天。","軒后霧圖今已得，秦王水劒昔常傳。","恩魚不似昆明釣，瑞鶴長如太液仙。","願侍巡游同舊里，更聞簫鼓濟樓船。"]', '["西京鳳邸躍龙泉，佳氣休光鎮在天。","軒后霧圖今已得，秦王水劒昔常傳。","恩鱼不似昆明釣，瑞鹤长如太液仙。","願侍巡游同旧里，更闻簫鼓濟楼船。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享龍池樂章 第七章 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('139c0bdc-57df-43ea-ab82-7f9db95554cf', '郊廟歌辭 享龍池樂章 第八章', '郊廟歌辞 享龙池乐章 第八章', '2e44fdde-7c3b-46a4-abf2-84f9ebdef55e', '唐', '["星分邑里四人居，水洊源流萬頃餘。","魏國君王稱象處，晉家藩邸化龍初。","青蒲暫似遊梁馬，綠藻還疑宴鎬魚。","自有神靈滋液地，年年雲物史官書。"]', '["星分邑里四人居，水洊源流万頃餘。","魏国君王稱象处，晉家藩邸化龙初。","青蒲暫似游梁马，綠藻還疑宴鎬鱼。","自有神靈滋液地，年年云物史官书。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享龍池樂章 第八章 李乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a05c8f5-0bdb-494b-bb42-7a780b603745', '郊廟歌辭 享龍池樂章 第九章', '郊廟歌辞 享龙池乐章 第九章', '8d472220-48a8-47cb-8921-181c3be51277', '唐', '["靈沼縈迴邸第前，浴日涵天寫曙天。","始見龍臺昇鳳闕，應如霄漢起神泉。","石匱渚傍還啓聖，桃李初生更有仙。","欲化帝圖從此受，正同河變一千年。"]', '["靈沼縈迴邸第前，浴日涵天寫曙天。","始见龙台昇鳳闕，應如霄漢起神泉。","石匱渚傍還啓聖，桃李初生更有仙。","欲化帝圖從此受，正同河变一千年。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享龍池樂章 第九章 姜皎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3f5fd27-c2a3-4007-9a52-21ac2aca7644', '郊廟歌辭 享龍池樂章 第十章', '郊廟歌辞 享龙池乐章 第十章', '8b8b6881-37e1-48f6-b9c0-fe2aace221a1', '唐', '["乾坤啓聖吐龍泉，泉水年年勝一年。","始看魚躍方成海，即覩龍飛利在天。","洲渚遙將銀漢接，樓臺直與紫微連。","休氣榮光常不散，懸知此地是神仙。"]', '["乾坤啓聖吐龙泉，泉水年年勝一年。","始看鱼躍方成海，即覩龙飞利在天。","洲渚遙將銀漢接，楼台直與紫微連。","休氣榮光常不散，懸知此地是神仙。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享龍池樂章 第十章 裴璀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c6f3aee-8862-4281-92f2-c963a5fdebef', '郊廟歌辭 享太廟樂章 永和', '郊廟歌辞 享太廟乐章 永和', '3a8df6b1-94e0-4ab3-9b71-775c9be50325', '唐', '["於穆烈祖，弘此丕基。","永言配命，子孫保之。","百神既洽，萬國在茲。","是用孝享，神其格思。"]', '["於穆烈祖，弘此丕基。","永言配命，子孫保之。","百神既洽，万国在茲。","是用孝享，神其格思。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 永和 魏徵、褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9eee091a-7070-4989-b87a-7c2f6dd4b20d', '郊廟歌辭 享太廟樂章 肅和', '郊廟歌辞 享太廟乐章 肅和', '3a8df6b1-94e0-4ab3-9b71-775c9be50325', '唐', '["大哉至德，允茲明聖。","格于上下，聿遵誠敬。","嘉樂斯登，鳴球以詠。","神其降止，式隆景命。"]', '["大哉至德，允茲明聖。","格于上下，聿遵誠敬。","嘉乐斯登，鳴球以詠。","神其降止，式隆景命。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 肅和 魏徵、褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b1a491d-c0c1-4ac2-9643-2f598cee7f77', '郊廟歌辭 享太廟樂章 雍和', '郊廟歌辞 享太廟乐章 雍和', '3a8df6b1-94e0-4ab3-9b71-775c9be50325', '唐', '["崇茲享祀，誠敬兼至。","樂以感靈，禮以昭事。","粢盛咸絜，牲牷孔備。","永言孝思，庶幾不匱。"]', '["崇茲享祀，誠敬兼至。","乐以感靈，禮以昭事。","粢盛咸絜，牲牷孔備。","永言孝思，庶幾不匱。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 雍和 魏徵、褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62ac1952-e0f1-4935-8e06-9d8f9f72bb6f', '郊廟歌辭 享太廟樂章 長發舞', '郊廟歌辞 享太廟乐章 长發舞', '3a8df6b1-94e0-4ab3-9b71-775c9be50325', '唐', '["睿哲維唐，長發其祥。","帝命斯祐，王業克昌。","配天載德，就日重光。","本支百代，申錫無疆。"]', '["睿哲維唐，长發其祥。","帝命斯祐，王業克昌。","配天載德，就日重光。","本支百代，申錫無疆。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 長發舞 魏徵、褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8e2aabe-4e9c-4a5d-8f4a-299d7f6624e7', '郊廟歌辭 享太廟樂章 大基舞', '郊廟歌辞 享太廟乐章 大基舞', '3a8df6b1-94e0-4ab3-9b71-775c9be50325', '唐', '["猗與祖業，皇矣帝先。","翦商德厚，封唐慶延。","在姬猶稷，方晉喻宣。","基我鼎運，於萬斯年。"]', '["猗與祖業，皇矣帝先。","翦商德厚，封唐慶延。","在姬猶稷，方晉喻宣。","基我鼎運，於万斯年。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 大基舞 魏徵、褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da2fb201-1711-47f6-9858-6a1b6fc753c6', '郊廟歌辭 享太廟樂章 大成舞', '郊廟歌辞 享太廟乐章 大成舞', '3a8df6b1-94e0-4ab3-9b71-775c9be50325', '唐', '["周稱王季，晉美帝文。","明明盛德，穆穆齊芬。","藏用四履，屈道三分。","鏗鏘鍾石，載紀鴻勳。"]', '["周稱王季，晉美帝文。","明明盛德，穆穆齊芬。","藏用四履，屈道三分。","鏗鏘鍾石，載紀鴻勳。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 大成舞 魏徵、褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc517fb4-afe5-4836-82dd-4b05d9a66851', '郊廟歌辭 享太廟樂章 大明舞', '郊廟歌辞 享太廟乐章 大明舞', '3a8df6b1-94e0-4ab3-9b71-775c9be50325', '唐', '["五紀更運，三正遞升。","勛華既沒，禹湯勃興。","神武命代，靈睠是膺。","望雲彰德，察緯告徵。","上紐天維，下安地軸。","徵師涿野，萬國咸服。","偃伯靈臺，九官允穆。","殊域委賮，懷生介福。","大禮既飾，大樂已和。","黑章擾囿，赤字浮河。","功宣載籍，德被詠歌。","克昌厥後，百祿是荷。"]', '["五紀更運，三正遞升。","勛华既沒，禹湯勃兴。","神武命代，靈睠是膺。","望云彰德，察緯告徵。","上紐天維，下安地軸。","徵師涿野，万国咸服。","偃伯靈台，九官允穆。","殊域委賮，懷生介福。","大禮既飾，大乐已和。","黑章擾囿，赤字浮河。","功宣載籍，德被詠歌。","克昌厥後，百祿是荷。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 大明舞 魏徵、褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3cb5d89-401f-42ca-8694-6e30d10c049c', '郊廟歌辭 享太廟樂章 壽和', '郊廟歌辞 享太廟乐章 壽和', '3a8df6b1-94e0-4ab3-9b71-775c9be50325', '唐', '["八音斯奏，三獻畢陳。","寶祚惟永，暉光日新。"]', '["八音斯奏，三獻畢陳。","寶祚惟永，暉光日新。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 壽和 魏徵、褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b75f9864-ebbc-4b6c-8758-9a8e4fb27d05', '郊廟歌辭 享太廟樂章 舒和', '郊廟歌辞 享太廟乐章 舒和', '3a8df6b1-94e0-4ab3-9b71-775c9be50325', '唐', '["聖敬通神光七廟，靈心薦祚和萬方。","嚴禋克配鴻基遠，明德惟馨鳳曆昌。"]', '["聖敬通神光七廟，靈心薦祚和万方。","嚴禋克配鴻基远，明德惟馨鳳曆昌。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 舒和 魏徵、褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3776e703-3ed3-4c65-95ea-62eed3e929c0', '郊廟歌辭 享太廟樂章 雍和', '郊廟歌辞 享太廟乐章 雍和', '3a8df6b1-94e0-4ab3-9b71-775c9be50325', '唐', '["於穆清廟，聿修嚴祀。","四縣載陳，三獻斯止。","籩豆徹薦，人祇介祉。","神維格思，錫祚不已。"]', '["於穆清廟，聿修嚴祀。","四縣載陳，三獻斯止。","籩豆徹薦，人祇介祉。","神維格思，錫祚不已。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 雍和 魏徵、褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('433e5a5c-0e39-419f-8ef5-e672dd4f56af', '郊廟歌辭 享太廟樂章 永和', '郊廟歌辞 享太廟乐章 永和', '3a8df6b1-94e0-4ab3-9b71-775c9be50325', '唐', '["肅肅清祀，烝烝孝思。","薦享昭備，虔恭在茲。","雍歌徹俎，祝嘏陳辭。","用光武志，永固鴻基。"]', '["肅肅清祀，烝烝孝思。","薦享昭備，虔恭在茲。","雍歌徹俎，祝嘏陳辞。","用光武志，永固鴻基。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 永和 魏徵、褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('064b1fa2-3649-4b01-a0c0-4bc73c9d8a89', '郊廟歌辭 享太廟樂章 崇德舞', '郊廟歌辞 享太廟乐章 崇德舞', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["五運改卜，千齡啓聖。","彤雲曉聚，黃星夜映。","葉闡珠囊，基開玉鏡。","下臨萬宇，上齊七政。","霧開三象，塵清九服。","海溓星暉，遠安邇肅。","天地交泰，華夷輯睦。","翔泳歸仁，中外禔福。","績踰黜夏，勳高翦商。","武陳七德，刑設三章。","祥禽巢閣，仁獸遊梁。","卜年惟永，景福無疆。"]', '["五運改卜，千齡啓聖。","彤云晓聚，黄星夜映。","葉闡珠囊，基开玉镜。","下臨万宇，上齊七政。","霧开三象，塵清九服。","海溓星暉，远安邇肅。","天地交泰，华夷輯睦。","翔泳归仁，中外禔福。","績踰黜夏，勳高翦商。","武陳七德，刑設三章。","祥禽巢閣，仁獸游梁。","卜年惟永，景福無疆。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 崇德舞 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bad3700c-fcfe-4096-a11b-1ba4c67a66fe', '郊廟歌辭 享太廟樂章 鈞天[舞]', '郊廟歌辞 享太廟乐章 鈞天[舞]', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["承天撫籙，纂聖登皇。","遐清萬宇，仰協三光。","功成日用，道濟時康。","璇圖載永，寶曆斯昌。","日月揚暉，煙雲爛色。","河嶽修貢，神祇効職。","舜風攸偃，堯曦先就。","睿感通寰，孝思浹宙。","奉揚先德，虔遵曩狩。","展義天扄，飛英雲岫。","化逸王表，神凝帝先。","乘雲厭俗，馭日登玄。"]', '["承天撫籙，纂聖登皇。","遐清万宇，仰協三光。","功成日用，道濟时康。","璇圖載永，寶曆斯昌。","日月揚暉，煙云爛色。","河嶽修貢，神祇効職。","舜风攸偃，堯曦先就。","睿感通寰，孝思浹宙。","奉揚先德，虔遵曩狩。","展義天扄，飞英云岫。","化逸王表，神凝帝先。","乘云厭俗，馭日登玄。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 鈞天[舞] 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26d7dd17-808c-4735-93d1-e74127c33838', '郊廟歌辭 享太廟樂章 太和舞', '郊廟歌辞 享太廟乐章 太和舞', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["廣樂既備，嘉薦既新。","述先惟德，孝饗惟親。","七獻具舉，五齊畢陳。","錫茲祚福，於萬斯春。"]', '["廣乐既備，嘉薦既新。","述先惟德，孝饗惟親。","七獻具舉，五齊畢陳。","錫茲祚福，於万斯春。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 太和舞 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f53dcca3-2e68-4719-a490-eb845dd6bb79', '郊廟歌辭 享太廟樂章 景雲舞', '郊廟歌辞 享太廟乐章 景云舞', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["惟睿作聖，惟聖登皇。","精感耀魄，時膺會昌。","舜慙大孝，堯推讓王。","能事斯極，振古誰方。","文明履運，車書同軌。","巍巍赫赫，盡善盡美。","衢室凝旒，大庭端扆。","釋負之寄，事光復子。","脫屣高天，登遐上玄。","龍湖超忽，象野芊綿。","遊衣復道，薦果初年。","新廟奕奕，明德配天。"]', '["惟睿作聖，惟聖登皇。","精感耀魄，时膺會昌。","舜慙大孝，堯推讓王。","能事斯極，振古誰方。","文明履運，车书同軌。","巍巍赫赫，尽善尽美。","衢室凝旒，大庭端扆。","釋負之寄，事光复子。","脫屣高天，登遐上玄。","龙湖超忽，象野芊綿。","游衣复道，薦果初年。","新廟奕奕，明德配天。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 景雲舞 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5fc1717-a9ac-45d4-bab0-7a54ec6e831e', '郊廟歌辭 享太廟樂章 光大舞', '郊廟歌辞 享太廟乐章 光大舞', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["大業龍祉，徽音駿尊。","潛居皇德，赫嗣天昆。","展儀宗祖，重誠孝孫。","春秋無極，享奏存存。"]', '["大業龙祉，徽音駿尊。","潛居皇德，赫嗣天昆。","展儀宗祖，重誠孝孫。","春秋無極，享奏存存。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 光大舞 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70baddd6-6128-41d4-bc8c-a409dd9a9939', '郊廟歌辭 享太廟樂章 迎神', '郊廟歌辞 享太廟乐章 迎神', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["七廟觀德，百靈攸仰。","俗荷財成，物資含養。","道光執契，化籠提象。","肅肅雍雍，神其來饗。"]', '["七廟观德，百靈攸仰。","俗荷財成，物資含養。","道光執契，化籠提象。","肅肅雍雍，神其来饗。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 迎神 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15e0461a-bd33-4197-8613-4c7adffe3fdd', '郊廟歌辭 享太廟樂章 金奏', '郊廟歌辞 享太廟乐章 金奏', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["肅肅清廟，巍巍盛唐。","配天立極，累聖重光。","樂和管磬，禮備烝嘗。","永惟來格，降福無疆。"]', '["肅肅清廟，巍巍盛唐。","配天立極，累聖重光。","乐和管磬，禮備烝嘗。","永惟来格，降福無疆。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 金奏 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ddd9228-e9ac-4ff1-b20c-79781d3deb46', '郊廟歌辭 享太廟樂章 送神', '郊廟歌辞 享太廟乐章 送神', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["五聲備奏，三獻終祠。","車移鳳輦，斾轉虹旗。","禮周籩豆，誠效虔祗。","皇靈徙蹕，簪紳拜辭。"]', '["五声備奏，三獻終祠。","车移鳳輦，斾轉虹旗。","禮周籩豆，誠效虔祗。","皇靈徙蹕，簪紳拜辞。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 送神 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98bed82f-528d-4a70-8d97-8f88e60ac3ba', '郊廟歌辭 武后享清廟樂章十首 第一', '郊廟歌辞 武后享清廟乐章十首 第一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["建清廟，贊玄功。","擇吉日，展禋宗。","樂已變，禮方崇。","望神駕，降仙宮。"]', '["建清廟，贊玄功。","擇吉日，展禋宗。","乐已变，禮方崇。","望神駕，降仙宮。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后享清廟樂章十首 第一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e914ab85-d5bb-4eb3-b564-1bc211fcc195', '郊廟歌辭 武后享清廟樂章十首 第二', '郊廟歌辞 武后享清廟乐章十首 第二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["隆周創業，寶命惟新。","敬宗茂典，爰表虔禋。","聲明已備，文物斯陳。","肅容如在，懇志方申。"]', '["隆周創業，寶命惟新。","敬宗茂典，爰表虔禋。","声明已備，文物斯陳。","肅容如在，懇志方申。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后享清廟樂章十首 第二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7909de1-2799-4b1d-8a64-e43d75deebd0', '郊廟歌辭 武后享清廟樂章十首 第三登歌', '郊廟歌辞 武后享清廟乐章十首 第三登歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["肅敷大禮，上謁尊靈。","敬[陳]筐幣，載表丹誠。"]', '["肅敷大禮，上謁尊靈。","敬[陳]筐幣，載表丹誠。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后享清廟樂章十首 第三登歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb8e35db-a91a-46ca-8cde-7864b5e5e249', '郊廟歌辭 武后享清廟樂章十首 第四迎神', '郊廟歌辞 武后享清廟乐章十首 第四迎神', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["敬奠蘋藻，式罄虔襟。","潔誠斯展，佇降靈歆。"]', '["敬奠蘋藻，式罄虔襟。","潔誠斯展，佇降靈歆。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后享清廟樂章十首 第四迎神 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38382709-1d0a-416c-8071-b1d0705ca4d1', '郊廟歌辭 武后享清廟樂章十首 第五飲福', '郊廟歌辞 武后享清廟乐章十首 第五饮福', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["爰陳玉醴，式奠瓊漿。","靈心有穆，介福無疆。"]', '["爰陳玉醴，式奠瓊漿。","靈心有穆，介福無疆。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后享清廟樂章十首 第五飲福 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea6a860c-43d0-4c40-8d6f-e1d3c863dcea', '郊廟歌辭 武后享清廟樂章十首 第六送文舞', '郊廟歌辞 武后享清廟乐章十首 第六送文舞', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["帝圖草創，皇業初開。","功高佐命，業贊雲雷。"]', '["帝圖草創，皇業初开。","功高佐命，業贊云雷。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后享清廟樂章十首 第六送文舞 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7723360-2a50-4f62-a869-ed07e01c7fab', '郊廟歌辭 武后享清廟樂章十首 第七迎武舞', '郊廟歌辞 武后享清廟乐章十首 第七迎武舞', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["赫赫玄功被穹壤，皇皇至德洽生靈。","開基撥亂妖氛廓，佐命宣威海內清。"]', '["赫赫玄功被穹壤，皇皇至德洽生靈。","开基撥亂妖氛廓，佐命宣威海內清。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后享清廟樂章十首 第七迎武舞 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75e066a5-dabc-422d-aac7-938ea029d94d', '郊廟歌辭 武后享清廟樂章十首 第八武舞作', '郊廟歌辞 武后享清廟乐章十首 第八武舞作', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["荷恩承顧託，執契恭臨撫。","廟畧靜邊荒，天兵耀神武。"]', '["荷恩承顧託，執契恭臨撫。","廟畧静邊荒，天兵耀神武。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后享清廟樂章十首 第八武舞作 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f80db8d-44da-4956-b07c-bea189de0ed9', '郊廟歌辭 武后享清廟樂章十首 第九徹俎', '郊廟歌辞 武后享清廟乐章十首 第九徹俎', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["登歌已闋，獻禮方周。","欽承景福，肅奉鴻休。"]', '["登歌已闋，獻禮方周。","欽承景福，肅奉鴻休。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后享清廟樂章十首 第九徹俎 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8b7d321-7dcc-493e-9260-84086c5a508c', '郊廟歌辭 武后享清廟樂章十首 第十送神', '郊廟歌辞 武后享清廟乐章十首 第十送神', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["大禮言畢，仙衛將歸。","莫申丹懇，空瞻紫微。"]', '["大禮言畢，仙衛將归。","莫申丹懇，空瞻紫微。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后享清廟樂章十首 第十送神 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7da09dfe-a023-474e-a933-14a6cf6ed39c', '郊廟歌辭 享太廟樂章 嚴和', '郊廟歌辞 享太廟乐章 嚴和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["肅肅清廟，赫赫玄猷。","功高萬古，化奄十洲。","中興丕業，上荷天休。","祗奉先構，禮備懷柔。"]', '["肅肅清廟，赫赫玄猷。","功高万古，化奄十洲。","中兴丕業，上荷天休。","祗奉先構，禮備懷柔。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 嚴和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea23a406-f7b4-4b25-8e27-9501c2483202', '郊廟歌辭 享太廟樂章 昇和', '郊廟歌辞 享太廟乐章 昇和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["顧惟菲薄，纂曆應期。","中外同軌，夷狄來思。","樂用崇德，禮以陳詞。","夕惕若厲，欽奉弘基。"]', '["顧惟菲薄，纂曆應期。","中外同軌，夷狄来思。","乐用崇德，禮以陳词。","夕惕若厲，欽奉弘基。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 昇和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c4735fa-2ede-4cca-8df1-0273f4c0737d', '郊廟歌辭 享太廟樂章 虔和', '郊廟歌辞 享太廟乐章 虔和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["禮標薦鬯，肅事祠庭。","敬申如在，敢託非馨。"]', '["禮標薦鬯，肅事祠庭。","敬申如在，敢託非馨。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 虔和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75293dd7-7569-4a09-afb9-fdb93ba281cf', '郊廟歌辭 享太廟樂章 歆和', '郊廟歌辞 享太廟乐章 歆和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["崇禋已備，粢盛聿修。","潔誠斯展，鍾石方遒。"]', '["崇禋已備，粢盛聿修。","潔誠斯展，鍾石方遒。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 歆和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e91f9b08-9363-4065-a6bb-53eb8616e245', '郊廟歌辭 享太廟樂章 承光舞', '郊廟歌辞 享太廟乐章 承光舞', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["金相載穆，玉裕重輝。","養德清禁，承光紫微。","乾宮候色，震象增威。","監國方永，賓天不歸。","孝友自衷，溫文性與。","龍樓正啓，鶴駕斯舉。","丹扆流念，鴻名式序。","中興考室，永陳彝俎。"]', '["金相載穆，玉裕重輝。","養德清禁，承光紫微。","乾宮候色，震象增威。","監国方永，賓天不归。","孝友自衷，溫文性與。","龙楼正啓，鹤駕斯舉。","丹扆流念，鴻名式序。","中兴考室，永陳彝俎。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 承光舞 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('248b95f0-07f4-49d9-a8e5-307ce68fcecf', '郊廟歌辭 享太廟樂章 延和', '郊廟歌辞 享太廟乐章 延和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["巍巍累聖，穆穆重光。","奄有區夏，祚啓隆唐。","百蠻飲澤，萬國來王。","本枝億載，鼎祚逾長。"]', '["巍巍累聖，穆穆重光。","奄有區夏，祚啓隆唐。","百蠻饮澤，万国来王。","本枝億載，鼎祚逾长。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 延和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e25e2a4-0a40-4306-86dd-43430565e2b5', '郊廟歌辭 享太廟樂章 同和', '郊廟歌辞 享太廟乐章 同和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["惟聖配天敷盛禮，惟天爲大闡洪名。","恭禋展敬光先德，蘋藻申虔表志誠。"]', '["惟聖配天敷盛禮，惟天爲大闡洪名。","恭禋展敬光先德，蘋藻申虔表志誠。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 同和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f8cb180-b645-4c8f-b36c-6c4476315524', '郊廟歌辭 享太廟樂章 寧和', '郊廟歌辞 享太廟乐章 寧和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["炎馭失天綱，土德承天命。","英猷被寰宇，懿躅隆邦政。","七德已綏邊，九夷咸底定。","景化覃遐邇，深仁洽翔泳。"]', '["炎馭失天綱，土德承天命。","英猷被寰宇，懿躅隆邦政。","七德已綏邊，九夷咸底定。","景化覃遐邇，深仁洽翔泳。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 寧和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02418954-7744-4232-8de7-4d325a86d757', '郊廟歌辭 享太廟樂章 恭和', '郊廟歌辞 享太廟乐章 恭和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["禮周三獻，樂闋九成。","肅承靈福，悚惕兼盈。"]', '["禮周三獻，乐闋九成。","肅承靈福，悚惕兼盈。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 恭和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77791732-5f87-4b20-9122-16e82321d122', '郊廟歌辭 享太廟樂章 通和', '郊廟歌辞 享太廟乐章 通和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["祠容既畢，仙座爰興。","停停鳳舉，靄靄雲昇。","長隆寶運，永錫休徵。","福覃貽厥，恩被黎蒸。"]', '["祠容既畢，仙座爰兴。","停停鳳舉，靄靄云昇。","长隆寶運，永錫休徵。","福覃貽厥，恩被黎蒸。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 通和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e96ad31-cda7-4e55-b32d-e64ec3ea876b', '郊廟歌辭 享太廟樂章 昭和', '郊廟歌辞 享太廟乐章 昭和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["道洽二儀交泰，時休四宇和平。","環珮肅於庭實，鍾石揚乎頌聲。"]', '["道洽二儀交泰，时休四宇和平。","环珮肅於庭實，鍾石揚乎頌声。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 昭和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b639cc5-5c54-46ca-95ee-ba9ec02726aa', '郊廟歌辭 享太廟樂章 誠敬', '郊廟歌辞 享太廟乐章 誠敬', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["顧惟菲質，忝位椒宮。","虔奉蘋藻，肅事神宗。","敢申誠絜，庶罄深衷。","睟容有裕，靈享無窮。"]', '["顧惟菲質，忝位椒宮。","虔奉蘋藻，肅事神宗。","敢申誠絜，庶罄深衷。","睟容有裕，靈享無窮。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 誠敬 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47211b3f-f590-48eb-bd73-b92297761131', '郊廟歌辭 享太廟樂章 肅和', '郊廟歌辞 享太廟乐章 肅和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["月禮已周，雲和將變。","爰獻其醑，載遷其奠。","明德逾隆，非馨是薦。","澤霑動植，仁覃宇縣。"]', '["月禮已周，云和將变。","爰獻其醑，載遷其奠。","明德逾隆，非馨是薦。","澤霑动植，仁覃宇縣。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 肅和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bac63ce9-8353-4527-bde9-a8ed8152df49', '郊廟歌辭 享太廟樂章 昭感', '郊廟歌辞 享太廟乐章 昭感', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["鏗鏘韶濩，肅穆神容。","洪規赫赫，祠典雍雍。","已周三獻，將乘六龍。","虔誠有託，懇志無從。"]', '["鏗鏘韶濩，肅穆神容。","洪規赫赫，祠典雍雍。","已周三獻，將乘六龙。","虔誠有託，懇志無從。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 昭感 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('712d4015-f37f-4b13-9445-f14daa6586fd', '郊廟歌辭 享太廟樂章 永和三章 一', '郊廟歌辞 享太廟乐章 永和三章 一', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["肅九室，諧八音。","歌皇慕，動神心。","禮宿設，樂妙尋。","聲明備，[祼]奠臨。"]', '["肅九室，諧八音。","歌皇慕，动神心。","禮宿設，乐妙尋。","声明備，[祼]奠臨。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 永和三章 一 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47749fe4-e4f7-44cd-9dfc-9c177de3c646', '郊廟歌辭 享太廟樂章 永和三章 二', '郊廟歌辞 享太廟乐章 永和三章 二', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["律迓氣，音入玄。","依玉几，御黼筵。","聆愾息，僾周旋。","九韶遍，百福傳。"]', '["律迓氣，音入玄。","依玉几，御黼筵。","聆愾息，僾周旋。","九韶遍，百福傳。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 永和三章 二 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('656928fe-763c-49d0-a587-b6857ab23734', '郊廟歌辭 享太廟樂章 永和三章 三', '郊廟歌辞 享太廟乐章 永和三章 三', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["信工祝，永頌聲。","來祖考，聽和平。","相百辟，貢九瀛。","神休委，帝孝成。"]', '["信工祝，永頌声。","来祖考，听和平。","相百辟，貢九瀛。","神休委，帝孝成。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 永和三章 三 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06273196-6d2a-4c70-9680-257cea297824', '郊廟歌辭 享太廟樂章 太和', '郊廟歌辞 享太廟乐章 太和', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["時文聖后，清廟肅邕。","致誠勤薦，在貌思恭。","玉節肆夏，金鏘五鍾。","繩繩雲步，穆穆天容。"]', '["时文聖后，清廟肅邕。","致誠勤薦，在貌思恭。","玉節肆夏，金鏘五鍾。","繩繩云步，穆穆天容。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 太和 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db927e94-ccb0-43f8-8d1c-d595e32aa205', '郊廟歌辭 享太廟樂章 肅和', '郊廟歌辞 享太廟乐章 肅和', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["天子享孝，工歌溥將。","躬[祼]鬱鬯，乃焚膋薌。","臭以達陰，聲以求陽。","奉時烝嘗，永代不忘。"]', '["天子享孝，工歌溥將。","躬[祼]鬱鬯，乃焚膋薌。","臭以達陰，声以求陽。","奉时烝嘗，永代不忘。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 肅和 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('076bc804-c0d9-4d33-bfbb-857a1b28d4fe', '郊廟歌辭 享太廟樂章 雍和二章 一', '郊廟歌辞 享太廟乐章 雍和二章 一', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["在滌嘉豢，麗碑敬牲。","角握之牡，色純之騂。","火傳陽燧，水溉陰精。","太公胖俎，[傅]說和羹。"]', '["在滌嘉豢，丽碑敬牲。","角握之牡，色純之騂。","火傳陽燧，水溉陰精。","太公胖俎，[傅]说和羹。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 雍和二章 一 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7196811a-78b3-4b37-b38d-4f312579860c', '郊廟歌辭 享太廟樂章 雍和二章 二', '郊廟歌辞 享太廟乐章 雍和二章 二', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["俎豆有馥，粢盛絜豐。","亦有和羹，既戒既平。","鼓鐘管磬，肅唱和鳴。","皇皇后祖，來我思成。"]', '["俎豆有馥，粢盛絜豐。","亦有和羹，既戒既平。","鼓鐘管磬，肅唱和鳴。","皇皇后祖，来我思成。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 雍和二章 二 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3bc86a7-d987-48d2-9f94-5df3bdc2934c', '郊廟歌辭 享太廟樂章 文舞', '郊廟歌辞 享太廟乐章 文舞', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["聖謩九德，真言五千。","慶集昌胄，符開帝先。","高文杖鉞，克配彼天。","三宗握鏡，六合渙然。","帝其承祀，率禮罔愆。","圖書霧出，日月清懸。","舞形德類，詠諗功傳。","黃龍蜿蟺，彩雲蹁躚。","五行氣順，八佾風宣。","介此百祿，於皇萬年。"]', '["聖謩九德，真言五千。","慶集昌胄，符开帝先。","高文杖鉞，克配彼天。","三宗握镜，六合渙然。","帝其承祀，率禮罔愆。","圖书霧出，日月清懸。","舞形德類，詠諗功傳。","黄龙蜿蟺，彩云蹁躚。","五行氣順，八佾风宣。","介此百祿，於皇万年。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 文舞 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e34baf9-9b4b-43d9-9333-5c3e5a72f841', '郊廟歌辭 享太廟樂章 光大舞', '郊廟歌辞 享太廟乐章 光大舞', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["肅肅藝祖，滔滔濬源。","有雄玉劍，作鎮金門。","玄王貽緒，后稷謀孫。","肇禋九廟，四海來尊。"]', '["肅肅藝祖，滔滔濬源。","有雄玉劍，作鎮金门。","玄王貽緒，后稷謀孫。","肇禋九廟，四海来尊。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 光大舞 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('062d7a61-9db6-4470-abf0-cf8d77eeffc5', '郊廟歌辭 享太廟樂章 長發舞', '郊廟歌辞 享太廟乐章 长發舞', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["具禮崇德，備樂承風。","魏推幢主，周贈司空。","不行而至，無成有終。","神興王業，天歸帝功。"]', '["具禮崇德，備乐承风。","魏推幢主，周贈司空。","不行而至，無成有終。","神兴王業，天归帝功。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 長發舞 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('884a1a63-e25d-4735-8987-3e557d13bb58', '郊廟歌辭 享太廟樂章 大政舞', '郊廟歌辞 享太廟乐章 大政舞', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["於赫元命，權輿帝文。","天齊八柱，地半三分。","宗廟觀德，笙鏞樂勳。","封唐之兆，成天下君。"]', '["於赫元命，權輿帝文。","天齊八柱，地半三分。","宗廟观德，笙鏞乐勳。","封唐之兆，成天下君。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 大政舞 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('357ac431-f7b8-4c06-823d-61254b5c1546', '郊廟歌辭 享太廟樂章 大成舞', '郊廟歌辞 享太廟乐章 大成舞', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["帝舞季歷，龍聖生昌。","后歌有蟜，胎炎孕黃。","天地合德，日月齊光。","肅雝孝享，祚我萬方。"]', '["帝舞季歷，龙聖生昌。","后歌有蟜，胎炎孕黄。","天地合德，日月齊光。","肅雝孝享，祚我万方。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 大成舞 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8bdfd81-4fdb-4c89-b7e6-6124331870d0', '郊廟歌辭 享太廟樂章 大明舞', '郊廟歌辞 享太廟乐章 大明舞', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["赤精亂德，四海困窮。","黃旗舉義，三靈會同。","旱望春雨，雲披大風。","溥天來祭，高祖之功。"]', '["赤精亂德，四海困窮。","黄旗舉義，三靈會同。","旱望春雨，云披大风。","溥天来祭，高祖之功。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 大明舞 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcebe002-b5e1-41e4-b269-ccd09098e0b7', '郊廟歌辭 享太廟樂章 崇德舞', '郊廟歌辞 享太廟乐章 崇德舞', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["皇合一德，朝宗百神。","削平天地，大拯生人。","上帝配食，單于入臣。","戎歌陳舞，曄曄震震。"]', '["皇合一德，朝宗百神。","削平天地，大拯生人。","上帝配食，單于入臣。","戎歌陳舞，曄曄震震。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 崇德舞 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b237c02d-7936-4f51-9e88-b11b6640df3e', '郊廟歌辭 享太廟樂章 鈞天舞', '郊廟歌辞 享太廟乐章 鈞天舞', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["高皇邁道，端拱無爲。","化懷獯鬻，兵賦句驪。","禮尊封禪，樂盛來儀。","合位媧后，同稱伏羲。"]', '["高皇邁道，端拱無爲。","化懷獯鬻，兵賦句驪。","禮尊封禪，乐盛来儀。","合位媧后，同稱伏羲。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 鈞天舞 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6f5e42d-b1c0-4fb7-ba33-3928a50a9cd5', '郊廟歌辭 享太廟樂章 大和舞', '郊廟歌辞 享太廟乐章 大和舞', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["退居江水，鬱起丹陵。","禮物還舊，朝章中興。","龍圖友及，駿命恭膺。","鳴球香瓚，大糦是承。"]', '["退居江水，鬱起丹陵。","禮物還旧，朝章中兴。","龙圖友及，駿命恭膺。","鳴球香瓚，大糦是承。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 大和舞 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ff56a31-51e0-4926-a44e-73635f47c545', '郊廟歌辭 享太廟樂章 景雲舞', '郊廟歌辞 享太廟乐章 景云舞', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["景雲霏爛，告我帝符。","噫帝沖德，與天爲徒。","笙鏞遙遠，俎豆虛無。","春秋孝獻，迴復此都。"]', '["景云霏爛，告我帝符。","噫帝沖德，與天爲徒。","笙鏞遙远，俎豆虛無。","春秋孝獻，迴复此都。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 景雲舞 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f77cc4a-756b-4d49-9f61-9f06765a6bad', '郊廟歌辭 享太廟樂章 福和', '郊廟歌辞 享太廟乐章 福和', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["備禮用樂，崇親致尊。","誠通慈降，敬徹愛存。","獻懷稱壽，啐感承恩。","皇帝孝德，子孫千億。","大包天域，長亙不極。"]', '["備禮用乐，崇親致尊。","誠通慈降，敬徹愛存。","獻懷稱壽，啐感承恩。","皇帝孝德，子孫千億。","大包天域，长亙不極。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 福和 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26890912-7fd0-4218-bb30-2e78c8c5842c', '郊廟歌辭 享太廟樂章 舒和', '郊廟歌辞 享太廟乐章 舒和', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["六鐘翕協六變成，八佾徜徉八風生。","樂九韶兮人神感，美七德兮天地清。"]', '["六鐘翕協六变成，八佾徜徉八风生。","乐九韶兮人神感，美七德兮天地清。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 舒和 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cc352d4-75fb-463a-9bda-f24ff3310cb4', '郊廟歌辭 享太廟樂章 凱安四章 一', '郊廟歌辞 享太廟乐章 凱安四章 一', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["瑟彼瑤爵，亞惟上公。","室如屏氣，門不容躬。","禮殷其本，樂執其中。","聖皇永慕，天地幽通。"]', '["瑟彼瑤爵，亞惟上公。","室如屏氣，门不容躬。","禮殷其本，乐執其中。","聖皇永慕，天地幽通。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 凱安四章 一 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53c38627-d071-4c1c-8d48-f7cdd7f9c026', '郊廟歌辭 享太廟樂章 凱安四章 二', '郊廟歌辞 享太廟乐章 凱安四章 二', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["禮匝三獻，樂遍九成。","降循軒陛，仰欷皇情。","福與仁合，德因孝明。","百年[神畏]，四海風行。"]', '["禮匝三獻，乐遍九成。","降循軒陛，仰欷皇情。","福與仁合，德因孝明。","百年[神畏]，四海风行。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 凱安四章 二 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd5cc7ad-fb0e-434e-b731-6967676f7f39', '郊廟歌辭 享太廟樂章 凱安四章 三', '郊廟歌辞 享太廟乐章 凱安四章 三', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["總總干戚，填填鼓鐘。","奮揚爭氣，坐作爲容。","離若鷙鳥，合如戰龍。","萬方觀德，肅肅雝雝。"]', '["總總干戚，填填鼓鐘。","奮揚爭氣，坐作爲容。","離若鷙鸟，合如戰龙。","万方观德，肅肅雝雝。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 凱安四章 三 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb23e85d-52f7-41bc-aef5-25b219f6f699', '郊廟歌辭 享太廟樂章 凱安四章 四', '郊廟歌辞 享太廟乐章 凱安四章 四', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["烈祖順三靈，文宗威四海。","黃鉞誅羣盜，朱旗掃多罪。","戢兵天下安，約法人心改。","大哉干羽意，長見風雲在。"]', '["烈祖順三靈，文宗威四海。","黄鉞誅羣盜，朱旗掃多罪。","戢兵天下安，約法人心改。","大哉干羽意，长见风云在。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 凱安四章 四 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('153776ca-d0c7-40ce-af6a-568daf6a79eb', '郊廟歌辭 享太廟樂章 登歌', '郊廟歌辞 享太廟乐章 登歌', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["止笙磬，撤豆籩。","廓無響，窅入玄。","主在室，神在天。","情餘慕，禮罔愆。","喜黍稷，屢豐年。"]', '["止笙磬，撤豆籩。","廓無响，窅入玄。","主在室，神在天。","情餘慕，禮罔愆。","喜黍稷，屢豐年。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 登歌 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e70176f2-53b1-4dbe-963c-ef6fc9e3e64d', '郊廟歌辭 享太廟樂章 永和', '郊廟歌辞 享太廟乐章 永和', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["眇嘉樂，授靈爽。","感若來，思如往。","休氣散，迴風上。","返寂寞，還惚恍。","懷靈駕，結空想。"]', '["眇嘉乐，授靈爽。","感若来，思如往。","休氣散，迴风上。","返寂寞，還惚恍。","懷靈駕，結空想。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 永和 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9adcff7-7ac4-4ac2-be95-df151a920114', '郊廟歌辭 享太廟樂章 廣運舞', '郊廟歌辞 享太廟乐章 廣運舞', '9964896f-2064-49e0-bca2-0d49d61a7a2a', '唐', '["於赫皇祖，昭明有融。","惟文之德，惟武之功。","河海靜謐，車書混同。","虔恭孝饗，穆穆玄風。"]', '["於赫皇祖，昭明有融。","惟文之德，惟武之功。","河海静謐，车书混同。","虔恭孝饗，穆穆玄风。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 廣運舞 郭子儀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e86a6a73-602c-4745-ab81-541d27786663', '郊廟歌辭 享太廟樂章 惟新舞', '郊廟歌辞 享太廟乐章 惟新舞', 'd84ded69-f9df-4301-a4e4-a8716f42626f', '唐', '["漢祚惟永，神功中興。","風驅氛祲，天覆黎蒸。","三光再朗，庶績其凝。","重熙累洽，景命是膺。"]', '["漢祚惟永，神功中兴。","风驱氛祲，天覆黎蒸。","三光再朗，庶績其凝。","重熙累洽，景命是膺。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 惟新舞 劉晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1700afdb-215f-4a06-b555-c4b3fb9e9375', '郊廟歌辭 享太廟樂章 保大舞', '郊廟歌辞 享太廟乐章 保大舞', '9964896f-2064-49e0-bca2-0d49d61a7a2a', '唐', '["於穆文考，聖神昭章。","肅勺羣慝，含光遠方。","萬物茂遂，九夷賓王。","愔愔雲韶，德音不忘。"]', '["於穆文考，聖神昭章。","肅勺羣慝，含光远方。","万物茂遂，九夷賓王。","愔愔云韶，德音不忘。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 保大舞 郭子儀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd9ee03c-96d1-4c84-b8ea-6d85f0e0f46f', '郊廟歌辭 享太廟樂章 文明舞', '郊廟歌辞 享太廟乐章 文明舞', 'b6dc0167-a22a-48a0-b2a5-9e90ae635422', '唐', '["開邸除暴，時邁勛尊。","三元告命，四極駿奔。","金枝翠葉，輝燭瑤琨。","象德億載，貽慶湯孫。"]', '["开邸除暴，时邁勛尊。","三元告命，四極駿奔。","金枝翠葉，輝燭瑤琨。","象德億載，貽慶湯孫。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 文明舞 鄭餘慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27173453-b779-41af-a14b-aa21a44a4ecb', '郊廟歌辭 享太廟樂章 大順舞', '郊廟歌辞 享太廟乐章 大順舞', '170218e7-8099-4428-a712-203ab61ebca6', '唐', '["於穆時文，受天明命。","允恭玄默，化成理定。","出震嗣德，應乾傳聖。","猗歟緝熙，千億流慶。"]', '["於穆时文，受天明命。","允恭玄默，化成理定。","出震嗣德，應乾傳聖。","猗歟緝熙，千億流慶。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 大順舞 鄭絪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24daec53-cf05-46fb-bfac-051e9eb4b8ce', '郊廟歌辭 享太廟樂章 象德舞', '郊廟歌辞 享太廟乐章 象德舞', 'e2aa1c92-a236-489d-8caa-edad96e1c05d', '唐', '["肅肅清廟，登顯至德。","澤周八荒，兵定四極。","生物咸遂，羣盜滅息。","明聖欽承，子孫千億。"]', '["肅肅清廟，登显至德。","澤周八荒，兵定四極。","生物咸遂，羣盜滅息。","明聖欽承，子孫千億。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 象德舞 段文昌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('811d83e1-a2d7-4ffd-93b3-5705c81706e2', '郊廟歌辭 享太廟樂章 和寧舞', '郊廟歌辞 享太廟乐章 和寧舞', 'de627c39-c31e-4b7c-802f-80e543334355', '唐', '["湜湜頎頎，融昭德輝。","不紐不舒，貫成九圍。","武烈文經，敷施當宜。","纂堯付啓，億萬熙熙。"]', '["湜湜頎頎，融昭德輝。","不紐不舒，貫成九圍。","武烈文經，敷施當宜。","纂堯付啓，億万熙熙。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 和寧舞 牛僧孺 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7595547c-5365-491b-912f-ab12784afc15', '郊廟歌辭 享太廟樂章 大定舞', '郊廟歌辞 享太廟乐章 大定舞', '87b02171-c734-4fc6-ad05-c1392b541913', '唐', '["受天明命，敷佑下土。","化時以儉，衛文以武。","氛消夷夏，俗臻往古。","億萬斯年，形于律呂。"]', '["受天明命，敷佑下土。","化时以儉，衛文以武。","氛消夷夏，俗臻往古。","億万斯年，形于律呂。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 大定舞 李回 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70332c1e-72b9-41d2-9752-ea1b4bf356c4', '郊廟歌辭 享太廟樂章 宣宗室舞', '郊廟歌辞 享太廟乐章 宣宗室舞', 'f86bca6c-0179-4ff7-b80b-6e3cde37ecdc', '唐', '["於鑠令主，聖祚重昌。","興起教義，申明典章。","俗尚素朴，人皆樂康。","積德可報，流慶無疆。"]', '["於鑠令主，聖祚重昌。","兴起教義，申明典章。","俗尚素朴，人皆乐康。","積德可報，流慶無疆。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 宣宗室舞 夏侯孜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccf34b3e-9e90-4bd2-8ea4-65948bd3d19b', '郊廟歌辭  懿宗室舞', '郊廟歌辞  懿宗室舞', '10608f17-cdfe-469b-9081-e5550a6d85e2', '唐', '["聖祚無疆，慶傳樂章。","金枝繁茂，玉葉延長。","海瀆常[晏]，波濤不揚。","汪汪美化，垂範今王。"]', '["聖祚無疆，慶傳乐章。","金枝繁茂，玉葉延长。","海瀆常[晏]，波濤不揚。","汪汪美化，垂範今王。"]', '诗', 'shi', '', NULL, '郊廟歌辭  懿宗室舞 蕭倣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09c0c6b5-b13f-4473-8618-eb160494b202', '郊廟歌辭 享太廟樂章 咸寧舞', '郊廟歌辞 享太廟乐章 咸寧舞', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["於鑠丕嗣，惟帝之光。","羽籥象德，金石薦祥。","聖系無極，景命永昌。","神降上哲，維天配長。"]', '["於鑠丕嗣，惟帝之光。","羽籥象德，金石薦祥。","聖系無極，景命永昌。","神降上哲，維天配长。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享太廟樂章 咸寧舞 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe138730-cbf4-45ab-9763-ed22317873a9', '郊廟歌辭 太清宮樂章 煌煌', '郊廟歌辞 太清宮乐章 煌煌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["煌煌道宮，肅肅太清。","禮光尊祖，樂備充庭。","罄竭誠至，希夷降靈。","雲凝翠蓋，風燄紅旌。","衆真以從，九奏初迎。","永惟休祐，是錫和平。"]', '["煌煌道宮，肅肅太清。","禮光尊祖，乐備充庭。","罄竭誠至，希夷降靈。","云凝翠蓋，风燄紅旌。","衆真以從，九奏初迎。","永惟休祐，是錫和平。"]', '诗', 'shi', '', NULL, '郊廟歌辭 太清宮樂章 煌煌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0ea6d16-5fd3-47e4-bdb5-27562528afe2', '郊廟歌辭 太清宮樂章 沖和', '郊廟歌辞 太清宮乐章 沖和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["虛無結思，鐘磬和音。","歌以頌德，香以達心。","禮殊祼鬯，義感昭臨。","雲車至止，慶垂愔愔。"]', '["虛無結思，鐘磬和音。","歌以頌德，香以達心。","禮殊祼鬯，義感昭臨。","云车至止，慶垂愔愔。"]', '诗', 'shi', '', NULL, '郊廟歌辭 太清宮樂章 沖和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c03752f1-fff4-459b-931e-896dedb77384', '郊廟歌辭 太清宮樂章 香初上', '郊廟歌辞 太清宮乐章 香初上', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["肅肅我祖，緜緜道宗。","至感潛達，靈心暗通。","雲軿御氣，芝蓋隨風。","四時禋祀，萬國來同。"]', '["肅肅我祖，緜緜道宗。","至感潛達，靈心暗通。","云軿御氣，芝蓋隨风。","四时禋祀，万国来同。"]', '诗', 'shi', '', NULL, '郊廟歌辭 太清宮樂章 香初上 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72199536-ac42-4142-9756-75719946c1ef', '郊廟歌辭 太清宮樂章 再上', '郊廟歌辞 太清宮乐章 再上', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["仙宗績道，我李承天。","慶深虛極，符光象先。","俗登仁壽，化闡蟺涓。","五千貽範，億萬斯年。"]', '["仙宗績道，我李承天。","慶深虛極，符光象先。","俗登仁壽，化闡蟺涓。","五千貽範，億万斯年。"]', '诗', 'shi', '', NULL, '郊廟歌辭 太清宮樂章 再上 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12c1a825-4611-4f3a-869d-0ee8b443513c', '郊廟歌辭 太清宮樂章 終上', '郊廟歌辞 太清宮乐章 終上', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["不宰元功，無爲上聖。","洪源長發，誕受天命。","金奏迎真，璇宮展盛。","備禮周樂，垂光儲慶。"]', '["不宰元功，無爲上聖。","洪源长發，誕受天命。","金奏迎真，璇宮展盛。","備禮周乐，垂光儲慶。"]', '诗', 'shi', '', NULL, '郊廟歌辭 太清宮樂章 終上 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd921ba1-15e1-4b4c-96e5-a127f6678ea7', '郊廟歌辭 太清宮樂章 紫極舞', '郊廟歌辞 太清宮乐章 紫極舞', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["至道生元氣，重圓法混成。","無爲觀大象，沖用體常名。","仙樂臨丹闕，雲車出玉京。","靈符百代應，瑞節九貞迎。","寶運開皇極，天臨映太清。","長垂一德慶，永庇萬方寧。"]', '["至道生元氣，重圓法混成。","無爲观大象，沖用體常名。","仙乐臨丹闕，云车出玉京。","靈符百代應，瑞節九貞迎。","寶運开皇極，天臨映太清。","长垂一德慶，永庇万方寧。"]', '诗', 'shi', '', NULL, '郊廟歌辭 太清宮樂章 紫極舞 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d862501-b360-4e47-bf4b-9ebd1406bc42', '郊廟歌辭 太清宮樂章 序入破第一奏', '郊廟歌辞 太清宮乐章 序入破第一奏', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["真宗開妙理，沖教統清虛。","化演無爲日，言昭有象初。","瑤臺肅靈瑞，金闕映仙居。","一奏三清樂，長回八景輿。"]', '["真宗开妙理，沖教統清虛。","化演無爲日，言昭有象初。","瑤台肅靈瑞，金闕映仙居。","一奏三清乐，长回八景輿。"]', '诗', 'shi', '', NULL, '郊廟歌辭 太清宮樂章 序入破第一奏 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa252fae-6e68-425e-b0b3-89acc657b20c', '郊廟歌辭 太清宮樂章 序入破第二奏', '郊廟歌辞 太清宮乐章 序入破第二奏', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["虛極仙宗本，希夷象帝先。","百靈朝太上，萬法祖重圓。","善貸惟沖德，功成謂自然。","雲門達和氣，思用合鈞天。"]', '["虛極仙宗本，希夷象帝先。","百靈朝太上，万法祖重圓。","善貸惟沖德，功成謂自然。","云门達和氣，思用合鈞天。"]', '诗', 'shi', '', NULL, '郊廟歌辭 太清宮樂章 序入破第二奏 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a2ad219-b391-4410-8915-80de4cee5715', '郊廟歌辭 太清宮樂章 序入破第三奏', '郊廟歌辞 太清宮乐章 序入破第三奏', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["元符傳紫極，寶祚啓高真。","道德先垂裕，沖和已化淳。","人風齊太古，天瑞叶惟新。","仙樂清都上，長明交泰辰。"]', '["元符傳紫極，寶祚啓高真。","道德先垂裕，沖和已化淳。","人风齊太古，天瑞叶惟新。","仙乐清都上，长明交泰辰。"]', '诗', 'shi', '', NULL, '郊廟歌辭 太清宮樂章 序入破第三奏 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30c24c3f-d61b-4577-84de-f25af23a069c', '郊廟歌辭 太清宮樂章 登歌', '郊廟歌辞 太清宮乐章 登歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["嚴禋展事，理潔烝嘗。","皇矣聖祖，德惟馨香。","盛薦既撤，工歌載揚。","大來之慶，降福穰穰。"]', '["嚴禋展事，理潔烝嘗。","皇矣聖祖，德惟馨香。","盛薦既撤，工歌載揚。","大来之慶，降福穰穰。"]', '诗', 'shi', '', NULL, '郊廟歌辭 太清宮樂章 登歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69bacbb3-1d7d-4e86-81c5-48f7789a4862', '郊廟歌辭 太清宮樂章 真和', '郊廟歌辞 太清宮乐章 真和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["玉磬含香，金爐既馥。","風馭泠泠，雲壇肅肅。","杳歸大象，霈流嘉福。","俾寧萬邦，無思不服。"]', '["玉磬含香，金爐既馥。","风馭泠泠，云壇肅肅。","杳归大象，霈流嘉福。","俾寧万邦，無思不服。"]', '诗', 'shi', '', NULL, '郊廟歌辭 太清宮樂章 真和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d290e33-710f-4419-a30d-2d76a3b3e54a', '郊廟歌辭 德明興聖廟樂章 迎神', '郊廟歌辞 德明兴聖廟乐章 迎神', '8b2ad8d8-1ac3-4174-8a77-4baa8b798a26', '唐', '["元尊九德，佐堯光宅。","烈祖太宗，方周作伯。","響懷霜露，樂變金石。","白雲清風，髣髴來格。"]', '["元尊九德，佐堯光宅。","烈祖太宗，方周作伯。","响懷霜露，乐变金石。","白云清风，髣髴来格。"]', '诗', 'shi', '', NULL, '郊廟歌辭 德明興聖廟樂章 迎神 李舒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea9c019e-a6fb-4620-847b-130634b1b349', '郊廟歌辭 德明興聖廟樂章 登歌奠幣', '郊廟歌辞 德明兴聖廟乐章 登歌奠幣', '8b2ad8d8-1ac3-4174-8a77-4baa8b798a26', '唐', '["四時有典，百事來祭。","尊祖奉宗，嚴禋大帝。","禮先蒼璧，奠幣黝制。","於斯萬年，熙成帝系。"]', '["四时有典，百事来祭。","尊祖奉宗，嚴禋大帝。","禮先蒼璧，奠幣黝制。","於斯万年，熙成帝系。"]', '诗', 'shi', '', NULL, '郊廟歌辭 德明興聖廟樂章 登歌奠幣 李舒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e9c2d4d-32af-4938-a890-b2f658f7db72', '郊廟歌辭 德明興聖廟樂章 迎俎', '郊廟歌辞 德明兴聖廟乐章 迎俎', '8b2ad8d8-1ac3-4174-8a77-4baa8b798a26', '唐', '["盛牲實俎，涓選休成。","鼎煁陽燧，玉盥陰精。","有飶嘉豆，既和大羹。","侑以清樂，細齊人情。"]', '["盛牲實俎，涓選休成。","鼎煁陽燧，玉盥陰精。","有飶嘉豆，既和大羹。","侑以清乐，細齊人情。"]', '诗', 'shi', '', NULL, '郊廟歌辭 德明興聖廟樂章 迎俎 李舒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78f6ace2-c073-4935-a33d-5146e337527f', '郊廟歌辭 德明興聖廟樂章 德明酌獻', '郊廟歌辞 德明兴聖廟乐章 德明酌獻', '8b2ad8d8-1ac3-4174-8a77-4baa8b798a26', '唐', '["清廟奕奕，和樂雍雍。","器尊犧象，禮屬宗公。","白水方祼，黃流在中。","謨明之德，萬古清風。"]', '["清廟奕奕，和乐雍雍。","器尊犧象，禮屬宗公。","白水方祼，黄流在中。","謨明之德，万古清风。"]', '诗', 'shi', '', NULL, '郊廟歌辭 德明興聖廟樂章 德明酌獻 李舒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b254f983-1f0a-40c9-9a35-19d1699fb83b', '郊廟歌辭 德明興聖廟樂章 興聖酌獻', '郊廟歌辞 德明兴聖廟乐章 兴聖酌獻', '8b2ad8d8-1ac3-4174-8a77-4baa8b798a26', '唐', '["閟宮靜謐，合樂周張。","泰尊始獻，百末重觴。","震澹存誠，庶幾迪嘗。","遙源之祚，天漢靈長。"]', '["閟宮静謐，合乐周張。","泰尊始獻，百末重觴。","震澹存誠，庶幾迪嘗。","遙源之祚，天漢靈长。"]', '诗', 'shi', '', NULL, '郊廟歌辭 德明興聖廟樂章 興聖酌獻 李舒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8df415f8-1217-4d67-b74c-eb561ae5bee5', '郊廟歌辭 德明興聖廟樂章 亞獻終獻', '郊廟歌辞 德明兴聖廟乐章 亞獻終獻', '8b2ad8d8-1ac3-4174-8a77-4baa8b798a26', '唐', '["惟清惟肅，靡聞靡見。","舉備九成，俛終三獻。","慶彰曼壽，胙徹嘉薦。","瘞玉埋牲，禮神斯徧。"]', '["惟清惟肅，靡闻靡见。","舉備九成，俛終三獻。","慶彰曼壽，胙徹嘉薦。","瘞玉埋牲，禮神斯徧。"]', '诗', 'shi', '', NULL, '郊廟歌辭 德明興聖廟樂章 亞獻終獻 李舒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db9b8092-5124-4685-8416-c092806d6bef', '郊廟歌辭 德明興聖廟樂章 送神', '郊廟歌辞 德明兴聖廟乐章 送神', '8b2ad8d8-1ac3-4174-8a77-4baa8b798a26', '唐', '["元精回復，靈貺繁滋。","風灑蘭路，雲搖桂旗。","高丘緬邈，涼部逶遲。","瞻望靡及，纏綿永思。"]', '["元精回复，靈貺繁滋。","风灑蘭路，云搖桂旗。","高丘緬邈，涼部逶遲。","瞻望靡及，纏綿永思。"]', '诗', 'shi', '', NULL, '郊廟歌辭 德明興聖廟樂章 送神 李舒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c5a317d-fe60-4e67-a0b5-a9ed42e5aa6a', '郊廟歌辭 儀坤廟樂章 永和', '郊廟歌辞 儀坤廟乐章 永和', 'feb1b440-a02e-4e74-8f62-faadc8d7e153', '唐', '["猗若清廟，肅肅熒熒。","國薦嚴祀，坤興淑靈。","有几在室，有樂在庭。","臨茲孝享，百祿惟寧。"]', '["猗若清廟，肅肅熒熒。","国薦嚴祀，坤兴淑靈。","有几在室，有乐在庭。","臨茲孝享，百祿惟寧。"]', '诗', 'shi', '', NULL, '郊廟歌辭 儀坤廟樂章 永和 徐彥伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe67914f-1ea9-4c19-96cd-fd01efec5274', '郊廟歌辭 儀坤廟樂章 金奏', '郊廟歌辞 儀坤廟乐章 金奏', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["陰靈曜祉，軒曜降精。","祥符淑氣，慶集柔明。","瑤俎既列，雕桐發聲。","徽猷永遠，比德皇英。"]', '["陰靈曜祉，軒曜降精。","祥符淑氣，慶集柔明。","瑤俎既列，雕桐發声。","徽猷永远，比德皇英。"]', '诗', 'shi', '', NULL, '郊廟歌辭 儀坤廟樂章 金奏 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('181cf5ae-f642-4a02-81f0-ae4685bed51f', '郊廟歌辭 儀坤廟樂章 太和', '郊廟歌辞 儀坤廟乐章 太和', '23b934d3-c958-411e-8201-671a2bf48b81', '唐', '["孝哉我后，沖乎迺聖。","道映重華，德輝文命。","慕深視篋，情殷撫鏡。","萬國移風，兆人承慶。"]', '["孝哉我后，沖乎迺聖。","道映重华，德輝文命。","慕深視篋，情殷撫镜。","万国移风，兆人承慶。"]', '诗', 'shi', '', NULL, '郊廟歌辭 儀坤廟樂章 太和 丘說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27377974-8e63-49d7-8da0-8608a884d0a2', '郊廟歌辭 儀坤廟樂章 肅和', '郊廟歌辞 儀坤廟乐章 肅和', 'fd3d1662-6b7e-4c60-a102-9bffc98656cb', '唐', '["祼圭既濯，鬱鬯既陳。","畫幕雲舉，黃流玉醇。","儀充獻酌，禮盛衆禋。","地察惟孝，愉焉饗親。"]', '["祼圭既濯，鬱鬯既陳。","畫幕云舉，黄流玉醇。","儀充獻酌，禮盛衆禋。","地察惟孝，愉焉饗親。"]', '诗', 'shi', '', NULL, '郊廟歌辭 儀坤廟樂章 肅和 張齊賢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fa22cad-259c-44ee-9895-cae13745127c', '郊廟歌辭 儀坤廟樂章 雍和', '郊廟歌辞 儀坤廟乐章 雍和', '07bae2f9-1645-4621-b8d0-e19ed8a0acc6', '唐', '["酌鬱既灌，薌蕭方爇。","籩豆靜器，簠簋芬飶。","魚腊薦美，牲牷表潔。","是戢是將，載迎載列。"]', '["酌鬱既灌，薌蕭方爇。","籩豆静器，簠簋芬飶。","鱼腊薦美，牲牷表潔。","是戢是將，載迎載列。"]', '诗', 'shi', '', NULL, '郊廟歌辭 儀坤廟樂章 雍和 鄭善玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('085598ca-4735-4f96-8681-491f4d7a3260', '郊廟歌辭 儀坤廟樂章 昭升', '郊廟歌辞 儀坤廟乐章 昭升', 'e201e627-f22a-4d7e-921a-601dacd6b259', '唐', '["陽靈配德，陰魄昭升。","堯壇鳳下，漢室龍興。","俔天作對，前旒是凝。","化行南國，道盛西陵。","造舟集灌，無德而稱。","我粢既絜，我醴既澄。","陰陰靈廟，光靈若憑。","德馨惟享，孝思烝烝。"]', '["陽靈配德，陰魄昭升。","堯壇鳳下，漢室龙兴。","俔天作对，前旒是凝。","化行南国，道盛西陵。","造舟集灌，無德而稱。","我粢既絜，我醴既澄。","陰陰靈廟，光靈若憑。","德馨惟享，孝思烝烝。"]', '诗', 'shi', '', NULL, '郊廟歌辭 儀坤廟樂章 昭升 薛稷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('235e8677-6e47-4e04-9422-c1a98acd3773', '郊廟歌辭 儀坤廟樂章 坤貞', '郊廟歌辞 儀坤廟乐章 坤貞', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["乾道既亨，坤元以貞。","肅雍攸在，輔佐斯成。","外睦九族，內光一庭。","克生睿哲，祚我休明。","欽若徽範，悠哉淑靈。","建茲清宮，于彼上京。","縮茅以獻，絜秬惟馨。","實受其福，期乎億齡。"]', '["乾道既亨，坤元以貞。","肅雍攸在，輔佐斯成。","外睦九族，內光一庭。","克生睿哲，祚我休明。","欽若徽範，悠哉淑靈。","建茲清宮，于彼上京。","縮茅以獻，絜秬惟馨。","實受其福，期乎億齡。"]', '诗', 'shi', '', NULL, '郊廟歌辭 儀坤廟樂章 坤貞 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d95c1136-9489-4d8b-a72e-22d1b0e7f1a3', '郊廟歌辭 儀坤廟樂章 壽和', '郊廟歌辞 儀坤廟乐章 壽和', 'ec72e864-2de4-43d6-bcca-d90c758c4325', '唐', '["於穆清廟，肅雍嚴祀。","合福受釐，介以繁[祉]。"]', '["於穆清廟，肅雍嚴祀。","合福受釐，介以繁[祉]。"]', '诗', 'shi', '', NULL, '郊廟歌辭 儀坤廟樂章 壽和 徐堅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b15d19b-79e5-4872-8e52-77d26c711632', '郊廟歌辭 儀坤廟樂章 舒和', '郊廟歌辞 儀坤廟乐章 舒和', '25f72364-480f-45a5-aeec-01e9ed89d8c7', '唐', '["送文迎武遞參差，一始一終光聖儀。","四海生人歌有慶，千齡孝享肅無虧。"]', '["送文迎武遞參差，一始一終光聖儀。","四海生人歌有慶，千齡孝享肅無虧。"]', '诗', 'shi', '', NULL, '郊廟歌辭 儀坤廟樂章 舒和 胡雄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('201aff1c-c3f8-4327-93bf-c1d6a1232ac7', '郊廟歌辭 儀坤廟樂章 安和', '郊廟歌辞 儀坤廟乐章 安和', 'd2cdeac7-2790-4326-b1be-5a5237aacdd8', '唐', '["妙筭申帷幄，神謀及廟庭。","兩階文物備，七德武功成。","校獵長楊苑，屯軍細柳營。","將軍獻凱入，歌舞溢重城。"]', '["妙筭申帷幄，神謀及廟庭。","兩階文物備，七德武功成。","校獵长楊苑，屯軍細柳營。","將軍獻凱入，歌舞溢重城。"]', '诗', 'shi', '', NULL, '郊廟歌辭 儀坤廟樂章 安和 劉子玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bcac1d6-b744-4060-9ef5-7f35dad5db8f', '郊廟歌辭 儀坤廟樂章 雍和', '郊廟歌辞 儀坤廟乐章 雍和', '036fa87c-42c8-4bb1-b325-6b9a50c4ccc7', '唐', '["孝享云畢，惟徹有章。","雲感玄羽，風悽素商。","瞻望神座，祗戀匪遑。","禮終樂闋，肅雍鏘鏘。"]', '["孝享云畢，惟徹有章。","云感玄羽，风悽素商。","瞻望神座，祗戀匪遑。","禮終乐闋，肅雍鏘鏘。"]', '诗', 'shi', '', NULL, '郊廟歌辭 儀坤廟樂章 雍和 員半千 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eed3132b-db96-48c9-aefc-898186012ccc', '郊廟歌辭 儀坤廟樂章 永和', '郊廟歌辞 儀坤廟乐章 永和', '8ad59a11-054b-466e-b28f-cd0e5fd04758', '唐', '["閟宮實實，清廟微微。","降格無象，馨香有依。","式昭纂慶，方融嗣徽。","明禋是享，神保聿歸。"]', '["閟宮實實，清廟微微。","降格無象，馨香有依。","式昭纂慶，方融嗣徽。","明禋是享，神保聿归。"]', '诗', 'shi', '', NULL, '郊廟歌辭 儀坤廟樂章 永和 祝欽明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9531bb3-bce8-42e3-9e73-28de161c2b1a', '郊廟歌辭 儀坤廟樂章 迎神', '郊廟歌辞 儀坤廟乐章 迎神', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["月靈降德，坤元授光。","娥英比秀，任姒均芳。","瑤臺薦祉，金屋延祥。","迎神有樂，歆此嘉薌。"]', '["月靈降德，坤元授光。","娥英比秀，任姒均芳。","瑤台薦祉，金屋延祥。","迎神有乐，歆此嘉薌。"]', '诗', 'shi', '', NULL, '郊廟歌辭 儀坤廟樂章 迎神 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5df204cd-62f9-4d08-baa7-2d75bae5a9dd', '郊廟歌辭 儀坤廟樂章 送神', '郊廟歌辞 儀坤廟乐章 送神', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["玉帛儀大，金絲奏廣。","靈應有孚，冥徵不爽。","降彼休福，歆茲禋享。","送樂有章，神麾其上。"]', '["玉帛儀大，金絲奏廣。","靈應有孚，冥徵不爽。","降彼休福，歆茲禋享。","送乐有章，神麾其上。"]', '诗', 'shi', '', NULL, '郊廟歌辭 儀坤廟樂章 送神 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('389ab6fd-17b0-4633-af04-f1f4d9985116', '郊廟歌辭 昭德皇后廟樂章 永和', '郊廟歌辞 昭德皇后廟乐章 永和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["穆清廟，薦嚴禋。","昭禮備，和樂新。","望靈光，集元辰。","祚無極，享萬春。"]', '["穆清廟，薦嚴禋。","昭禮備，和乐新。","望靈光，集元辰。","祚無極，享万春。"]', '诗', 'shi', '', NULL, '郊廟歌辭 昭德皇后廟樂章 永和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85a46f9d-724e-4e70-9a94-280ac37dcb72', '郊廟歌辭 昭德皇后廟樂章 肅和', '郊廟歌辞 昭德皇后廟乐章 肅和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["誠心達，娛樂分。","升簫膋，鬱氛氳。","茅既縮，鬯既薰。","后來思，福如雲。"]', '["誠心達，娛乐分。","升簫膋，鬱氛氳。","茅既縮，鬯既薰。","后来思，福如云。"]', '诗', 'shi', '', NULL, '郊廟歌辭 昭德皇后廟樂章 肅和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e035238-dd9f-4544-b1d6-85dc9eb46810', '郊廟歌辭 昭德皇后廟樂章 雍和', '郊廟歌辞 昭德皇后廟乐章 雍和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["我將我享，盡明而誠。","載芬黍稷，載滌犧牲。","懿矣元良，萬邦以貞。","心乎愛敬，若覩容聲。"]', '["我將我享，尽明而誠。","載芬黍稷，載滌犧牲。","懿矣元良，万邦以貞。","心乎愛敬，若覩容声。"]', '诗', 'shi', '', NULL, '郊廟歌辭 昭德皇后廟樂章 雍和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c124fb36-862f-4c52-8ca3-d2ec5c92f80e', '郊廟歌辭 昭德皇后廟樂章 坤元', '郊廟歌辞 昭德皇后廟乐章 坤元', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["於穆先后，麗聖稱崇。","母臨萬宇，道[被]六宮。","昌時協慶，理內成功。","殷薦明德，傳芳國風。"]', '["於穆先后，丽聖稱崇。","母臨万宇，道[被]六宮。","昌时協慶，理內成功。","殷薦明德，傳芳国风。"]', '诗', 'shi', '', NULL, '郊廟歌辭 昭德皇后廟樂章 坤元 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01780a1c-3926-44f0-a75e-bf97d4624284', '郊廟歌辭 昭德皇后廟樂章 壽和', '郊廟歌辞 昭德皇后廟乐章 壽和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["工祝致告，徽音不遐。","酒醴咸旨，馨香具嘉。","受釐獻祉，永慶邦家。"]', '["工祝致告，徽音不遐。","酒醴咸旨，馨香具嘉。","受釐獻祉，永慶邦家。"]', '诗', 'shi', '', NULL, '郊廟歌辭 昭德皇后廟樂章 壽和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39971b18-28f4-4de4-be97-f327fd3433fd', '郊廟歌辭 昭德皇后廟樂章 舒和', '郊廟歌辞 昭德皇后廟乐章 舒和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["金枝羽部徹清歌，瑤臺肅穆笙磬羅。","諧音遍響合明意，萬類昭融靈應多。"]', '["金枝羽部徹清歌，瑤台肅穆笙磬羅。","諧音遍响合明意，万類昭融靈應多。"]', '诗', 'shi', '', NULL, '郊廟歌辭 昭德皇后廟樂章 舒和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bde04cd8-18fd-45eb-80ea-fdc0af36c6d4', '郊廟歌辭 昭德皇后廟樂章 凱安', '郊廟歌辞 昭德皇后廟乐章 凱安', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["辰位列四星，帝功參十亂。","進賢勤內輔，扈蹕清多難。","承天厚載均，並耀宵光璨。","留徽藹前躅，萬古披圖煥。"]', '["辰位列四星，帝功參十亂。","進賢勤內輔，扈蹕清多难。","承天厚載均，並耀宵光璨。","留徽藹前躅，万古披圖煥。"]', '诗', 'shi', '', NULL, '郊廟歌辭 昭德皇后廟樂章 凱安 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab29bc48-2530-448e-ad7e-d8bef40d1ac9', '郊廟歌辭 昭德皇后廟樂章 雍和', '郊廟歌辞 昭德皇后廟乐章 雍和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["公尸既起，享禮載終。","稱歌進徹，盡敬繇衷。","澤流惠下，大小咸同。"]', '["公尸既起，享禮載終。","稱歌進徹，尽敬繇衷。","澤流惠下，大小咸同。"]', '诗', 'shi', '', NULL, '郊廟歌辭 昭德皇后廟樂章 雍和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03981ca7-42b0-4400-af87-2106d8d2ab83', '郊廟歌辭 昭德皇后廟樂章 永和', '郊廟歌辞 昭德皇后廟乐章 永和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["昭事終，幽享餘。","移月御，返仙居。","璇庭寂，靈幄虛。","顧裴回，感皇儲。"]', '["昭事終，幽享餘。","移月御，返仙居。","璇庭寂，靈幄虛。","顧裴回，感皇儲。"]', '诗', 'shi', '', NULL, '郊廟歌辭 昭德皇后廟樂章 永和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('429d126e-c2a3-4496-8481-fb7d16a587d0', '郊廟歌辭 讓皇帝廟樂章 迎神', '郊廟歌辞 讓皇帝廟乐章 迎神', '8b2ad8d8-1ac3-4174-8a77-4baa8b798a26', '唐', '["皇矣天宗，德先王季。","因心則友，克讓以位。","爰命有司，式遵前志。","神其降靈，昭饗祀事。"]', '["皇矣天宗，德先王季。","因心則友，克讓以位。","爰命有司，式遵前志。","神其降靈，昭饗祀事。"]', '诗', 'shi', '', NULL, '郊廟歌辭 讓皇帝廟樂章 迎神 李舒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41ecef75-7b10-43ec-bd23-77fab837ced4', '郊廟歌辭 讓皇帝廟樂章 奠幣', '郊廟歌辞 讓皇帝廟乐章 奠幣', '8b2ad8d8-1ac3-4174-8a77-4baa8b798a26', '唐', '["惟帝時若，去而上仙。","祀用商舞，樂備宮懸。","白璧加薦，玄纁告虔。","子孫拜後，承茲吉蠲。"]', '["惟帝时若，去而上仙。","祀用商舞，乐備宮懸。","白璧加薦，玄纁告虔。","子孫拜後，承茲吉蠲。"]', '诗', 'shi', '', NULL, '郊廟歌辭 讓皇帝廟樂章 奠幣 李舒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92be38ae-8f3e-4b9b-ba7c-7064eb84e63f', '郊廟歌辭 讓皇帝廟樂章 迎俎', '郊廟歌辞 讓皇帝廟乐章 迎俎', '8b2ad8d8-1ac3-4174-8a77-4baa8b798a26', '唐', '["祀盛體薦，禮協粢盛。","方周假廟，用魯純牲。","捧徹祗敬，擊拊和鳴。","受釐歸胙，既戒而平。"]', '["祀盛體薦，禮協粢盛。","方周假廟，用魯純牲。","捧徹祗敬，擊拊和鳴。","受釐归胙，既戒而平。"]', '诗', 'shi', '', NULL, '郊廟歌辭 讓皇帝廟樂章 迎俎 李舒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8af69bf5-5208-4b2c-9b2c-97c904af1b2d', '郊廟歌辭 讓皇帝廟樂章 酌獻', '郊廟歌辞 讓皇帝廟乐章 酌獻', '8b2ad8d8-1ac3-4174-8a77-4baa8b798a26', '唐', '["八音具舉，三壽既盥。","潔茲宗彝，瑟彼圭瓚。","蘭肴重錯，椒醑飄散。","降胙維城，永爲藩翰。"]', '["八音具舉，三壽既盥。","潔茲宗彝，瑟彼圭瓚。","蘭肴重錯，椒醑飄散。","降胙維城，永爲藩翰。"]', '诗', 'shi', '', NULL, '郊廟歌辭 讓皇帝廟樂章 酌獻 李舒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3e0ba41-a564-4cf0-97d9-bb4185a5ace2', '郊廟歌辭 讓皇帝廟樂章 亞獻終獻', '郊廟歌辞 讓皇帝廟乐章 亞獻終獻', '8b2ad8d8-1ac3-4174-8a77-4baa8b798a26', '唐', '["秩禮有序，和音既同。","九儀不忒，三揖將終。","孝感藩后，相維辟公。","四時之典，永永無窮。"]', '["秩禮有序，和音既同。","九儀不忒，三揖將終。","孝感藩后，相維辟公。","四时之典，永永無窮。"]', '诗', 'shi', '', NULL, '郊廟歌辭 讓皇帝廟樂章 亞獻終獻 李舒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('206cead0-3581-4c90-806d-73c1988744cf', '郊廟歌辭 讓皇帝廟樂章 送神', '郊廟歌辞 讓皇帝廟乐章 送神', '8b2ad8d8-1ac3-4174-8a77-4baa8b798a26', '唐', '["奠獻已事，昏昕載分。","風搖雨散，靈衛絪緼。","龍駕帝服，上騰五雲。","泮宮復閟，寂寞無聞。"]', '["奠獻已事，昏昕載分。","风搖雨散，靈衛絪緼。","龙駕帝服，上腾五云。","泮宮复閟，寂寞無闻。"]', '诗', 'shi', '', NULL, '郊廟歌辭 讓皇帝廟樂章 送神 李舒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46a7c1f9-9435-4a65-a047-b3522122d754', '郊廟歌辭 享隱太子廟樂章 誠和', '郊廟歌辞 享隐太子廟乐章 誠和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["道閟鶴關，運纏鳩里。","門集大命，俾歆嘉祀。","禮亞六瑚，誠殫二簋。","有誠顒若，神斯戾止。"]', '["道閟鹤关，運纏鳩里。","门集大命，俾歆嘉祀。","禮亞六瑚，誠殫二簋。","有誠顒若，神斯戾止。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享隱太子廟樂章 誠和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fce85010-8fcb-42b5-8ac1-db094c76e69e', '郊廟歌辭 享隱太子廟樂章 肅和', '郊廟歌辞 享隐太子廟乐章 肅和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["歲肇春宗，乾開震長。","瑤山既寂，戾園斯享。","玉肅其事，物昭其象。","弦誦成風，笙歌合響。"]', '["歲肇春宗，乾开震长。","瑤山既寂，戾园斯享。","玉肅其事，物昭其象。","弦誦成风，笙歌合响。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享隱太子廟樂章 肅和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1dc3f1e4-38a9-44d2-b041-7818ef30f0b4', '郊廟歌辭 享隱太子廟樂章 雍和', '郊廟歌辞 享隐太子廟乐章 雍和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["明典肅陳，神居邃啓。","春伯聯事，秋官相禮。","有來雍雍，登歌濟濟。","緬維主鬯，庶歆芳醴。"]', '["明典肅陳，神居邃啓。","春伯聯事，秋官相禮。","有来雍雍，登歌濟濟。","緬維主鬯，庶歆芳醴。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享隱太子廟樂章 雍和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0853819-25ae-442f-8f48-c0bf2717023e', '郊廟歌辭 享隱太子廟樂章 舒和', '郊廟歌辞 享隐太子廟乐章 舒和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["三縣已判歌鐘列，六佾將開羽鏚分。","尚想燕飛來蔽日，終疑鶴影降凌雲。"]', '["三縣已判歌鐘列，六佾將开羽鏚分。","尚想燕飞来蔽日，終疑鹤影降凌云。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享隱太子廟樂章 舒和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('033790bd-6e98-4c99-b4b7-2f3fe8d87c93', '郊廟歌辭 享隱太子廟樂章 凱安', '郊廟歌辞 享隐太子廟乐章 凱安', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["天步昔將開，商郊初欲踐。","撫戎金陣廓，貳極瑤圖闡。","雞戟遂崇儀，龍樓期好善。","弄兵隳震業，啓聖隆嗣典。"]', '["天步昔將开，商郊初欲踐。","撫戎金陣廓，貳極瑤圖闡。","雞戟遂崇儀，龙楼期好善。","弄兵隳震業，啓聖隆嗣典。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享隱太子廟樂章 凱安 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78ae9964-a188-450b-ba7c-7c6386a2a980', '郊廟歌辭 隱太子廟樂章 迎神', '郊廟歌辞 隐太子廟乐章 迎神', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["蒼震有位，黃離蔽明。","江充禍結，戾據災成。","銜冤昔痛，贈典今榮。","享靈有秩，奉樂以迎。"]', '["蒼震有位，黄離蔽明。","江充禍結，戾據災成。","銜冤昔痛，贈典今榮。","享靈有秩，奉乐以迎。"]', '诗', 'shi', '', NULL, '郊廟歌辭 隱太子廟樂章 迎神 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('867ad8d9-f1b1-43a5-94d7-7dac74332b1f', '郊廟歌辭 隱太子廟樂章 送神', '郊廟歌辞 隐太子廟乐章 送神', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["皇情悼往，祀議增設。","鐘鼓鏗鏘，羽旄昭晰。","掌禮云備，司筵告徹。","樂以送神，靈其鑒闋。"]', '["皇情悼往，祀議增設。","鐘鼓鏗鏘，羽旄昭晰。","掌禮云備，司筵告徹。","乐以送神，靈其鑒闋。"]', '诗', 'shi', '', NULL, '郊廟歌辭 隱太子廟樂章 送神 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f03e0bf6-9cfd-4209-9617-f25c4499343a', '郊廟歌辭 享章懷太子廟樂章 迎神', '郊廟歌辞 享章懷太子廟乐章 迎神', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["副君昭象，道應黃離。","銅樓備德，玉裕成規。","仙氣靄靄，靈從師師。","前驅戾止，控鶴來儀。"]', '["副君昭象，道應黄離。","銅楼備德，玉裕成規。","仙氣靄靄，靈從師師。","前驱戾止，控鹤来儀。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享章懷太子廟樂章 迎神 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c33a6b03-6ab3-42eb-b49a-4c3327d34f3f', '郊廟歌辭 享章懷太子廟樂章 登歌酌鬯', '郊廟歌辞 享章懷太子廟乐章 登歌酌鬯', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["忠孝本著，羽翼先成。","寢門昭德，馳道爲程。","幣帛有典，容衛無聲。","司存既肅，廟享惟清。"]', '["忠孝本著，羽翼先成。","寢门昭德，驰道爲程。","幣帛有典，容衛無声。","司存既肅，廟享惟清。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享章懷太子廟樂章 登歌酌鬯 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b94c383f-7e56-4f31-97d9-f5e0b11f6bec', '郊廟歌辭 享章懷太子廟樂章 迎俎酌獻', '郊廟歌辞 享章懷太子廟乐章 迎俎酌獻', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["通三錫胤，明兩承英。","太山比赫，伊水聞笙。","宗祧是寄，禮樂其亨。","嘉辰薦俎，以發聲明。"]', '["通三錫胤，明兩承英。","太山比赫，伊水闻笙。","宗祧是寄，禮乐其亨。","嘉辰薦俎，以發声明。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享章懷太子廟樂章 迎俎酌獻 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f875d13-f28a-4fb6-8770-c599af4c1909', '郊廟歌辭 享章懷太子廟樂章 送文舞迎武舞', '郊廟歌辞 享章懷太子廟乐章 送文舞迎武舞', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["羽籥崇文禮以畢，干鏚奮武事將行。","用舍繇來其有致，壯志宣威樂太平。"]', '["羽籥崇文禮以畢，干鏚奮武事將行。","用舍繇来其有致，壯志宣威乐太平。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享章懷太子廟樂章 送文舞迎武舞 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3e2191a-e121-4ddc-a90c-f39467dabf75', '郊廟歌辭 享章懷太子廟樂章 武舞作', '郊廟歌辞 享章懷太子廟乐章 武舞作', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["綠林熾炎曆，黃虞格有苗。","沙塵驚塞外，帷幄命嫖姚。","七德干戈止，三邊雲霧消。","寶祚長無極，歌舞盛今朝。"]', '["綠林熾炎曆，黄虞格有苗。","沙塵驚塞外，帷幄命嫖姚。","七德干戈止，三邊云霧消。","寶祚长無極，歌舞盛今朝。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享章懷太子廟樂章 武舞作 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6629ab09-a177-43fc-b434-b5b5c4aca1d3', '郊廟歌辭 享懿德太子廟樂章 迎神', '郊廟歌辞 享懿德太子廟乐章 迎神', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["甲觀昭祥，畫堂升位。","禮絕羣后，望尊儲貳。","啓誦慙德，莊丕掩粹。","伊浦鳳翔，緱峰鶴至。"]', '["甲观昭祥，畫堂升位。","禮絕羣后，望尊儲貳。","啓誦慙德，莊丕掩粹。","伊浦鳳翔，緱峰鹤至。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享懿德太子廟樂章 迎神 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebaa76e9-e569-4145-bf34-2c543612c475', '郊廟歌辭 享懿德太子廟樂章 登歌酌鬯', '郊廟歌辞 享懿德太子廟乐章 登歌酌鬯', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["譽闡元儲，寄崇明兩。","玉裕雖晦，銅樓可想。","弦誦輟音，笙歌罷響。","幣帛言設，禮容無爽。"]', '["譽闡元儲，寄崇明兩。","玉裕雖晦，銅楼可想。","弦誦輟音，笙歌罷响。","幣帛言設，禮容無爽。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享懿德太子廟樂章 登歌酌鬯 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('638dc04a-2956-4d8c-9953-bd99b6f07b10', '郊廟歌辭 享懿德太子廟樂章 迎俎酌獻', '郊廟歌辞 享懿德太子廟乐章 迎俎酌獻', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["雍雍盛典，肅肅靈祠。","賓天有聖，對日無期。","飄颻羽服，掣曳雲旗。","眷言主鬯，心乎愴茲。"]', '["雍雍盛典，肅肅靈祠。","賓天有聖，对日無期。","飄颻羽服，掣曳云旗。","眷言主鬯，心乎愴茲。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享懿德太子廟樂章 迎俎酌獻 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fd8d994-fa15-4dd6-9619-af4802e819fc', '郊廟歌辭 享懿德太子廟樂章 送文舞迎武舞', '郊廟歌辞 享懿德太子廟乐章 送文舞迎武舞', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["八音協奏陳金石，六佾分行整禮容。","滄溟赴海還稱少，素月開輪即是重。"]', '["八音協奏陳金石，六佾分行整禮容。","滄溟赴海還稱少，素月开輪即是重。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享懿德太子廟樂章 送文舞迎武舞 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d95012e2-da3b-40d9-ac43-3ccd222298cc', '郊廟歌辭 享懿德太子廟樂章 武舞作', '郊廟歌辞 享懿德太子廟乐章 武舞作', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["隋季昔云終，唐年初啓聖。","纂戎將禁暴，崇儒更敷政。","威略靜三邊，仁恩覃萬姓。"]', '["隋季昔云終，唐年初啓聖。","纂戎將禁暴，崇儒更敷政。","威略静三邊，仁恩覃万姓。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享懿德太子廟樂章 武舞作 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b58d8eef-5c3d-4ffc-a8d8-1444d5788cd0', '郊廟歌辭 享節愍太子廟樂章 迎神', '郊廟歌辞 享節愍太子廟乐章 迎神', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["儲后望崇，元良寄切。","寢門是仰，馳道不絕。","仙袂雲會，靈旗電晰。","煌煌而來，禮物攸設。"]', '["儲后望崇，元良寄切。","寢门是仰，驰道不絕。","仙袂云會，靈旗電晰。","煌煌而来，禮物攸設。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享節愍太子廟樂章 迎神 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79ddee12-c5fd-4c8d-a46b-eb1d6649d850', '郊廟歌辭 享節愍太子廟樂章 登歌酌鬯', '郊廟歌辞 享節愍太子廟乐章 登歌酌鬯', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["灼灼重明，仰承元首。","既賢且哲，惟孝與友。","惟孝雖遙，靈規不朽。","禮因誠致，備絜玄酒。"]', '["灼灼重明，仰承元首。","既賢且哲，惟孝與友。","惟孝雖遙，靈規不朽。","禮因誠致，備絜玄酒。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享節愍太子廟樂章 登歌酌鬯 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ff5fdc0-c751-4486-badb-b915f2846d71', '郊廟歌辭 享節愍太子廟樂章 迎俎酌獻', '郊廟歌辞 享節愍太子廟乐章 迎俎酌獻', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["嘉薦有典，至誠莫騫。","畫梁雲亙，雕俎星連。","樂器周列，禮容備宣。","依稀如在，若未賓天。"]', '["嘉薦有典，至誠莫騫。","畫梁云亙，雕俎星連。","乐器周列，禮容備宣。","依稀如在，若未賓天。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享節愍太子廟樂章 迎俎酌獻 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d20096b1-0638-4ae2-8991-63dd8cc416f6', '郊廟歌辭 享節愍太子廟樂章 送文舞出迎武舞入', '郊廟歌辞 享節愍太子廟乐章 送文舞出迎武舞入', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["邕邕闡化憑文德，赫赫宣威藉武功。","既執羽旄先拂吹，還持玉鏚更揮空。"]', '["邕邕闡化憑文德，赫赫宣威藉武功。","既執羽旄先拂吹，還持玉鏚更揮空。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享節愍太子廟樂章 送文舞出迎武舞入 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ad961c0-606b-4c1d-ae90-257a622641a5', '郊廟歌辭 享節愍太子廟樂章 武舞作', '郊廟歌辞 享節愍太子廟乐章 武舞作', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["武德諒雍雍，由來掃寇戎。","劒光揮作電，旗影列成虹。","霧廓三邊靜，波澄四海同。","睿圖今已盛，相共舞皇風。"]', '["武德諒雍雍，由来掃寇戎。","劒光揮作電，旗影列成虹。","霧廓三邊静，波澄四海同。","睿圖今已盛，相共舞皇风。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享節愍太子廟樂章 武舞作 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc49c7e9-6335-48b7-bef3-6302b96ca84c', '郊廟歌辭 享文敬太子廟樂章 請神', '郊廟歌辞 享文敬太子廟乐章 請神', '3cc8d08d-8bdd-4dc9-aad3-531cf95b6532', '唐', '["觴牢具品，管磬有節。","祝道夤恭，神儀昭晰。","桐圭早貴，象輅追設。","聲達樂成，降歆豐潔。"]', '["觴牢具品，管磬有節。","祝道夤恭，神儀昭晰。","桐圭早貴，象輅追設。","声達乐成，降歆豐潔。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享文敬太子廟樂章 請神 許孟容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87a78b1d-6698-48af-9dee-5f1ed107b418', '郊廟歌辭 享文敬太子廟樂章 登歌', '郊廟歌辞 享文敬太子廟乐章 登歌', '5f89bf13-d1d4-4c79-a8e0-e1dfd4f2ae0e', '唐', '["歌以德發，聲以樂貴。","樂善名存，追仙禮異。","鸞旌拱修，鳳鳴合吹。","神聽皇慈，仲月皆至。"]', '["歌以德發，声以乐貴。","乐善名存，追仙禮異。","鸾旌拱修，鳳鳴合吹。","神听皇慈，仲月皆至。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享文敬太子廟樂章 登歌 陳京 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6e3064d-ee05-4ca8-b10d-30c7216efdd1', '郊廟歌辭 享文敬太子廟樂章 迎俎酌獻', '郊廟歌辞 享文敬太子廟乐章 迎俎酌獻', 'a88379cd-5098-40bc-bcbc-869e7ffe66f4', '唐', '["撰日瞻景，誠陳樂張。","禮容秩秩，羽舞煌煌。","肅將滌濯，祗薦芬芳。","永錫繁祉，思深饗嘗。"]', '["撰日瞻景，誠陳乐張。","禮容秩秩，羽舞煌煌。","肅將滌濯，祗薦芬芳。","永錫繁祉，思深饗嘗。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享文敬太子廟樂章 迎俎酌獻 馮伉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0da37a4d-2fd4-4bfd-b23f-c2aeccdfb968', '郊廟歌辭 享文敬太子廟樂章 送文舞迎武舞', '郊廟歌辞 享文敬太子廟乐章 送文舞迎武舞', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["干旄羽籥相虧蔽，一進一退殊行綴。","昔獻三雍盛禮容，今陳六佾崇儀制。"]', '["干旄羽籥相虧蔽，一進一退殊行綴。","昔獻三雍盛禮容，今陳六佾崇儀制。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享文敬太子廟樂章 送文舞迎武舞 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b3a1327-3904-4065-b735-f5bed808f6ea', '郊廟歌辭 享文敬太子廟樂章 亞獻終獻', '郊廟歌辞 享文敬太子廟乐章 亞獻終獻', '9070f068-dd7f-4d84-bee3-e8d673819cd3', '唐', '["醴齊泛尊彝，軒縣動干戚。","入室僾如在，升階虔所歷。","奮疾合威容，定利舒皦繹。","方崇廟貌禮，永被君恩錫。"]', '["醴齊泛尊彝，軒縣动干戚。","入室僾如在，升階虔所歷。","奮疾合威容，定利舒皦繹。","方崇廟貌禮，永被君恩錫。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享文敬太子廟樂章 亞獻終獻 崔邠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62ce882e-643b-4de0-9fb0-29097e6440c4', '郊廟歌辭 享文敬太子廟樂章 送神', '郊廟歌辞 享文敬太子廟乐章 送神', 'a937f111-941d-44f9-8b58-128e97c2017e', '唐', '["三獻具舉，九旗將旋。","追勞表德，罷享賓天。","風引仙管，堂虛畫筵。","芳馨常在，瞻望悠然。"]', '["三獻具舉，九旗將旋。","追勞表德，罷享賓天。","风引仙管，堂虛畫筵。","芳馨常在，瞻望悠然。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享文敬太子廟樂章 送神 張薦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f1bdb64-597c-4b05-ba77-8ed259edfb60', '郊廟歌辭 享惠昭太子廟樂章 請神', '郊廟歌辞 享惠昭太子廟乐章 請神', 'ab92e4f9-6bd3-455d-8693-dcf57b152e0c', '唐', '["嘉薦既陳，祀事孔明。","閒歌在堂，萬舞在庭。","外則盡物，內則盡誠。","鳳笙如聞，歌其潔精。"]', '["嘉薦既陳，祀事孔明。","閒歌在堂，万舞在庭。","外則尽物，內則尽誠。","鳳笙如闻，歌其潔精。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享惠昭太子廟樂章 請神 歸登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49fbd5f0-3471-45c5-a64a-bc40941ecc7f', '郊廟歌辭 享惠昭太子廟樂章 登歌', '郊廟歌辞 享惠昭太子廟乐章 登歌', '402cdba7-1f9e-4b81-ac90-26d3fa1c72ae', '唐', '["因心克孝，位震遺芬。","賓天道茂，軫懷氣分。","發祗乃祀，咳歎如聞。","二歌斯升，以詠德薰。"]', '["因心克孝，位震遺芬。","賓天道茂，軫懷氣分。","發祗乃祀，咳歎如闻。","二歌斯升，以詠德薰。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享惠昭太子廟樂章 登歌 杜羔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9634986a-188d-4cde-b2c7-41b5036d2c16', '郊廟歌辭 享惠昭太子廟樂章 迎俎酌獻', '郊廟歌辞 享惠昭太子廟乐章 迎俎酌獻', '2db0b02e-25c1-4351-9fd7-5f29fc60a673', '唐', '["既潔酒醴，聿陳熟腥。","肅將震念，昭格儲靈。","展矣禮典，薰然德馨。","愔愔管磬，亦具是聽。"]', '["既潔酒醴，聿陳熟腥。","肅將震念，昭格儲靈。","展矣禮典，薰然德馨。","愔愔管磬，亦具是听。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享惠昭太子廟樂章 迎俎酌獻 李逢吉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa313434-c420-4913-949b-ecca22c5d5a4', '郊廟歌辭 享惠昭太子廟樂章 送文舞出迎武舞入', '郊廟歌辞 享惠昭太子廟乐章 送文舞出迎武舞入', 'bd272f87-8332-47ff-b1f6-849e80d96d8f', '唐', '["喧喧金石容既缺，肅肅羽駕就行列。","緱山遺響昔所聞，廟庭進旅今攸設。"]', '["喧喧金石容既缺，肅肅羽駕就行列。","緱山遺响昔所闻，廟庭進旅今攸設。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享惠昭太子廟樂章 送文舞出迎武舞入 孟簡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6230e55-bf8d-4279-8516-d7c1480d7dcb', '郊廟歌辭 享惠昭太子廟樂章 亞獻終獻', '郊廟歌辞 享惠昭太子廟乐章 亞獻終獻', 'b882b09f-8955-4a9d-8b99-7eeb15a9a2a9', '唐', '["重輪始發祥，齒胄方興學。","冥然升紫府，鏗爾薦清樂。","奠斝致馨香，在庭紛羽籥。","禮成神既醉，髣髴緱山鶴。"]', '["重輪始發祥，齒胄方兴学。","冥然升紫府，鏗爾薦清乐。","奠斝致馨香，在庭紛羽籥。","禮成神既醉，髣髴緱山鹤。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享惠昭太子廟樂章 亞獻終獻 裴度 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d132fee-78bd-4ca6-9f30-ebe3c81c95f7', '郊廟歌辭 享惠昭太子廟樂章 送神', '郊廟歌辞 享惠昭太子廟乐章 送神', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["威儀畢陳，備樂將闋。","苞茅酒縮，膋蕭香徹。","宮臣展事，肅雍在列。","迎精送往，厥鑒昭晰。"]', '["威儀畢陳，備乐將闋。","苞茅酒縮，膋蕭香徹。","宮臣展事，肅雍在列。","迎精送往，厥鑒昭晰。"]', '诗', 'shi', '', NULL, '郊廟歌辭 享惠昭太子廟樂章 送神 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cb1c0b0-5d86-4916-8d89-6ff586e84308', '郊廟歌辭 武后崇先廟樂章', '郊廟歌辞 武后崇先廟乐章', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["先德謙撝冠昔，嚴規節素超今。","奉國忠誠每竭，承家至孝純深。","追崇懼乖尊意，顯號恐玷徽音。","既迫王公屢請，方乃俯遂羣心。","有限無由展敬，奠醑每闕親斟。","大禮虔申典冊，蘋藻敬薦翹襟。"]', '["先德謙撝冠昔，嚴規節素超今。","奉国忠誠每竭，承家至孝純深。","追崇懼乖尊意，显號恐玷徽音。","既迫王公屢請，方乃俯遂羣心。","有限無由展敬，奠醑每闕親斟。","大禮虔申典冊，蘋藻敬薦翹襟。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后崇先廟樂章 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc360c8a-07ac-45e0-bd96-bf2e8dfba5da', '郊廟歌辭 襃德廟樂章 昭德', '郊廟歌辞 襃德廟乐章 昭德', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["道赫梧宮，悲盈蒿里。","爰賜徽烈，載敷嘉祀。","享洽四時，規陳二簋。","靈應昭格，神其戾止。"]', '["道赫梧宮，悲盈蒿里。","爰賜徽烈，載敷嘉祀。","享洽四时，規陳二簋。","靈應昭格，神其戾止。"]', '诗', 'shi', '', NULL, '郊廟歌辭 襃德廟樂章 昭德 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a013e18-54cc-4269-a082-97cf543ddf65', '郊廟歌辭 襃德廟樂章 進德', '郊廟歌辞 襃德廟乐章 進德', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["塗山懿戚，媯汭崇姻。","祠筵肇啓，祭典方申。","禮以備物，樂以感神。","用隆敦敍，載穆彝倫。"]', '["塗山懿戚，媯汭崇姻。","祠筵肇啓，祭典方申。","禮以備物，乐以感神。","用隆敦敍，載穆彝倫。"]', '诗', 'shi', '', NULL, '郊廟歌辭 襃德廟樂章 進德 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ee1a9cc-06b3-43f2-843e-2c18869a92c4', '郊廟歌辭 襃德廟樂章 襃德', '郊廟歌辞 襃德廟乐章 襃德', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["家著累仁，門昭積善。","瑤篚既列，金縣式展。"]', '["家著累仁，门昭積善。","瑤篚既列，金縣式展。"]', '诗', 'shi', '', NULL, '郊廟歌辭 襃德廟樂章 襃德 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46351d94-3e29-45c5-a09a-b37e306bdfdd', '郊廟歌辭 襃德廟樂章 武舞作', '郊廟歌辞 襃德廟乐章 武舞作', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["昭昭竹殿開，奕奕蘭宮啓。","懿範隆丹掖，殊榮闢朱邸。","六佾薦徽容，三簋陳芳醴。","萬石覃貽厥，分珪崇祖禰。"]', '["昭昭竹殿开，奕奕蘭宮啓。","懿範隆丹掖，殊榮闢朱邸。","六佾薦徽容，三簋陳芳醴。","万石覃貽厥，分珪崇祖禰。"]', '诗', 'shi', '', NULL, '郊廟歌辭 襃德廟樂章 武舞作 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0012fad3-1326-4cba-95b2-d420ec573977', '郊廟歌辭 襃德廟樂章 彰德', '郊廟歌辞 襃德廟乐章 彰德', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["名隆五嶽，秩映三台。","嚴祠已備，[睟]影方迴。"]', '["名隆五嶽，秩映三台。","嚴祠已備，[睟]影方迴。"]', '诗', 'shi', '', NULL, '郊廟歌辭 襃德廟樂章 彰德 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4976a8f8-250f-4373-bdb4-19222eaf4ec0', '舞曲歌辭 功成慶善樂舞詞', '舞曲歌辞 功成慶善乐舞词', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["壽丘惟舊跡，酆邑乃前基。","粤余承累聖，懸弧亦在茲。","弱齡逢運改，提劒鬱匡時。","指麾八荒定，懷柔萬國夷。","梯山盛入欵，駕海亦來思。","單于陪武帳，日逐衛文㮰。","端扆朝四岳，無爲任百司。","霜節明秋景，輕冰結水湄。","芸黃遍原隰，禾頴積京坻。","共樂還譙宴，歡此大風詩。"]', '["壽丘惟旧跡，酆邑乃前基。","粤余承累聖，懸弧亦在茲。","弱齡逢運改，提劒鬱匡时。","指麾八荒定，懷柔万国夷。","梯山盛入欵，駕海亦来思。","單于陪武帳，日逐衛文㮰。","端扆朝四岳，無爲任百司。","霜節明秋景，轻冰結水湄。","芸黄遍原隰，禾頴積京坻。","共乐還譙宴，歡此大风诗。"]', '诗', 'shi', '', NULL, '舞曲歌辭 功成慶善樂舞詞 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bf4db06-9f1f-4d9a-bf85-57a742b46a17', '舞曲歌辭 中和樂舞詞', '舞曲歌辞 中和乐舞词', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["芳歲肇佳節，物華當仲春。","乾坤既昭泰，煙景含氤氳。","德淺荷玄貺，樂成思治人。","前庭列鐘鼓，廣殿延羣臣。","八卦隨舞意，五音轉曲新。","顧非咸池奏，庶協南風薰。","式宴禮所重，浹歡情必均。","同和諒在茲，萬國希可親。"]', '["芳歲肇佳節，物华當仲春。","乾坤既昭泰，煙景含氤氳。","德淺荷玄貺，乐成思治人。","前庭列鐘鼓，廣殿延羣臣。","八卦隨舞意，五音轉曲新。","顧非咸池奏，庶協南风薰。","式宴禮所重，浹歡情必均。","同和諒在茲，万国希可親。"]', '诗', 'shi', '', NULL, '舞曲歌辭 中和樂舞詞 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a189c45-aa28-4599-96c8-dd55e1d67a23', '舞曲歌辭 凱樂歌辭 破陣樂', '舞曲歌辞 凱乐歌辞 破陣乐', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["受律辭元首，相將討叛臣。","咸歌破陣樂，共賞太平人。"]', '["受律辞元首，相將討叛臣。","咸歌破陣乐，共賞太平人。"]', '诗', 'shi', '', NULL, '舞曲歌辭 凱樂歌辭 破陣樂 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf410866-e96c-46e5-a6af-f54971f61820', '舞曲歌辭 凱樂歌辭 應聖期', '舞曲歌辞 凱乐歌辞 應聖期', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["聖德期昌運，雍熙萬宇清。","乾坤資化育，海嶽共休明。","闢土欣耕稼，銷戈遂偃兵。","殊方歌帝澤，執贄賀昇平。"]', '["聖德期昌運，雍熙万宇清。","乾坤資化育，海嶽共休明。","闢土欣耕稼，銷戈遂偃兵。","殊方歌帝澤，執贄賀昇平。"]', '诗', 'shi', '', NULL, '舞曲歌辭 凱樂歌辭 應聖期 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55c332db-d62a-45b9-83ce-1b22f3261c7a', '舞曲歌辭 凱樂歌辭 賀聖歡', '舞曲歌辞 凱乐歌辞 賀聖歡', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["四海皇風被，千年德水清。","戎衣更不著，今日告功成。"]', '["四海皇风被，千年德水清。","戎衣更不著，今日告功成。"]', '诗', 'shi', '', NULL, '舞曲歌辭 凱樂歌辭 賀聖歡 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fe98de1-5cd1-4a24-892c-56e058583719', '舞曲歌辭 凱樂歌辭 君臣同慶樂', '舞曲歌辞 凱乐歌辞 君臣同慶乐', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["主聖開昌曆，臣忠奉大猷。","君看偃革後，便是太平秋。"]', '["主聖开昌曆，臣忠奉大猷。","君看偃革後，便是太平秋。"]', '诗', 'shi', '', NULL, '舞曲歌辭 凱樂歌辭 君臣同慶樂 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6bc971a-81b0-42db-b6e7-7f3e6d2aa250', '郊廟歌辭 梁郊祀樂章 慶和 一', '郊廟歌辞 梁郊祀乐章 慶和 一', 'a6bf682f-8894-460e-8fa3-7bf0f074de14', '唐', '["就陽位，升圓丘。","佩雙玉，御大裘。","膺天命，擁神休。","萬靈感，百祿遒。"]', '["就陽位，升圓丘。","佩雙玉，御大裘。","膺天命，擁神休。","万靈感，百祿遒。"]', '诗', 'shi', '', NULL, '郊廟歌辭 梁郊祀樂章 慶和 一 趙光逢、張衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85735127-9249-41f5-8c05-ffc89bbe34d2', '郊廟歌辭 梁郊祀樂章 慶和 二', '郊廟歌辞 梁郊祀乐章 慶和 二', 'a6bf682f-8894-460e-8fa3-7bf0f074de14', '唐', '["秉黃鉞，建朱旗。","震八表，清二儀。","帝業顯，王道夷。","受景命，啓皇基。"]', '["秉黄鉞，建朱旗。","震八表，清二儀。","帝業显，王道夷。","受景命，啓皇基。"]', '诗', 'shi', '', NULL, '郊廟歌辭 梁郊祀樂章 慶和 二 趙光逢、張衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c83d6fd3-b533-4f81-8274-cfc77d39ce77', '郊廟歌辭 梁郊祀樂章 慶和 三', '郊廟歌辞 梁郊祀乐章 慶和 三', 'a6bf682f-8894-460e-8fa3-7bf0f074de14', '唐', '["開九門，懷百神。","通肸蠁，接氤氳。","明粢薦，廣樂陳。","奠嘉璧，燎芳薪。"]', '["开九门，懷百神。","通肸蠁，接氤氳。","明粢薦，廣乐陳。","奠嘉璧，燎芳薪。"]', '诗', 'shi', '', NULL, '郊廟歌辭 梁郊祀樂章 慶和 三 趙光逢、張衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c02395c-ea77-4e2e-b356-da5a089542c7', '郊廟歌辭 梁郊祀樂章 慶和 四', '郊廟歌辞 梁郊祀乐章 慶和 四', 'a6bf682f-8894-460e-8fa3-7bf0f074de14', '唐', '["膺寶圖，執左契。","德應天，聖饗帝。","薦表衷，荷靈惠。","壽萬年，祚百世。"]', '["膺寶圖，執左契。","德應天，聖饗帝。","薦表衷，荷靈惠。","壽万年，祚百世。"]', '诗', 'shi', '', NULL, '郊廟歌辭 梁郊祀樂章 慶和 四 趙光逢、張衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72d9dcc7-c6eb-4b78-8d05-f1f3b6963937', '郊廟歌辭 梁郊祀樂章 慶和 五', '郊廟歌辞 梁郊祀乐章 慶和 五', 'a6bf682f-8894-460e-8fa3-7bf0f074de14', '唐', '["惟德動天，有感必通。","秉茲一德，禋於六宗。","欽夤寶命，恭肅禮容。","來顧來享，永穆皇風。"]', '["惟德动天，有感必通。","秉茲一德，禋於六宗。","欽夤寶命，恭肅禮容。","来顧来享，永穆皇风。"]', '诗', 'shi', '', NULL, '郊廟歌辭 梁郊祀樂章 慶和 五 趙光逢、張衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2838b215-b643-4eba-83f3-74c33b9b0a78', '郊廟歌辭 梁郊祀樂章 慶和 六', '郊廟歌辞 梁郊祀乐章 慶和 六', 'a6bf682f-8894-460e-8fa3-7bf0f074de14', '唐', '["天惟佑德，辟乃奉天。","交感斯在，昭事罔愆。","歲功已就，王道無偏。","於焉報本，是用告虔。"]', '["天惟佑德，辟乃奉天。","交感斯在，昭事罔愆。","歲功已就，王道無偏。","於焉報本，是用告虔。"]', '诗', 'shi', '', NULL, '郊廟歌辭 梁郊祀樂章 慶和 六 趙光逢、張衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aea2ebbd-30af-49d6-a669-4d2e230fbcf2', '郊廟歌辭 梁郊祀樂章 慶順', '郊廟歌辞 梁郊祀乐章 慶順', 'a6bf682f-8894-460e-8fa3-7bf0f074de14', '唐', '["聖皇戾止，天步舒遲。","乾乾睿相，穆穆皇儀。","進退必肅，陟降是祗。","六變克協，萬靈協隨。"]', '["聖皇戾止，天步舒遲。","乾乾睿相，穆穆皇儀。","進退必肅，陟降是祗。","六变克協，万靈協隨。"]', '诗', 'shi', '', NULL, '郊廟歌辭 梁郊祀樂章 慶順 趙光逢、張衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b5da87f-0b2d-4b82-8461-174658630b20', '郊廟歌辭 梁郊祀樂章 慶平', '郊廟歌辞 梁郊祀乐章 慶平', 'a6bf682f-8894-460e-8fa3-7bf0f074de14', '唐', '["天命降鑒，帝德惟馨。","享祀不忒，禮容孔明。","奠璧布幣，薦神獻精。","神佑以答，敷錫永寧。"]', '["天命降鑒，帝德惟馨。","享祀不忒，禮容孔明。","奠璧布幣，薦神獻精。","神佑以答，敷錫永寧。"]', '诗', 'shi', '', NULL, '郊廟歌辭 梁郊祀樂章 慶平 趙光逢、張衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31f00e5a-29bd-41ee-b876-1555098dc862', '郊廟歌辭 梁郊祀樂章 慶肅', '郊廟歌辞 梁郊祀乐章 慶肅', 'a6bf682f-8894-460e-8fa3-7bf0f074de14', '唐', '["籩豆簠簋，黍稷非馨。","懿茲彝器，厥德惟明。","金石匏革，以和以平。","繇此無體，期乎永寧。"]', '["籩豆簠簋，黍稷非馨。","懿茲彝器，厥德惟明。","金石匏革，以和以平。","繇此無體，期乎永寧。"]', '诗', 'shi', '', NULL, '郊廟歌辭 梁郊祀樂章 慶肅 趙光逢、張衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('323842d9-5424-473b-b736-17a756fa6bb8', '郊廟歌辭 梁郊祀樂章 慶熙', '郊廟歌辞 梁郊祀乐章 慶熙', 'a6bf682f-8894-460e-8fa3-7bf0f074de14', '唐', '["哲后躬享，旨酒斯陳。","王恭無斁，嚴祀維夤。","皇祖以配，大孝以振。","宜錫景福，永休下民。"]', '["哲后躬享，旨酒斯陳。","王恭無斁，嚴祀維夤。","皇祖以配，大孝以振。","宜錫景福，永休下民。"]', '诗', 'shi', '', NULL, '郊廟歌辭 梁郊祀樂章 慶熙 趙光逢、張衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0422e5c8-5a58-467c-9bd8-c38a585b0ac2', '郊廟歌辭 梁郊祀樂章 慶隆', '郊廟歌辞 梁郊祀乐章 慶隆', 'a6bf682f-8894-460e-8fa3-7bf0f074de14', '唐', '["恭祀上帝，于國之陽。","爵醴是荷，鴻基永昌。"]', '["恭祀上帝，于国之陽。","爵醴是荷，鴻基永昌。"]', '诗', 'shi', '', NULL, '郊廟歌辭 梁郊祀樂章 慶隆 趙光逢、張衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6947499c-32e9-4bd7-9df9-7cfb4a9b9c26', '郊廟歌辭 梁郊祀樂章 慶融', '郊廟歌辞 梁郊祀乐章 慶融', 'a6bf682f-8894-460e-8fa3-7bf0f074de14', '唐', '["道和氣兮襲氤氳，宣皇規兮彰聖神。","服遐裔兮敷質文，格苗扈兮息煙塵。"]', '["道和氣兮襲氤氳，宣皇規兮彰聖神。","服遐裔兮敷質文，格苗扈兮息煙塵。"]', '诗', 'shi', '', NULL, '郊廟歌辭 梁郊祀樂章 慶融 趙光逢、張衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4ed9fc0-2f60-4076-bdc6-10647b93bb3a', '郊廟歌辭 梁郊祀樂章 慶休', '郊廟歌辞 梁郊祀乐章 慶休', 'a6bf682f-8894-460e-8fa3-7bf0f074de14', '唐', '["大業來四夷，仁風和萬國。","白日體無私，皇天輔有德。","七旬罪已服，六月師方克。","偉哉帝道隆，終始常作則。"]', '["大業来四夷，仁风和万国。","白日體無私，皇天輔有德。","七旬罪已服，六月師方克。","偉哉帝道隆，終始常作則。"]', '诗', 'shi', '', NULL, '郊廟歌辭 梁郊祀樂章 慶休 趙光逢、張衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa9edde0-b875-4ac6-ad28-2643d36fe463', '郊廟歌辭 梁郊祀樂章 慶和', '郊廟歌辞 梁郊祀乐章 慶和', 'a6bf682f-8894-460e-8fa3-7bf0f074de14', '唐', '["煙燎升，禮容徹。","誠感達，人神悅。","靈貺彰，聖情結。","玉座寂，金爐歇。"]', '["煙燎升，禮容徹。","誠感達，人神悅。","靈貺彰，聖情結。","玉座寂，金爐歇。"]', '诗', 'shi', '', NULL, '郊廟歌辭 梁郊祀樂章 慶和 趙光逢、張衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('874cb9ab-1d1d-46d0-a2f6-ca86a74f6a8b', '郊廟歌辭 周郊祀樂章 昭順樂', '郊廟歌辞 周郊祀乐章 昭順乐', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["五兵勿用，萬國咸安。","告功圓蓋，受命雲壇。","樂鳴鳳律，禮備雞竿。","神光欲降，衆目遐觀。"]', '["五兵勿用，万国咸安。","告功圓蓋，受命云壇。","乐鳴鳳律，禮備雞竿。","神光欲降，衆目遐观。"]', '诗', 'shi', '', NULL, '郊廟歌辭 周郊祀樂章 昭順樂 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e853c39-1a72-4671-86c1-562805f0d563', '郊廟歌辭 周郊祀樂章 治順樂', '郊廟歌辞 周郊祀乐章 治順乐', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["羽衛離丹闕，金軒赴泰壇。","珠旗明月色，玉佩曉霜寒。","黼黻龍衣備，琮璜寶器完。","百神將受職，宗社保長安。"]', '["羽衛離丹闕，金軒赴泰壇。","珠旗明月色，玉佩晓霜寒。","黼黻龙衣備，琮璜寶器完。","百神將受職，宗社保长安。"]', '诗', 'shi', '', NULL, '郊廟歌辭 周郊祀樂章 治順樂 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c45a628-700b-4822-80b5-01cff6f7997b', '郊廟歌辭 周郊祀樂章 感順樂', '郊廟歌辞 周郊祀乐章 感順乐', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["明君陳大禮，展幣祀圓丘。","雅樂聲其發，祥雲色正浮。"]', '["明君陳大禮，展幣祀圓丘。","雅乐声其發，祥云色正浮。"]', '诗', 'shi', '', NULL, '郊廟歌辭 周郊祀樂章 感順樂 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ff009da-1154-46ae-bc65-af8c9372f08d', '郊廟歌辭 周郊祀樂章 禋順樂', '郊廟歌辞 周郊祀乐章 禋順乐', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["黃彝將獻，特牲預迎。","既修昭事，潛達明誠。"]', '["黄彝將獻，特牲預迎。","既修昭事，潛達明誠。"]', '诗', 'shi', '', NULL, '郊廟歌辭 周郊祀樂章 禋順樂 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da032cf6-0cbf-4ac0-89c5-ca1f30d1103c', '郊廟歌辭 周郊祀樂章 福順樂', '郊廟歌辞 周郊祀乐章 福順乐', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["相承五運，取法三才。","大禮爰展，率土咸來。","卿雲祕室，甘泉寶臺。","象樽初酌，受福不回。"]', '["相承五運，取法三才。","大禮爰展，率土咸来。","卿云祕室，甘泉寶台。","象樽初酌，受福不回。"]', '诗', 'shi', '', NULL, '郊廟歌辭 周郊祀樂章 福順樂 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4a3572e-6a8b-48dd-b783-fdcad0b18c3f', '郊廟歌辭 周郊祀樂章 福順樂', '郊廟歌辞 周郊祀乐章 福順乐', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["昊天成命，邦國盛儀。","多士齊列，六龍載馳。","壇升泰一，樂奏咸池。","高明祚德，永致昌期。"]', '["昊天成命，邦国盛儀。","多士齊列，六龙載驰。","壇升泰一，乐奏咸池。","高明祚德，永致昌期。"]', '诗', 'shi', '', NULL, '郊廟歌辭 周郊祀樂章 福順樂 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52d4576e-8c59-4eb6-b447-418a531cb97e', '郊廟歌辭 周郊祀樂章 福順樂', '郊廟歌辞 周郊祀乐章 福順乐', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["上天垂景貺，哲后舉鸞觴。","明德今方祚，邦家萬世昌。"]', '["上天垂景貺，哲后舉鸾觴。","明德今方祚，邦家万世昌。"]', '诗', 'shi', '', NULL, '郊廟歌辭 周郊祀樂章 福順樂 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ca290b9-18af-4403-bdc7-00c6d0aa3211', '郊廟歌辭 周郊祀樂章 忠順樂', '郊廟歌辞 周郊祀乐章 忠順乐', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["木鐸敷音文德昌，朱干成列武功彰。","雷鼗鷺羽今休用，玉鏚相參正發揚。"]', '["木鐸敷音文德昌，朱干成列武功彰。","雷鼗鷺羽今休用，玉鏚相參正發揚。"]', '诗', 'shi', '', NULL, '郊廟歌辭 周郊祀樂章 忠順樂 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae1d49cc-efe9-4014-ad98-8417fedced83', '郊廟歌辭 周郊祀樂章 武舞樂', '郊廟歌辞 周郊祀乐章 武舞乐', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["圭瓚方陳禮，干旄乃象功。","成文非羽籥，猛勢若羆熊。"]', '["圭瓚方陳禮，干旄乃象功。","成文非羽籥，猛勢若羆熊。"]', '诗', 'shi', '', NULL, '郊廟歌辭 周郊祀樂章 武舞樂 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5c60e4b-e1c7-4071-8d05-b4e786788e12', '郊廟歌辭 周郊祀樂章 昭順樂', '郊廟歌辞 周郊祀乐章 昭順乐', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["雲門孤竹，蒼璧黃琮。","既祀天地，克配祖宗。","虔修盛禮，仰荅玄功。","神歸碧落，福降無窮。"]', '["云门孤竹，蒼璧黄琮。","既祀天地，克配祖宗。","虔修盛禮，仰荅玄功。","神归碧落，福降無窮。"]', '诗', 'shi', '', NULL, '郊廟歌辭 周郊祀樂章 昭順樂 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a53428d-1ee1-4404-81a3-8aeaae4894fa', '郊廟歌辭 梁太廟樂舞辭 開平舞', '郊廟歌辞 梁太廟乐舞辞 开平舞', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["黍稷馨，醴𨣧清。","牲牷潔，金石鏗。","恭祀事，結皇情。","神來格，歌頌聲。"]', '["黍稷馨，醴𨣧清。","牲牷潔，金石鏗。","恭祀事，結皇情。","神来格，歌頌声。"]', '诗', 'shi', '', NULL, '郊廟歌辭 梁太廟樂舞辭 開平舞 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6c8f066-5e4e-44d0-853d-13902a670a69', '郊廟歌辭 梁太廟樂舞辭 皇帝行', '郊廟歌辞 梁太廟乐舞辞 皇帝行', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["莫高者天，攀躋弗克。","隮天有方，累仁積德。","祖宗隆之，子孫履之。","配天明祀，永永孝思。"]', '["莫高者天，攀躋弗克。","隮天有方，累仁積德。","祖宗隆之，子孫履之。","配天明祀，永永孝思。"]', '诗', 'shi', '', NULL, '郊廟歌辭 梁太廟樂舞辭 皇帝行 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64e7b48a-305f-4d78-a810-c84a76b7b348', '郊廟歌辭 梁太廟樂舞辭 帝盥', '郊廟歌辞 梁太廟乐舞辞 帝盥', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["莊肅蒞事，周旋禮容。","裸鬯嚴潔，穆穆雍雍。"]', '["莊肅蒞事，周旋禮容。","裸鬯嚴潔，穆穆雍雍。"]', '诗', 'shi', '', NULL, '郊廟歌辭 梁太廟樂舞辭 帝盥 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('630ab837-d414-4cce-bf80-bc615a6c15fd', '郊廟歌辭 梁太廟樂舞辭 登歌', '郊廟歌辞 梁太廟乐舞辞 登歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["於赫我皇，建中立極。","動以武功，靜以文德。","昭事上帝，歡心萬國。","大報嚴禋，四海述職。"]', '["於赫我皇，建中立極。","动以武功，静以文德。","昭事上帝，歡心万国。","大報嚴禋，四海述職。"]', '诗', 'shi', '', NULL, '郊廟歌辭 梁太廟樂舞辭 登歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f87f89bd-21a1-4861-9590-eb27a2888aa2', '郊廟歌辭 梁太廟樂舞辭 大合舞', '郊廟歌辞 梁太廟乐舞辞 大合舞', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["於穆皇祖，濬哲雍熙。","美溢中夏，化被南陲。","后稷累德，公劉創基。","肇興九廟，樂合來儀。"]', '["於穆皇祖，濬哲雍熙。","美溢中夏，化被南陲。","后稷累德，公劉創基。","肇兴九廟，乐合来儀。"]', '诗', 'shi', '', NULL, '郊廟歌辭 梁太廟樂舞辭 大合舞 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5f1c26b-b71b-41d9-a261-95b0f036fe9c', '郊廟歌辭 梁太廟樂舞辭 象功舞', '郊廟歌辞 梁太廟乐舞辞 象功舞', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["天地合德，睿聖昭彰。","累贈太傅，俄登魏王。","雄名不朽，奕葉而光。","建國之兆，君臨萬方。"]', '["天地合德，睿聖昭彰。","累贈太傅，俄登魏王。","雄名不朽，奕葉而光。","建国之兆，君臨万方。"]', '诗', 'shi', '', NULL, '郊廟歌辭 梁太廟樂舞辭 象功舞 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32a6054f-b534-4e84-b350-3ac909640f93', '郊廟歌辭 梁太廟樂舞辭 來儀舞', '郊廟歌辞 梁太廟乐舞辞 来儀舞', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["於赫帝命，應天順人。","亭育品彙，賓禮百神。","洪基永固，景命惟新。","肅恭孝享，祚我生民。"]', '["於赫帝命，應天順人。","亭育品彙，賓禮百神。","洪基永固，景命惟新。","肅恭孝享，祚我生民。"]', '诗', 'shi', '', NULL, '郊廟歌辭 梁太廟樂舞辭 來儀舞 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('826ce190-8078-4566-abe8-cd6b0f008072', '郊廟歌辭 梁太廟樂舞辭 昭德舞', '郊廟歌辞 梁太廟乐舞辞 昭德舞', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["肅肅文考，源濬派長。","漢稱誕季，周實生昌。","奄有四海，超彼百王。","笙鏞迭奏，禮物熒煌。"]', '["肅肅文考，源濬派长。","漢稱誕季，周實生昌。","奄有四海，超彼百王。","笙鏞迭奏，禮物熒煌。"]', '诗', 'shi', '', NULL, '郊廟歌辭 梁太廟樂舞辭 昭德舞 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ef3f8b3-47d4-46fc-a4e6-1e5f5409ca4b', '郊廟歌辭 梁太廟樂舞辭 飲福', '郊廟歌辞 梁太廟乐舞辞 饮福', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["戛玉摐金永頌聲，檿絲孤竹和且清。","靈歆醉止犧象盈，自天降福千萬齡。"]', '["戛玉摐金永頌声，檿絲孤竹和且清。","靈歆醉止犧象盈，自天降福千万齡。"]', '诗', 'shi', '', NULL, '郊廟歌辭 梁太廟樂舞辭 飲福 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bee147ae-b09f-4b5b-a916-8297f1584642', '郊廟歌辭 梁太廟樂舞辭 撤豆', '郊廟歌辞 梁太廟乐舞辞 撤豆', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["笙鏞洋洋，庭燎煌煌。","明星有爛，祝史下堂。","[籩]豆斯撤，禮容有章。","克勤克儉，無怠無荒。"]', '["笙鏞洋洋，庭燎煌煌。","明星有爛，祝史下堂。","[籩]豆斯撤，禮容有章。","克勤克儉，無怠無荒。"]', '诗', 'shi', '', NULL, '郊廟歌辭 梁太廟樂舞辭 撤豆 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54a1868d-5896-4ede-81ee-9793077ce6a2', '郊廟歌辭 梁太廟樂舞辭 送神', '郊廟歌辞 梁太廟乐舞辞 送神', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["其降無從，其往無蹤。","黍稷非馨，有感必通。","赫奕令德，髣髴睟容。","再拜慌忽，遐想昊穹。"]', '["其降無從，其往無蹤。","黍稷非馨，有感必通。","赫奕令德，髣髴睟容。","再拜慌忽，遐想昊穹。"]', '诗', 'shi', '', NULL, '郊廟歌辭 梁太廟樂舞辭 送神 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3efeffba-63c5-4de4-90d4-203e176ea4b6', '郊廟歌辭 後唐宗廟樂舞辭 昭德舞', '郊廟歌辞 後唐宗廟乐舞辞 昭德舞', '4d0b284d-d3d4-4585-9047-27621033b54e', '唐', '["懿彼明德，赫赫煌煌。","名高閫域，功著旂常。","道符休泰，運叶祺祥。","慶傳萬祀，以播耿光。"]', '["懿彼明德，赫赫煌煌。","名高閫域，功著旂常。","道符休泰，運叶祺祥。","慶傳万祀，以播耿光。"]', '诗', 'shi', '', NULL, '郊廟歌辭 後唐宗廟樂舞辭 昭德舞 崔居儉、盧文紀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c459ade7-f1ec-449d-9280-f885c9680769', '郊廟歌辭 後唐宗廟樂舞辭 文明舞', '郊廟歌辞 後唐宗廟乐舞辞 文明舞', '4d0b284d-d3d4-4585-9047-27621033b54e', '唐', '["帝業光揚，皇圖翕赫。","聖德孔彰，神功不測。","信及豚魚，恩霑動植。","懿範鴻名，傳之萬億。"]', '["帝業光揚，皇圖翕赫。","聖德孔彰，神功不測。","信及豚鱼，恩霑动植。","懿範鴻名，傳之万億。"]', '诗', 'shi', '', NULL, '郊廟歌辭 後唐宗廟樂舞辭 文明舞 崔居儉、盧文紀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4562669-eb6d-49db-9be9-7e0188a5607e', '郊廟歌辭 後唐宗廟樂舞辭 應天舞', '郊廟歌辞 後唐宗廟乐舞辞 應天舞', '4d0b284d-d3d4-4585-9047-27621033b54e', '唐', '["晉國肇興，雄圖再固。","黼黻帝道，金玉王度。","皇天無親，惟德是輔。","載誕英明，永光聖祚。"]', '["晉国肇兴，雄圖再固。","黼黻帝道，金玉王度。","皇天無親，惟德是輔。","載誕英明，永光聖祚。"]', '诗', 'shi', '', NULL, '郊廟歌辭 後唐宗廟樂舞辭 應天舞 崔居儉、盧文紀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41ee0b46-12c6-47ea-a6c5-e4aac44c2fc4', '郊廟歌辭 後唐宗廟樂舞辭 永平舞', '郊廟歌辞 後唐宗廟乐舞辞 永平舞', '4d0b284d-d3d4-4585-9047-27621033b54e', '唐', '["慶傳瓚祚，位正瑤圖。","功宣四海，化被八區。","靜彰帝道，動合乾符。","千秋萬祀，永荷昭蘇。"]', '["慶傳瓚祚，位正瑤圖。","功宣四海，化被八區。","静彰帝道，动合乾符。","千秋万祀，永荷昭蘇。"]', '诗', 'shi', '', NULL, '郊廟歌辭 後唐宗廟樂舞辭 永平舞 崔居儉、盧文紀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6efdeafd-8fbd-40a2-83f3-7a570f43a2e8', '郊廟歌辭 後唐宗廟樂舞辭 武成舞', '郊廟歌辞 後唐宗廟乐舞辞 武成舞', '4d0b284d-d3d4-4585-9047-27621033b54e', '唐', '["艱難王業，返正皇唐。","先天再造，却日重光。","漢紹世祖，夏資少康。","功成德茂，率祀無疆。"]', '["艱难王業，返正皇唐。","先天再造，却日重光。","漢紹世祖，夏資少康。","功成德茂，率祀無疆。"]', '诗', 'shi', '', NULL, '郊廟歌辭 後唐宗廟樂舞辭 武成舞 崔居儉、盧文紀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc43dea3-2c32-4f99-a810-7ed8854a3b9d', '郊廟歌辭 後唐宗廟樂舞辭 雍煕舞', '郊廟歌辞 後唐宗廟乐舞辞 雍煕舞', '4d0b284d-d3d4-4585-9047-27621033b54e', '唐', '["仁君御宇，寰海謐清。","運符武德，道協文明。","九成式敍，百度惟貞。","金門積慶，玉葉傳榮。"]', '["仁君御宇，寰海謐清。","運符武德，道協文明。","九成式敍，百度惟貞。","金门積慶，玉葉傳榮。"]', '诗', 'shi', '', NULL, '郊廟歌辭 後唐宗廟樂舞辭 雍煕舞 崔居儉、盧文紀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ab117a7-0b6d-43fc-8ff4-412ef61802de', '郊廟歌辭 漢宗廟樂舞辭 武德舞', '郊廟歌辞 漢宗廟乐舞辞 武德舞', '5ea269ad-d631-4e05-b4cc-36254d0106b0', '唐', '["明明我祖，天集休明。","神母夜哭，彤雲晝興。","籩豆有踐，管籥斯登。","孝孫致告，神其降靈。"]', '["明明我祖，天集休明。","神母夜哭，彤云晝兴。","籩豆有踐，管籥斯登。","孝孫致告，神其降靈。"]', '诗', 'shi', '', NULL, '郊廟歌辭 漢宗廟樂舞辭 武德舞 張昭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07232e95-0109-4302-ad90-957ca3c2cd2f', '郊廟歌辭 漢宗廟樂舞辭 靈長舞', '郊廟歌辞 漢宗廟乐舞辞 靈长舞', '5ea269ad-d631-4e05-b4cc-36254d0106b0', '唐', '["天降祥，漢祚昌。","火炎上，水靈長。","建廟社，潔蒸嘗。","羅鐘石，儼珩璜。","陳玉豆，酌金觴。","氣昭感，德馨香。","祗洛汭，瞻晉陽。","降吾祖，福穰穰。"]', '["天降祥，漢祚昌。","火炎上，水靈长。","建廟社，潔蒸嘗。","羅鐘石，儼珩璜。","陳玉豆，酌金觴。","氣昭感，德馨香。","祗洛汭，瞻晉陽。","降吾祖，福穰穰。"]', '诗', 'shi', '', NULL, '郊廟歌辭 漢宗廟樂舞辭 靈長舞 張昭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bf39a54-a034-4425-8044-d7d70738f029', '郊廟歌辭 漢宗廟樂舞辭 積善舞', '郊廟歌辞 漢宗廟乐舞辞 積善舞', '5ea269ad-d631-4e05-b4cc-36254d0106b0', '唐', '["黍稷斯馨，祖德惟明。","蛇告赤帝，龜謀大橫。","雲行雨施，天成地平。","造我家邦，斡我璿衡。","陶匏在御，醍盎惟精。","或戛或擊，載炮載烹。","飲福受胙，舞降歌迎。","滔滔不竭，洪惟水行。"]', '["黍稷斯馨，祖德惟明。","蛇告赤帝，龟謀大橫。","云行雨施，天成地平。","造我家邦，斡我璿衡。","陶匏在御，醍盎惟精。","或戛或擊，載炮載烹。","饮福受胙，舞降歌迎。","滔滔不竭，洪惟水行。"]', '诗', 'shi', '', NULL, '郊廟歌辭 漢宗廟樂舞辭 積善舞 張昭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4866e70c-51c9-48bb-a2b4-d4d975e338fe', '郊廟歌辭 漢宗廟樂舞辭 顯仁舞', '郊廟歌辞 漢宗廟乐舞辞 显仁舞', '5ea269ad-d631-4e05-b4cc-36254d0106b0', '唐', '["運極金行謝，天資水德隆。","禮神鄜畤館，布政未央宮。","詰旦備明祀，登歌荅茂功。","雲軒臨降久，星俎薦陳豐。","靄靄沈檀霧，鏗鏘環佩風。","熒煌升藻藉，肸蠁轉珠櫳。","尊祖咸韶備，貽孫書軌同。","京坻長有積，宗社享無窮。"]', '["運極金行謝，天資水德隆。","禮神鄜畤館，布政未央宮。","詰旦備明祀，登歌荅茂功。","云軒臨降久，星俎薦陳豐。","靄靄沈檀霧，鏗鏘环佩风。","熒煌升藻藉，肸蠁轉珠櫳。","尊祖咸韶備，貽孫书軌同。","京坻长有積，宗社享無窮。"]', '诗', 'shi', '', NULL, '郊廟歌辭 漢宗廟樂舞辭 顯仁舞 張昭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('792ab2c6-7baf-427b-bccf-e9e58537de8e', '郊廟歌辭 漢宗廟樂舞辭 章慶舞', '郊廟歌辞 漢宗廟乐舞辞 章慶舞', '5ea269ad-d631-4e05-b4cc-36254d0106b0', '唐', '["罘罳曉唱雞人，三牲八簋斯陳。","霧集瑤階瑣闥，香生綺席華茵。","珠佩貂璫熠爚，羽旄干戚紛綸。","酌鬯既終三獻，凝旒何止千春。","阿閣長棲綵鳳，郊宮疊奏祥麟。","赤伏英靈未泯，玄圭運祚重新。","玉斝犧樽瀲灩，龍旂鳳轄逡巡。","瞻望月遊冠冕，猶疑蒼野回輪。"]', '["罘罳晓唱雞人，三牲八簋斯陳。","霧集瑤階瑣闥，香生綺席华茵。","珠佩貂璫熠爚，羽旄干戚紛綸。","酌鬯既終三獻，凝旒何止千春。","阿閣长棲綵鳳，郊宮叠奏祥麟。","赤伏英靈未泯，玄圭運祚重新。","玉斝犧樽瀲灩，龙旂鳳轄逡巡。","瞻望月游冠冕，猶疑蒼野回輪。"]', '诗', 'shi', '', NULL, '郊廟歌辭 漢宗廟樂舞辭 章慶舞 張昭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f12b2f5-d237-4507-aa77-3eaab9fa5a8c', '郊廟歌辭 漢宗廟樂舞辭 觀德舞', '郊廟歌辞 漢宗廟乐舞辞 观德舞', '5ea269ad-d631-4e05-b4cc-36254d0106b0', '唐', '["高廟明靈再啓圖，金根玉輅幸神都。","巢阿丹凰銜書命，入昴飛星獻寶符。","正換熏弦娛赤子，忽登仙駕泣蒼梧。","薦櫻鶴館笳簫咽，酌鬯金楹劒佩趨。","星俎雲罍兼魯禮，朱干象箾雜巴渝。","氤氳龍麝交青瑣，髣髴[錫]鑾下蘂珠。","薦豆奉觴親玉几，配天合祖耀璿樞。","受釐飲酒皇歡洽，仰俟餘靈泰九區。"]', '["高廟明靈再啓圖，金根玉輅幸神都。","巢阿丹凰銜书命，入昴飞星獻寶符。","正換熏弦娛赤子，忽登仙駕泣蒼梧。","薦櫻鹤館笳簫咽，酌鬯金楹劒佩趨。","星俎云罍兼魯禮，朱干象箾杂巴渝。","氤氳龙麝交青瑣，髣髴[錫]鑾下蘂珠。","薦豆奉觴親玉几，配天合祖耀璿樞。","受釐饮酒皇歡洽，仰俟餘靈泰九區。"]', '诗', 'shi', '', NULL, '郊廟歌辭 漢宗廟樂舞辭 觀德舞 張昭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8833a3c-5382-478d-aa30-1fb1f4a93a3c', '郊廟歌辭 周宗廟樂舞辭 肅順', '郊廟歌辞 周宗廟乐舞辞 肅順', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["我后至孝，祗謁祖先。","仰瞻廟貌，夙設宮懸。","朱弦疏越，羽舞迴旋。","神其來格，明祀惟虔。"]', '["我后至孝，祗謁祖先。","仰瞻廟貌，夙設宮懸。","朱弦疏越，羽舞迴旋。","神其来格，明祀惟虔。"]', '诗', 'shi', '', NULL, '郊廟歌辭 周宗廟樂舞辭 肅順 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a20f5b10-ab9d-4422-b68e-e0fbfa4f3992', '郊廟歌辭 周宗廟樂舞辭 治順', '郊廟歌辞 周宗廟乐舞辞 治順', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["清廟將入，衮服是依。","載行載止，令行令儀。","永終就養，空極孝思。","瞻望如在，顧復長違。"]', '["清廟將入，衮服是依。","載行載止，令行令儀。","永終就養，空極孝思。","瞻望如在，顧复长違。"]', '诗', 'shi', '', NULL, '郊廟歌辭 周宗廟樂舞辭 治順 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40427e69-1d6a-4d07-8428-f3cbda689880', '郊廟歌辭 周宗廟樂舞辭 肅雍舞', '郊廟歌辞 周宗廟乐舞辞 肅雍舞', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["周道載興，象日之明。","萬邦咸慶，百穀用成。","於穆聖祖，祗薦鴻名。","祀於廟社，陳其犧牲。","進旅退旅，皇武之形。","一倡三歎，朱弦之聲。","以妥以侑，既和且平。","至誠潛達，介福攸寧。"]', '["周道載兴，象日之明。","万邦咸慶，百穀用成。","於穆聖祖，祗薦鴻名。","祀於廟社，陳其犧牲。","進旅退旅，皇武之形。","一倡三歎，朱弦之声。","以妥以侑，既和且平。","至誠潛達，介福攸寧。"]', '诗', 'shi', '', NULL, '郊廟歌辭 周宗廟樂舞辭 肅雍舞 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1db83204-895b-41ca-9ad5-502106899bf4', '郊廟歌辭 周宗廟樂舞辭 章德舞', '郊廟歌辞 周宗廟乐舞辞 章德舞', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["清廟新，展嚴禋。","恭祖德，厚人倫。","雅樂薦，禮器陳。","儼皇尸，列虞賓。","神如在，聲不聞。","享必信，貌惟夤。","想龍服，奠犧樽。","禮既備，慶來臻。"]', '["清廟新，展嚴禋。","恭祖德，厚人倫。","雅乐薦，禮器陳。","儼皇尸，列虞賓。","神如在，声不闻。","享必信，貌惟夤。","想龙服，奠犧樽。","禮既備，慶来臻。"]', '诗', 'shi', '', NULL, '郊廟歌辭 周宗廟樂舞辭 章德舞 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8e557fd-6b68-47b3-b14f-b26de587fe6b', '郊廟歌辭 周宗廟樂舞辭 善慶舞', '郊廟歌辞 周宗廟乐舞辞 善慶舞', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["卜世長，帝祚昌。","定中國，服四方。","修明祀，從舊章。","奏激楚，轉清商。","羅俎豆，列簪裳。","歌纍纍，容皇皇。","望來格，降休祥。","祝敢告，壽無疆。"]', '["卜世长，帝祚昌。","定中国，服四方。","修明祀，從旧章。","奏激楚，轉清商。","羅俎豆，列簪裳。","歌纍纍，容皇皇。","望来格，降休祥。","祝敢告，壽無疆。"]', '诗', 'shi', '', NULL, '郊廟歌辭 周宗廟樂舞辭 善慶舞 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('640ab086-c340-4b15-8669-15ba50c0689d', '郊廟歌辭 周宗廟樂舞辭 觀成舞', '郊廟歌辞 周宗廟乐舞辞 观成舞', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["穆穆王國，奕奕神功。","毖祀載展，明德有融。","彝樽斯滿，簠簋斯豐。","紛絺旄羽，鏘洋磬鐘。","或升或降，克和克同。","孔惠之禮，必肅之容。","錫以純嘏，祚其允恭。","神保是饗，萬世無窮。"]', '["穆穆王国，奕奕神功。","毖祀載展，明德有融。","彝樽斯满，簠簋斯豐。","紛絺旄羽，鏘洋磬鐘。","或升或降，克和克同。","孔惠之禮，必肅之容。","錫以純嘏，祚其允恭。","神保是饗，万世無窮。"]', '诗', 'shi', '', NULL, '郊廟歌辭 周宗廟樂舞辭 觀成舞 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef905ab2-4dae-4b94-9295-1d10156acfaf', '郊廟歌辭 周宗廟樂舞辭 明德舞', '郊廟歌辞 周宗廟乐舞辞 明德舞', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["惟彼岐陽，德大流光。","載造周室，澤及遐荒。","於鑠聖祖，上帝是皇。","迺聖迺神，知微知彰。","新廟奕奕，豐年穰穰。","取彼血膋，以往蒸嘗。","黍稷惟馨，籩豆大房。","工祝致告，受福無疆。"]', '["惟彼岐陽，德大流光。","載造周室，澤及遐荒。","於鑠聖祖，上帝是皇。","迺聖迺神，知微知彰。","新廟奕奕，豐年穰穰。","取彼血膋，以往蒸嘗。","黍稷惟馨，籩豆大房。","工祝致告，受福無疆。"]', '诗', 'shi', '', NULL, '郊廟歌辭 周宗廟樂舞辭 明德舞 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed40a913-e197-4ac1-85bd-d82dd147bede', '郊廟歌辭 周宗廟樂舞辭 咸順', '郊廟歌辞 周宗廟乐舞辞 咸順', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["萬舞咸列，三階克清。","貫珠一倡，擊石九成。","盈觴雖酌，靈坐無形。","永懷我祖，達其孝誠。"]', '["万舞咸列，三階克清。","貫珠一倡，擊石九成。","盈觴雖酌，靈坐無形。","永懷我祖，達其孝誠。"]', '诗', 'shi', '', NULL, '郊廟歌辭 周宗廟樂舞辭 咸順 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0b0a9b7-a1ef-4cf7-b1c8-c9f205db19e2', '郊廟歌辭 周宗廟樂舞辭 禋順', '郊廟歌辞 周宗廟乐舞辞 禋順', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["旨酒既獻，嘉殽乃迎。","振其鼗鼓，潔以鉶羹。","肇禋肇祀，或炮或烹。","皇尸儼若，保饗是明。"]', '["旨酒既獻，嘉殽乃迎。","振其鼗鼓，潔以鉶羹。","肇禋肇祀，或炮或烹。","皇尸儼若，保饗是明。"]', '诗', 'shi', '', NULL, '郊廟歌辭 周宗廟樂舞辭 禋順 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2144751c-5633-4d58-b0bd-5dc2f044b83d', '郊廟歌辭 周宗廟樂舞辭 福順', '郊廟歌辞 周宗廟乐舞辞 福順', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["新廟奕奕，金奏洋洋。","享于祖考，循彼典章。","清酤特滿，嘉玉騰光。","神醉既告，帝祉無疆。"]', '["新廟奕奕，金奏洋洋。","享于祖考，循彼典章。","清酤特满，嘉玉腾光。","神醉既告，帝祉無疆。"]', '诗', 'shi', '', NULL, '郊廟歌辭 周宗廟樂舞辭 福順 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6229fb2d-8df5-4435-9aae-b41a928a4d74', '郊廟歌辭 周宗廟樂舞辭 忠順', '郊廟歌辞 周宗廟乐舞辞 忠順', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["稱文既表溫柔德，示武須成蹈厲容。","綴兆疾舒皆應節，明明我祖樂無窮。"]', '["稱文既表溫柔德，示武須成蹈厲容。","綴兆疾舒皆應節，明明我祖乐無窮。"]', '诗', 'shi', '', NULL, '郊廟歌辭 周宗廟樂舞辭 忠順 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42500782-6469-41ae-aeae-ecaba64511e1', '郊廟歌辭  善勝舞', '郊廟歌辞  善勝舞', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["聖祖累功，福鍾來裔。","持羽執干，舞文不廢。"]', '["聖祖累功，福鍾来裔。","持羽執干，舞文不廢。"]', '诗', 'shi', '', NULL, '郊廟歌辭  善勝舞 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00f241fc-a107-454f-81fa-f0ac4893d155', '郊廟歌辭  禋順', '郊廟歌辞  禋順', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["禮畢祀先，香散几筵。","罷舞干戚，收撤豆籩。"]', '["禮畢祀先，香散几筵。","罷舞干戚，收撤豆籩。"]', '诗', 'shi', '', NULL, '郊廟歌辭  禋順 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e46c92f3-c08f-41a9-9e61-2d2a4e23ebce', '郊廟歌辭  肅順', '郊廟歌辞  肅順', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["樂奏四順，福受萬年。","神歸碧天，庭餘瑞煙。"]', '["乐奏四順，福受万年。","神归碧天，庭餘瑞煙。"]', '诗', 'shi', '', NULL, '郊廟歌辭  肅順 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed452c0c-f893-4743-80ff-cd9170831490', '郊廟歌辭 晉朝饗樂章 初舉酒文同樂', '郊廟歌辞 晉朝饗乐章 初舉酒文同乐', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["赫矣昌運，明哉聖王。","文興墜典，禮復舊章。","鴛鸞濟濟，鳥獸蹌蹌。","一人有慶，萬福無疆。"]', '["赫矣昌運，明哉聖王。","文兴墜典，禮复旧章。","鴛鸾濟濟，鸟獸蹌蹌。","一人有慶，万福無疆。"]', '诗', 'shi', '', NULL, '郊廟歌辭 晉朝饗樂章 初舉酒文同樂 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48105ca4-28d4-4477-a6c3-73ae21a928fb', '郊廟歌辭 晉朝饗樂章 舉酒', '郊廟歌辞 晉朝饗乐章 舉酒', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["大明御宇，至德動天。","君臣慶會，禮樂昭宣。","劒佩成列，金石在縣。","椒觴再獻，寶曆萬年。"]', '["大明御宇，至德动天。","君臣慶會，禮乐昭宣。","劒佩成列，金石在縣。","椒觴再獻，寶曆万年。"]', '诗', 'shi', '', NULL, '郊廟歌辭 晉朝饗樂章 舉酒 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20bc12d7-5879-4e6d-a3ec-45b0034abe7b', '郊廟歌辭 晉朝饗樂章 再舉酒', '郊廟歌辞 晉朝饗乐章 再舉酒', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["朝野無事，寰瀛大康。","聖人有作，盛禮重光。","萬國執玉，千官奉觴。","南山永固，地久天長。"]', '["朝野無事，寰瀛大康。","聖人有作，盛禮重光。","万国執玉，千官奉觴。","南山永固，地久天长。"]', '诗', 'shi', '', NULL, '郊廟歌辭 晉朝饗樂章 再舉酒 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f84ae8f0-fb73-470d-abe6-0e7415d9a96e', '郊廟歌辭 晉朝饗樂章 四舉酒', '郊廟歌辞 晉朝饗乐章 四舉酒', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["八表歡無事，三秋賀有成。","照臨同日遠，渥澤並雲行。","河變千年色，山呼萬歲聲。","願修封岱禮，方以稱文明。"]', '["八表歡無事，三秋賀有成。","照臨同日远，渥澤並云行。","河变千年色，山呼万歲声。","願修封岱禮，方以稱文明。"]', '诗', 'shi', '', NULL, '郊廟歌辭 晉朝饗樂章 四舉酒 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f407039-aaf9-41fe-a393-af670d5ff23c', '郊廟歌辭 晉朝饗樂章 羣臣酒行歌 一', '郊廟歌辞 晉朝饗乐章 羣臣酒行歌 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["劒佩儼如林，齊傾拱北心。","渥恩頒美祿，咸濩聽和音。","一德君臣合，重瞳日月臨。","歌時兼樂聖，唯待贊泥金。"]', '["劒佩儼如林，齊傾拱北心。","渥恩頒美祿，咸濩听和音。","一德君臣合，重瞳日月臨。","歌时兼乐聖，唯待贊泥金。"]', '诗', 'shi', '', NULL, '郊廟歌辭 晉朝饗樂章 羣臣酒行歌 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f4d2f20-a7ac-4310-b2d5-3fb079011272', '郊廟歌辭 晉朝饗樂章 羣臣酒行歌 二', '郊廟歌辞 晉朝饗乐章 羣臣酒行歌 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["萬國咸歸禹，千官共祝堯。","拜恩瞻鳳扆，傾耳聽雲韶。","運啓金行遠，時和玉燭調。","酒酣齊抃舞，同賀聖明朝。"]', '["万国咸归禹，千官共祝堯。","拜恩瞻鳳扆，傾耳听云韶。","運啓金行远，时和玉燭調。","酒酣齊抃舞，同賀聖明朝。"]', '诗', 'shi', '', NULL, '郊廟歌辭 晉朝饗樂章 羣臣酒行歌 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a756cea-8b47-419c-99d0-06c17359dc05', '郊廟歌辭 晉朝饗樂章 羣臣酒行歌 三', '郊廟歌辞 晉朝饗乐章 羣臣酒行歌 三', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["令節陳高會，羣臣侍御筵。","玉墀留愛景，金殿靄祥煙。","振鷺涵天澤，靈禽下樂懸。","聖明無一事，何處讓堯年。"]', '["令節陳高會，羣臣侍御筵。","玉墀留愛景，金殿靄祥煙。","振鷺涵天澤，靈禽下乐懸。","聖明無一事，何处讓堯年。"]', '诗', 'shi', '', NULL, '郊廟歌辭 晉朝饗樂章 羣臣酒行歌 三 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48f870b0-fa59-43e1-8ef2-6c58dd86f6a3', '郊廟歌辭 周朝饗樂章 忠順', '郊廟歌辞 周朝饗乐章 忠順', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["歲迎更始，節及朝元。","冕旒仰止，冠劒相連。","八音合奏，萬物齊宣。","常陳盛禮，願永千年。"]', '["歲迎更始，節及朝元。","冕旒仰止，冠劒相連。","八音合奏，万物齊宣。","常陳盛禮，願永千年。"]', '诗', 'shi', '', NULL, '郊廟歌辭 周朝饗樂章 忠順 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('805b734f-4a62-45df-b725-0b775bb116d9', '郊廟歌辭 周朝饗樂章 忠順', '郊廟歌辞 周朝饗乐章 忠順', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["明君當宁，列辟奉觴。","雲容表瑞，日影初長。","衣冠濟濟，鐘磬洋洋。","令儀克盛，嘉會有章。"]', '["明君當宁，列辟奉觴。","云容表瑞，日影初长。","衣冠濟濟，鐘磬洋洋。","令儀克盛，嘉會有章。"]', '诗', 'shi', '', NULL, '郊廟歌辭 周朝饗樂章 忠順 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5ec0478-b462-441b-bfa3-59c93c82f376', '郊廟歌辭 周朝饗樂章 治順', '郊廟歌辞 周朝饗乐章 治順', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["庭陳大樂，作當太微。","凝旒負扆，端拱垂衣。","鴛鸞成列，簪組相輝。","御爐香散，郁郁霏霏。"]', '["庭陳大乐，作當太微。","凝旒負扆，端拱垂衣。","鴛鸾成列，簪組相輝。","御爐香散，郁郁霏霏。"]', '诗', 'shi', '', NULL, '郊廟歌辭 周朝饗樂章 治順 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64afb35e-d5b9-4f5b-af6b-1b47a72d1e9e', '郊廟歌辭 周朝饗樂章 福順', '郊廟歌辞 周朝饗乐章 福順', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["聖皇端拱，多士輸忠。","蠻觴共獻，臣心畢同。","聲齊嵩嶽，祝比華封。","千齡萬祀，常保時雍。"]', '["聖皇端拱，多士輸忠。","蠻觴共獻，臣心畢同。","声齊嵩嶽，祝比华封。","千齡万祀，常保时雍。"]', '诗', 'shi', '', NULL, '郊廟歌辭 周朝饗樂章 福順 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2df45b12-b0e8-46d3-b366-8a0f26cbfbec', '郊廟歌辭 周朝饗樂章 康順', '郊廟歌辞 周朝饗乐章 康順', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["鴻鈞廣運，嘉節良辰。","列辟在位，萬國來賓。","干旌屢舞，金石咸陳。","禮容既備，帝履長春。"]', '["鴻鈞廣運，嘉節良辰。","列辟在位，万国来賓。","干旌屢舞，金石咸陳。","禮容既備，帝履长春。"]', '诗', 'shi', '', NULL, '郊廟歌辭 周朝饗樂章 康順 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f73247fb-5b23-431e-8e31-e388cd6b44ba', '郊廟歌辭 周朝饗樂章 忠順', '郊廟歌辞 周朝饗乐章 忠順', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["禮成三爵，樂畢九成。","共離金戺，復列彤庭。"]', '["禮成三爵，乐畢九成。","共離金戺，复列彤庭。"]', '诗', 'shi', '', NULL, '郊廟歌辭 周朝饗樂章 忠順 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23abe3f3-6a5a-404a-8875-5844c102efc4', '郊廟歌辭 周朝饗樂章 忠順', '郊廟歌辞 周朝饗乐章 忠順', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["明庭展禮，爲龍爲光。","咸韶息韻，鵷鷺歸行。"]', '["明庭展禮，爲龙爲光。","咸韶息韻，鵷鷺归行。"]', '诗', 'shi', '', NULL, '郊廟歌辭 周朝饗樂章 忠順 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff874166-6794-41a3-945b-4f9c949adbdb', '郊廟歌辭 晉昭德成功舞歌 昭德舞歌二首 一', '郊廟歌辞 晉昭德成功舞歌 昭德舞歌二首 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["聖代修文德，明庭舉舊章。","兩階陳羽籥，萬舞合宮商。","劒佩森鴛鷺，簫韶下鳳凰。","我朝青史上，千古有輝光。"]', '["聖代修文德，明庭舉旧章。","兩階陳羽籥，万舞合宮商。","劒佩森鴛鷺，簫韶下鳳凰。","我朝青史上，千古有輝光。"]', '诗', 'shi', '', NULL, '郊廟歌辭 晉昭德成功舞歌 昭德舞歌二首 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3806494e-a073-476c-b9e0-bac7f834a4dc', '郊廟歌辭 晉昭德成功舞歌 昭德舞歌二首 二', '郊廟歌辞 晉昭德成功舞歌 昭德舞歌二首 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["淮海干戈戢，朝廷禮樂施。","白駒皆就縶，丹鳳復來儀。","德備三苗格，風行萬國隨。","小臣同百獸，率舞賀昌期。"]', '["淮海干戈戢，朝廷禮乐施。","白駒皆就縶，丹鳳复来儀。","德備三苗格，风行万国隨。","小臣同百獸，率舞賀昌期。"]', '诗', 'shi', '', NULL, '郊廟歌辭 晉昭德成功舞歌 昭德舞歌二首 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f72402fd-ddb2-4782-a5d7-1402c8cf495c', '郊廟歌辭 晉昭德成功舞歌 武功舞歌二首 一', '郊廟歌辞 晉昭德成功舞歌 武功舞歌二首 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["撥亂資英主，開基自晉陽。","一戎成大業，七德煥前王。","炎漢提封遠，姬周世祚長。","朱干將玉戚，全象武功揚。"]', '["撥亂資英主，开基自晉陽。","一戎成大業，七德煥前王。","炎漢提封远，姬周世祚长。","朱干將玉戚，全象武功揚。"]', '诗', 'shi', '', NULL, '郊廟歌辭 晉昭德成功舞歌 武功舞歌二首 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6014337-3716-40f7-80fd-ce7b8b8a7c76', '郊廟歌辭 晉昭德成功舞歌 武功舞歌二首 二', '郊廟歌辞 晉昭德成功舞歌 武功舞歌二首 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["睿算超前古，神功格上圓。","百川留禹跡，萬國戴堯天。","既已櫜弓矢，誠宜播管弦。","蹌蹌隨鳥獸，共樂太平年。"]', '["睿算超前古，神功格上圓。","百川留禹跡，万国戴堯天。","既已櫜弓矢，誠宜播管弦。","蹌蹌隨鸟獸，共乐太平年。"]', '诗', 'shi', '', NULL, '郊廟歌辭 晉昭德成功舞歌 武功舞歌二首 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39c8eb21-2fd1-42bb-9540-3ff56ea983c3', '鼓吹曲辭 朱鷺', '鼓吹曲辞 朱鷺', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["翩翩兮朱鷺，來汎春塘棲綠樹。","羽毛如翦色如染，遠飛欲下雙翅斂。","避人引子入深壍，動處水紋開灩灩。","誰知豪家網爾軀，不如飲啄江海隅。"]', '["翩翩兮朱鷺，来汎春塘棲綠樹。","羽毛如翦色如染，远飞欲下雙翅斂。","避人引子入深壍，动处水紋开灩灩。","誰知豪家網爾軀，不如饮啄江海隅。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 朱鷺 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d259d7b-98df-4576-b439-3cc6671bfc0b', '鼓吹曲辭 艾如張', '鼓吹曲辞 艾如張', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["錦襜褕，繡襠襦，強強飲啄哺爾雛。","隴東臥穟滿風雨，莫信龍媒隴西去。","齊人織網如素空，張在野春平碧中。","網絲漠漠無形影，誤爾觸之傷首紅。","艾葉綠花誰翦刻，中藏禍機不可測。"]', '["錦襜褕，繡襠襦，強強饮啄哺爾雛。","隴东臥穟满风雨，莫信龙媒隴西去。","齊人织網如素空，張在野春平碧中。","網絲漠漠無形影，誤爾觸之傷首紅。","艾葉綠花誰翦刻，中藏禍機不可測。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 艾如張 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb6b3bf9-3154-4539-99f6-12b288444219', '鼓吹曲辭 上之回', '鼓吹曲辞 上之回', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["回中道路險，蕭關烽候多。","五營屯北地，萬乘出西河。","單于拜玉璽，天子按琱戈。","振旅汾川曲，秋風橫大歌。"]', '["回中道路險，蕭关烽候多。","五營屯北地，万乘出西河。","單于拜玉璽，天子按琱戈。","振旅汾川曲，秋风橫大歌。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 上之回 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee3195f6-eb17-4e87-b714-f7cf07ff03f2', '鼓吹曲辭 上之回', '鼓吹曲辞 上之回', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["三十六離宮，樓臺與天通。","閣道步行月，美人愁煙空。","恩疎寵不及，桃李傷春風。","淫樂意何極，金輿向回中。","萬乘出黃道，千旗揚彩虹。","前軍細柳北，後騎甘泉東。","豈問渭川老，寧邀襄野童。","秋暮瑤池宴，歸來樂未窮。"]', '["三十六離宮，楼台與天通。","閣道步行月，美人愁煙空。","恩疎寵不及，桃李傷春风。","淫乐意何極，金輿向回中。","万乘出黄道，千旗揚彩虹。","前軍細柳北，後騎甘泉东。","豈问渭川老，寧邀襄野童。","秋暮瑤池宴，归来乐未窮。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 上之回 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ca0cc8a-db1e-4e60-943a-7cf72e679248', '鼓吹曲辭 上之回', '鼓吹曲辞 上之回', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["上之回，大旗喜。","懸虹彗，撻鳳尾。","劒匣破，舞蛟龍。","蚩尤死，鼓逢逢。","天高慶雷齊墜地，地無驚煙海千里。"]', '["上之回，大旗喜。","懸虹彗，撻鳳尾。","劒匣破，舞蛟龙。","蚩尤死，鼓逢逢。","天高慶雷齊墜地，地無驚煙海千里。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 上之回 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('154bc6b6-be47-4e42-a039-e6f6d22fd447', '鼓吹曲辭 戰城南', '鼓吹曲辞 戰城南', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["將軍出紫塞，冒頓在烏貪。","笳喧雁門北，陣翼龍城南。","琱弓夜宛轉，鐵騎曉參潭。","應須駐白日，爲待戰方酣。"]', '["將軍出紫塞，冒頓在烏貪。","笳喧雁门北，陣翼龙城南。","琱弓夜宛轉，鐵騎晓參潭。","應須駐白日，爲待戰方酣。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 戰城南 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0f1c8ed-bbf8-4ace-ac86-91e5e57d8ece', '鼓吹曲辭 戰城南', '鼓吹曲辞 戰城南', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["去年戰桑乾源，今年戰蔥河道。","洗兵條支海上波，放馬天山雪中草。","萬里長征戰，三軍盡衰老。","匈奴以殺戮爲耕作，古來唯見白骨黃沙田。","秦家築城備胡處，漢家還有烽火然。","烽火然不息，征戰無已時。","野戰格鬬死，敗馬號鳴向天悲。","烏鳶啄人腸，銜飛上挂枯樹枝。","士卒塗草莽，將軍空爾爲。","乃知兵者是凶器，聖人不得已而用之。"]', '["去年戰桑乾源，今年戰蔥河道。","洗兵條支海上波，放马天山雪中草。","万里长征戰，三軍尽衰老。","匈奴以殺戮爲耕作，古来唯见白骨黄沙田。","秦家築城備胡处，漢家還有烽火然。","烽火然不息，征戰無已时。","野戰格鬬死，敗马號鳴向天悲。","烏鳶啄人腸，銜飞上挂枯樹枝。","士卒塗草莽，將軍空爾爲。","乃知兵者是凶器，聖人不得已而用之。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 戰城南 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f85f5813-4fa8-4ce8-be2d-a6664da153ee', '鼓吹曲辭 戰城南', '鼓吹曲辞 戰城南', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["城南征戰多，城北無飢鵶。","白骨馬蹄下，誰言皆有家。","城前水聲苦，倏忽流萬古。","莫爭城外地，城裏有閑土。"]', '["城南征戰多，城北無飢鵶。","白骨马蹄下，誰言皆有家。","城前水声苦，倏忽流万古。","莫爭城外地，城裏有闲土。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 戰城南 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e01deae-f2e1-403a-a615-97aaf7e78738', '鼓吹曲辭 戰城南二首 一', '鼓吹曲辞 戰城南二首 一', '2f390450-2daa-424a-9330-8269402ce797', '唐', '["萬里桑乾傍，茫茫古蕃壤。","將軍貌顦顇，撫劒悲年長。","胡兵尚陵逼，久住亦非強。","邯鄲少年輩，箇箇有伎倆。","拖槍半夜去，雪片大如掌。"]', '["万里桑乾傍，茫茫古蕃壤。","將軍貌顦顇，撫劒悲年长。","胡兵尚陵逼，久住亦非強。","邯鄲少年輩，箇箇有伎倆。","拖槍半夜去，雪片大如掌。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 戰城南二首 一 僧貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('241e52e3-22fe-4943-b65e-74117c33b8b7', '鼓吹曲辭 戰城南二首 二', '鼓吹曲辞 戰城南二首 二', '2f390450-2daa-424a-9330-8269402ce797', '唐', '["磧中有陰兵，戰馬時驚蹶。","輕猛李陵心，摧殘蘇武節。","黃金鎖子甲，風吹色如鐵。","十載不封侯，茫茫向誰說。"]', '["磧中有陰兵，戰马时驚蹶。","轻猛李陵心，摧殘蘇武節。","黄金鎖子甲，风吹色如鐵。","十載不封侯，茫茫向誰说。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 戰城南二首 二 僧貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2099379f-db42-4de6-9013-0649e78c5408', '鼓吹曲辭 巫山高', '鼓吹曲辞 巫山高', '490de3dd-2114-40b0-ab8b-bc8b444dfa1d', '唐', '["巫山凌太清，岧嶢類削成。","霏霏暮雨合，靄靄朝雲生。","危峰入鳥道，深谷瀉猿聲。","別有幽棲客，淹留攀桂情。"]', '["巫山凌太清，岧嶢類削成。","霏霏暮雨合，靄靄朝云生。","危峰入鸟道，深谷瀉猿声。","別有幽棲客，淹留攀桂情。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 巫山高 鄭世翼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbecbf52-7793-4e52-92d1-1a84c07b649c', '鼓吹曲辭 巫山高二首 一', '鼓吹曲辞 巫山高二首 一', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["巫山峰十二，環合隱昭回。","俯眺琵琶峽，平看雲雨臺。","古槎天外倚，瀑水日邊來。","何忽啼猨夜，荆王枕席開。"]', '["巫山峰十二，环合隐昭回。","俯眺琵琶峽，平看云雨台。","古槎天外倚，瀑水日邊来。","何忽啼猨夜，荆王枕席开。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 巫山高二首 一 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37063ab6-a303-4864-b68d-9888d19a5124', '鼓吹曲辭 巫山高二首 二', '鼓吹曲辞 巫山高二首 二', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["神女向高唐，巫山下夕陽。","裴回作行雨，婉孌逐荆王。","電影江前落，雷聲峽外長。","霽雲無處所，臺館曉蒼蒼。"]', '["神女向高唐，巫山下夕陽。","裴回作行雨，婉孌逐荆王。","電影江前落，雷声峽外长。","霽云無处所，台館晓蒼蒼。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 巫山高二首 二 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efafe0cd-54fd-40a4-be7b-117a45d18ee1', '鼓吹曲辭 巫山高', '鼓吹曲辞 巫山高', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["巫山望不極，望望下朝雰。","莫辨啼猿樹，徒看神女雲。","驚濤亂水脈，驟雨暗峰文。","霑裳即此地，況復遠思君。"]', '["巫山望不極，望望下朝雰。","莫辨啼猿樹，徒看神女云。","驚濤亂水脈，驟雨暗峰文。","霑裳即此地，況复远思君。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 巫山高 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c3b9194-4120-405d-8ad3-35db9dd01379', '鼓吹曲辭 巫山高', '鼓吹曲辞 巫山高', 'c67d16ad-c102-4959-9edd-e677bb9716af', '唐', '["巫山高不極，沓沓狀奇新。","暗谷疑風雨，幽巖若鬼神。","月明三峽曙，潮滿二江春。","爲問陽臺夕，應知入夢人。"]', '["巫山高不極，沓沓狀奇新。","暗谷疑风雨，幽巖若鬼神。","月明三峽曙，潮满二江春。","爲问陽台夕，應知入梦人。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 巫山高 張循之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0be28b3-b020-4c2b-9d81-2ff24b4ef1f2', '鼓吹曲辭 巫山高', '鼓吹曲辞 巫山高', 'bcc19379-0cd3-45d1-985f-8aa6bf5c5476', '唐', '["楚國巫山秀，清猨日夜啼。","萬重春樹合，十二碧峰齊。","峽出朝雲下，江來暮雨西。","陽臺歸路直，不畏向家迷。"]', '["楚国巫山秀，清猨日夜啼。","万重春樹合，十二碧峰齊。","峽出朝云下，江来暮雨西。","陽台归路直，不畏向家迷。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 巫山高 劉方平 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e607091f-25b1-4d3b-96f0-f5e8fa16bea1', '鼓吹曲辭 巫山高', '鼓吹曲辞 巫山高', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["巫峽見巴東，迢迢半出空。","雲藏神女館，雨到楚王宮。","朝暮泉聲落，寒暄樹色同。","清猨不可聽，偏在九秋中。"]', '["巫峽见巴东，迢迢半出空。","云藏神女館，雨到楚王宮。","朝暮泉声落，寒暄樹色同。","清猨不可听，偏在九秋中。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 巫山高 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5a4b9de-6628-40ce-8e63-6e433f69997d', '鼓吹曲辭 巫山高', '鼓吹曲辞 巫山高', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["巫山十二峰，皆在碧虛中。","回合雲藏日，霏微雨帶風。","猨聲寒過水，樹色暮連空。","愁向高唐望，清秋見楚宮。"]', '["巫山十二峰，皆在碧虛中。","回合云藏日，霏微雨带风。","猨声寒過水，樹色暮連空。","愁向高唐望，清秋见楚宮。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 巫山高 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4dbb46b-ddc5-4e16-9c82-0bdd6bc9a0ab', '鼓吹曲辭 巫山高', '鼓吹曲辞 巫山高', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["何山無朝雲，彼雲亦悠揚。","何山無暮雨，彼雨亦蒼茫。","宋玉恃才者，憑雲構高唐。","自重文賦名，荒淫歸楚襄。","峨峨十二峰，永作妖鬼鄉。"]', '["何山無朝云，彼云亦悠揚。","何山無暮雨，彼雨亦蒼茫。","宋玉恃才者，憑云構高唐。","自重文賦名，荒淫归楚襄。","峨峨十二峰，永作妖鬼乡。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 巫山高 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df99dd63-0832-4715-8e63-ce89452560a1', '鼓吹曲辭 巫山高二首 一', '鼓吹曲辞 巫山高二首 一', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["巴山上峽重復重，陽臺碧峭十二峰。","荆王獵時逢暮雨，夜臥高丘夢神女。","輕紅流煙溼豔姿，行雲飛去明星稀。","目極魂斷望不見，猨啼三聲淚霑衣。"]', '["巴山上峽重复重，陽台碧峭十二峰。","荆王獵时逢暮雨，夜臥高丘梦神女。","轻紅流煙溼豔姿，行云飞去明星稀。","目極魂斷望不见，猨啼三声泪霑衣。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 巫山高二首 一 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26e48437-716e-4d92-85e1-cd258121753f', '鼓吹曲辭 巫山高二首 二', '鼓吹曲辞 巫山高二首 二', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["見盡數萬里，不聞三聲猨。","但飛蕭蕭雨，中有亭亭魂。","千載楚襄恨，遺文宋玉言。","至今青冥裏，雲結深閨門。"]', '["见尽數万里，不闻三声猨。","但飞蕭蕭雨，中有亭亭魂。","千載楚襄恨，遺文宋玉言。","至今青冥裏，云結深閨门。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 巫山高二首 二 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f4eb2fc-17fd-4302-88e6-4bda6fcff473', '鼓吹曲辭 巫山高', '鼓吹曲辞 巫山高', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["碧叢叢，高插天，大江翻瀾神曳煙。","楚魂尋夢風颸然，曉風飛雨生苔錢。","瑤姬一去一千年，丁香笻竹啼老猨。","古祠近月蟾桂寒，椒花墜紅溼雲間。"]', '["碧叢叢，高插天，大江翻瀾神曳煙。","楚魂尋梦风颸然，晓风飞雨生苔錢。","瑤姬一去一千年，丁香笻竹啼老猨。","古祠近月蟾桂寒，椒花墜紅溼云间。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 巫山高 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee1c6140-7f86-4c71-ac6b-26abdbe9aa12', '鼓吹曲辭 巫山高', '鼓吹曲辞 巫山高', '405848e7-8d14-42db-a593-f688fd279870', '唐', '["巫山高，巫女妖。","雨爲暮兮雲爲朝，楚王顦顇魂欲銷。","秋猨嗥嗥日將夕，紅霞紫煙凝老壁。","千巖萬壑花皆坼，但恐芳菲無正色。","不知今古行人行，幾人經此無秋情。","雲深廟遠不可覓，十二峰頭插天碧。"]', '["巫山高，巫女妖。","雨爲暮兮云爲朝，楚王顦顇魂欲銷。","秋猨嗥嗥日將夕，紅霞紫煙凝老壁。","千巖万壑花皆坼，但恐芳菲無正色。","不知今古行人行，幾人經此無秋情。","云深廟远不可覓，十二峰头插天碧。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 巫山高 僧齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f7504df-cda2-4fe2-bc63-867ec2e418e7', '鼓吹曲辭 將進酒', '鼓吹曲辞 將進酒', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["君不見黃河之水天上來，奔流到海不復回。","君不見高堂明鏡悲白髮，朝如青絲暮成雪。","人生得意須盡歡，莫使金尊空對月。","天生我材必有用，千金散盡還復來。","烹羊宰牛且爲樂，會須一飲三百杯。","岑夫子，丹丘生，將進酒，杯莫停。","與君歌一曲，請君爲我側耳聽。","鐘鼓饌玉不足貴，但願長醉不復醒。","古來聖賢皆寂寞，惟有飲者留其名。","陳王昔時宴平樂，斗酒十千恣歡謔。","主人何爲言少錢，徑須酤取對君酌。","五花馬，千金裘，呼兒將出換美酒，與爾同銷萬古愁。"]', '["君不见黄河之水天上来，奔流到海不复回。","君不见高堂明镜悲白髮，朝如青絲暮成雪。","人生得意須尽歡，莫使金尊空对月。","天生我材必有用，千金散尽還复来。","烹羊宰牛且爲乐，會須一饮三百杯。","岑夫子，丹丘生，將進酒，杯莫停。","與君歌一曲，請君爲我側耳听。","鐘鼓饌玉不足貴，但願长醉不复醒。","古来聖賢皆寂寞，惟有饮者留其名。","陳王昔时宴平乐，斗酒十千恣歡謔。","主人何爲言少錢，徑須酤取对君酌。","五花马，千金裘，呼兒將出換美酒，與爾同銷万古愁。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 將進酒 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c1d7719-593f-489d-ae78-3e1e34a66412', '鼓吹曲辭 將進酒', '鼓吹曲辞 將進酒', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["將進酒，將進酒。","酒中有毒酖主父，言之主父傷主母。","母爲妾地父妾天，仰天俯地不忍言。","佯爲僵踣主父前，主父不知加妾鞭。","旁人知妾爲主說，主將淚洗鞭頭血。","推摧主母牽下堂，扶妾遣升堂上牀。","將進酒，酒中無毒令主壽。","願主回思歸主母，遣妾如此事主父。","妾爲此事人偶知，自慙不密方自悲。","主今顛倒安置妾，貪天僭地誰不爲。"]', '["將進酒，將進酒。","酒中有毒酖主父，言之主父傷主母。","母爲妾地父妾天，仰天俯地不忍言。","佯爲僵踣主父前，主父不知加妾鞭。","旁人知妾爲主说，主將泪洗鞭头血。","推摧主母牽下堂，扶妾遣升堂上牀。","將進酒，酒中無毒令主壽。","願主回思归主母，遣妾如此事主父。","妾爲此事人偶知，自慙不密方自悲。","主今顛倒安置妾，貪天僭地誰不爲。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 將進酒 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d22a2f9-a696-435c-8d2e-7c7e1b3c1af9', '鼓吹曲辭 將進酒', '鼓吹曲辞 將進酒', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["瑠璃鍾，琥珀濃，小槽酒滴真珠紅。","烹龍炮鳳玉脂泣，羅屏繡幕圍香風。","吹龍笛，擊鼉鼓，皓齒歌，細腰舞。","況是青春日將暮，桃花亂落如紅雨。","勸君終日酩酊醉，酒不到劉伶墳上土。"]', '["瑠璃鍾，琥珀濃，小槽酒滴真珠紅。","烹龙炮鳳玉脂泣，羅屏繡幕圍香风。","吹龙笛，擊鼉鼓，皓齒歌，細腰舞。","況是青春日將暮，桃花亂落如紅雨。","勸君終日酩酊醉，酒不到劉伶墳上土。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 將進酒 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4c03bc1-0596-4177-88ba-e42a97b0a7d9', '鼓吹曲辭 君馬黃', '鼓吹曲辞 君马黄', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["君馬黃，我馬白。","馬色雖不同，人心本無隔。","共作遊冶盤，雙行洛陽陌。","長劒既照曜，高冠何赩赫。","各有千金裘，俱爲五侯客。","猛虎落陷穽，壯夫時屈厄。","相知在急難，獨好亦何益。"]', '["君马黄，我马白。","马色雖不同，人心本無隔。","共作游冶盤，雙行洛陽陌。","长劒既照曜，高冠何赩赫。","各有千金裘，俱爲五侯客。","猛虎落陷穽，壯夫时屈厄。","相知在急难，独好亦何益。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 君馬黃 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('315098e7-6da6-4435-9fed-f3ed5b80875d', '鼓吹曲辭 芳樹', '鼓吹曲辞 芳樹', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["何地早芳菲？宛在長門殿。","夭桃色若綬，穠李光如練。","啼鳥弄花疎，遊蠭飲香徧。","歎息春風起，飄零君不見。"]', '["何地早芳菲？宛在长门殿。","夭桃色若綬，穠李光如練。","啼鸟弄花疎，游蠭饮香徧。","歎息春风起，飄零君不见。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 芳樹 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('768bbe02-89b7-4ba7-b107-56da218e4c67', '鼓吹曲辭 芳樹', '鼓吹曲辞 芳樹', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["芳樹本多奇，年華復在斯。","結翠成新幄，開紅滿舊枝。","風歸花歷亂，日度影參差。","容色朝朝落，思君君不知。"]', '["芳樹本多奇，年华复在斯。","結翠成新幄，开紅满旧枝。","风归花歷亂，日度影參差。","容色朝朝落，思君君不知。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 芳樹 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39b2b613-94a2-492b-aaaa-cee6c34a6c41', '鼓吹曲辭 芳樹', '鼓吹曲辞 芳樹', 'feb1b440-a02e-4e74-8f62-faadc8d7e153', '唐', '["玉花珍簟上，金縷畫屏開。","曉月憐箏柱，春風憶鏡臺。","箏柱春風吹曉月，芳樹落花朝暝歇。","藳砧刀頭未有時，攀條拭淚坐相思。"]', '["玉花珍簟上，金縷畫屏开。","晓月怜箏柱，春风憶镜台。","箏柱春风吹晓月，芳樹落花朝暝歇。","藳砧刀头未有时，攀條拭泪坐相思。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 芳樹 徐彥伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4501ca9-2069-4e6b-90c7-908f094f4fd1', '鼓吹曲辭 芳樹', '鼓吹曲辞 芳樹', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["迢迢芳園樹，列映清池曲。","對此傷人心，還如故時綠。","風條灑餘靄，露葉承新旭。","佳人不再攀，下有往來躅。"]', '["迢迢芳园樹，列映清池曲。","对此傷人心，還如故时綠。","风條灑餘靄，露葉承新旭。","佳人不再攀，下有往来躅。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 芳樹 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5eb2f6f-4806-41cf-ac0f-9764b3911007', '鼓吹曲辭 芳樹', '鼓吹曲辞 芳樹', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["芳樹已寥落，孤英尤可嘉。","可憐團團葉，蓋覆深深花。","遊蠭競攢刺，鬬雀亦紛拏。","天生細碎物，不愛好光華。","非無殲殄法，念爾有生涯。","春雷一聲發，驚燕亦驚蛇。","清池養神蔡，已復長蝦蟆。","雨露貴平施，吾其春草芽。"]', '["芳樹已寥落，孤英尤可嘉。","可怜團團葉，蓋覆深深花。","游蠭競攢刺，鬬雀亦紛拏。","天生細碎物，不愛好光华。","非無殲殄法，念爾有生涯。","春雷一声發，驚燕亦驚蛇。","清池養神蔡，已复长蝦蟆。","雨露貴平施，吾其春草芽。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 芳樹 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ba9e234-c171-4129-ab2e-b52db1026621', '鼓吹曲辭 芳樹', '鼓吹曲辞 芳樹', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["細蘂慢逐風，暖香閑破鼻。","青帝固有心，時時動人意。","去年高枝猶壓地，今年低枝已顦顇。","吾所以見造化之權，變通之理。","春夏作頭，秋冬爲尾。","循環反覆無窮已，今生長短同一軌。","若使威可以制，力可以止，秦皇不肯斂手下沙丘，孟賁不合低頭入蒿里。","伊人彊猛猶如此，顧我勞生何足恃？","但願開素袍，傾綠蟻，陶陶兀兀大醉於青冥白晝間。","任他上是天，下是地。"]', '["細蘂慢逐风，暖香闲破鼻。","青帝固有心，时时动人意。","去年高枝猶壓地，今年低枝已顦顇。","吾所以见造化之權，变通之理。","春夏作头，秋冬爲尾。","循环反覆無窮已，今生长短同一軌。","若使威可以制，力可以止，秦皇不肯斂手下沙丘，孟賁不合低头入蒿里。","伊人彊猛猶如此，顧我勞生何足恃？","但願开素袍，傾綠蟻，陶陶兀兀大醉於青冥白晝间。","任他上是天，下是地。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 芳樹 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f61de6f0-8b47-4b5f-8344-b95849bd556d', '鼓吹曲辭 有所思', '鼓吹曲辞 有所思', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["君子事行役，再空芳歲期。","美人曠延佇，萬里浮雲思。","園槿綻紅豔，郊桑柔綠滋。","坐看長夏晚，秋月生羅幃。"]', '["君子事行役，再空芳歲期。","美人曠延佇，万里浮云思。","园槿綻紅豔，郊桑柔綠滋。","坐看长夏晚，秋月生羅幃。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 有所思 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f876a76-9628-4cc3-91da-124444b562f1', '鼓吹曲辭 有所思', '鼓吹曲辞 有所思', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["我思仙人，乃在碧海之東隅。","海寒多天風，白波連山倒蓬壺。","長鯨噴湧不可涉，撫心茫茫淚如珠。","西來青鳥東飛去，願寄一書謝麻姑。"]', '["我思仙人，乃在碧海之东隅。","海寒多天风，白波連山倒蓬壺。","长鯨噴湧不可涉，撫心茫茫泪如珠。","西来青鸟东飞去，願寄一书謝麻姑。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 有所思 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e71eb5f9-d4a1-44dd-b2ad-bffe671f51dd', '鼓吹曲辭 有所思', '鼓吹曲辞 有所思', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["桔槔烽火晝不滅，客路迢迢信難越。","古鎮刀攢萬片霜，寒江浪起千堆雪。","此時西去定如何，空使南心遠淒切。"]', '["桔槔烽火晝不滅，客路迢迢信难越。","古鎮刀攢万片霜，寒江浪起千堆雪。","此时西去定如何，空使南心远淒切。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 有所思 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9629e5e-c8bc-47e6-ae9f-2eba96a7fbda', '鼓吹曲辭 有所思', '鼓吹曲辞 有所思', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["當時我醉美人家，美人顏色嬌如花。","今日美人棄我去，青樓珠箔天之涯。","天涯娟娟常娥月，三五二八盈又缺。","翠眉蟬鬢生別離，一望不見心斷絕。","心斷絕，幾千里，夢中醉臥巫山雲。","覺來淚滴湘江水，湘江兩岸花木深。","美人不見愁人心，含愁更奏綠綺琴，調高弦絕無知音。","美人兮美人！不知爲暮雨兮爲朝雲。","相思一夜梅花發，忽到窗前疑是君。"]', '["當时我醉美人家，美人顏色嬌如花。","今日美人棄我去，青楼珠箔天之涯。","天涯娟娟常娥月，三五二八盈又缺。","翠眉蟬鬢生別離，一望不见心斷絕。","心斷絕，幾千里，梦中醉臥巫山云。","覺来泪滴湘江水，湘江兩岸花木深。","美人不见愁人心，含愁更奏綠綺琴，調高弦絕無知音。","美人兮美人！不知爲暮雨兮爲朝云。","相思一夜梅花發，忽到窗前疑是君。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 有所思 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95f31821-6665-4832-9780-ee1348df07cb', '鼓吹曲辭 有所思', '鼓吹曲辞 有所思', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["借問江上柳，青青爲誰春。","空遊昨日地，不見昨日人。","繚繞萬家井，往來車馬塵。","莫道無相識，要非心所親。"]', '["借问江上柳，青青爲誰春。","空游昨日地，不见昨日人。","繚繞万家井，往来车马塵。","莫道無相識，要非心所親。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 有所思 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea6c5a06-ed63-49f3-82aa-bb7bbded3ee5', '鼓吹曲辭 有所思', '鼓吹曲辞 有所思', '8d78cd6a-1fed-40cc-afc1-7b90a8fa05ea', '唐', '["朝亦有所思，暮亦有所思。","登樓望君處，藹藹浮雲飛。","浮雲遮卻陽關道，向晚誰知妾懷抱。","玉井蒼苔春院深，桐花落地無人掃。"]', '["朝亦有所思，暮亦有所思。","登楼望君处，藹藹浮云飞。","浮云遮卻陽关道，向晚誰知妾懷抱。","玉井蒼苔春院深，桐花落地無人掃。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 有所思 劉氏雲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bfac3e5-6cc6-49c6-892e-e290aa5c5923', '鼓吹曲辭 雉子班', '鼓吹曲辞 雉子班', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["辟邪伎作鼓吹驚，雉子班之奏曲成。","喔咿振迅欲飛鳴，扇錦翼，雄風生。","雙雌同飲啄，趫悍誰能爭。","乍向草中耿介死，不求黃金籠下生。","天地至廣大，何惜遂物情。","善卷讓天子，務光亦逃名。","所貴曠士懷，朗然合太清。"]', '["辟邪伎作鼓吹驚，雉子班之奏曲成。","喔咿振迅欲飞鳴，扇錦翼，雄风生。","雙雌同饮啄，趫悍誰能爭。","乍向草中耿介死，不求黄金籠下生。","天地至廣大，何惜遂物情。","善卷讓天子，務光亦逃名。","所貴曠士懷，朗然合太清。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 雉子班 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0cdc4dd-068d-4edd-a358-ecf71b0a17e3', '鼓吹曲辭 臨高臺', '鼓吹曲辞 臨高台', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["高臺暫俯臨，飛翼聳輕音。","浮光隨日度，漾影逐波深。","迥瞰周平野，開懷暢遠襟。","獨此三休上，還傷千歲心。"]', '["高台暫俯臨，飞翼聳轻音。","浮光隨日度，漾影逐波深。","迥瞰周平野，开懷暢远襟。","独此三休上，還傷千歲心。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 臨高臺 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cd853ef-8a04-4d1c-9c94-bffe4f97a00c', '鼓吹曲辭 臨高臺', '鼓吹曲辞 臨高台', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["臨高臺，高臺迢遞絕浮埃。","瑤軒綺構何崔嵬，鸞歌鳳吹清且哀。","俯瞰長安道，萋萋御溝草。","斜對甘泉路，蒼蒼茂陵樹。","高臺四望同，帝鄉佳氣鬱蔥蔥。","紫閣丹樓紛照曜，璧房錦殿相玲瓏。","東彌長樂觀，西指未央宮。","赤城映朝日，綠樹搖春風。","旗亭百隊開新市，甲第千甍分戚里。","朱輪翠蓋不勝春，疊樹層楹相對起。","復有青樓大道中，繡戶文窗雕綺櫳。","錦衣晝不襞，羅幃夕未空。","歌屏朝揜翠，妝鏡晚窺紅。","爲吾安寶髻，蛾眉罷花叢。","狹路塵間黯將暮，雲間月色明如素。","鴛鴦池上兩兩飛，鳳皇樓下雙雙度。","物色正如此，佳期那不顧。","銀鞍繡轂盛繁華，可憐今夜宿倡家。","倡家少婦不須嚬，東園桃李片時春。","君看舊日高臺處，柏梁銅雀生黃塵。"]', '["臨高台，高台迢遞絕浮埃。","瑤軒綺構何崔嵬，鸾歌鳳吹清且哀。","俯瞰长安道，萋萋御溝草。","斜对甘泉路，蒼蒼茂陵樹。","高台四望同，帝乡佳氣鬱蔥蔥。","紫閣丹楼紛照曜，璧房錦殿相玲瓏。","东彌长乐观，西指未央宮。","赤城映朝日，綠樹搖春风。","旗亭百隊开新市，甲第千甍分戚里。","朱輪翠蓋不勝春，叠樹層楹相对起。","复有青楼大道中，繡戶文窗雕綺櫳。","錦衣晝不襞，羅幃夕未空。","歌屏朝揜翠，妝镜晚窺紅。","爲吾安寶髻，蛾眉罷花叢。","狹路塵间黯將暮，云间月色明如素。","鴛鴦池上兩兩飞，鳳皇楼下雙雙度。","物色正如此，佳期那不顧。","銀鞍繡轂盛繁华，可怜今夜宿倡家。","倡家少婦不須嚬，东园桃李片时春。","君看旧日高台处，柏梁銅雀生黄塵。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 臨高臺 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d3a1f16-ac20-4258-b134-a57b42713d8e', '鼓吹曲辭 臨高臺', '鼓吹曲辞 臨高台', '2f390450-2daa-424a-9330-8269402ce797', '唐', '["涼風吹遠念，使我升高臺。","寧知數片雲，不是舊山來。","故人天一涯，久客殊未回。","雁來不得書，空寄聲哀哀。"]', '["涼风吹远念，使我升高台。","寧知數片云，不是旧山来。","故人天一涯，久客殊未回。","雁来不得书，空寄声哀哀。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 臨高臺 僧貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de4ba9d3-ed18-45cd-baec-58e8e002f9f7', '鼓吹曲辭 黃雀行', '鼓吹曲辞 黄雀行', '998a453e-7ad8-44a7-ac68-91abf4146a26', '唐', '["穿屋穿牆不知止，爭樹爭巢入營死。","林間公子挾彈弓，一丸致斃花叢裏。","小雛黃口未有知，青天不解高高飛。","虞人設網當要路，白日啾嘲禍萬機。"]', '["穿屋穿牆不知止，爭樹爭巢入營死。","林间公子挾彈弓，一丸致斃花叢裏。","小雛黄口未有知，青天不解高高飞。","虞人設網當要路，白日啾嘲禍万機。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 黃雀行 莊南傑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8446acb8-23da-451a-958b-120cdfc8b52d', '鼓吹曲辭 釣竿篇', '鼓吹曲辞 釣竿篇', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["朝日斂紅煙，垂竿向綠川。","人疑天上坐，魚似鏡中懸。","避檝時驚透，猜鉤每誤牽。","湍危不理轄，潭靜欲留船。","釣玉君徒尚，徵金我未賢。","爲看芳餌下，貪得會無全。"]', '["朝日斂紅煙，垂竿向綠川。","人疑天上坐，鱼似镜中懸。","避檝时驚透，猜鉤每誤牽。","湍危不理轄，潭静欲留船。","釣玉君徒尚，徵金我未賢。","爲看芳餌下，貪得會無全。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 釣竿篇 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1795ede6-16e1-4ef7-8d14-9ce9a4c917a5', '鼓吹曲辭 凱歌六首 一', '鼓吹曲辞 凱歌六首 一', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["漢將承恩西破戎，捷書先奏未央宮。","天子預開麟閣待，祗今誰數貳師功。"]', '["漢將承恩西破戎，捷书先奏未央宮。","天子預开麟閣待，祗今誰數貳師功。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 凱歌六首 一 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('436ddce1-56b4-4d4b-a0e0-2101cf9cebb3', '鼓吹曲辭 凱歌六首 二', '鼓吹曲辞 凱歌六首 二', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["官軍西出過樓蘭，營幕傍臨月窟寒。","蒲海曉霜凝劒尾，蔥山夜雪撲旌竿。"]', '["官軍西出過楼蘭，營幕傍臨月窟寒。","蒲海晓霜凝劒尾，蔥山夜雪撲旌竿。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 凱歌六首 二 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd06ba1d-9d8e-4b20-884b-bcf4c93507a6', '鼓吹曲辭 凱歌六首 三', '鼓吹曲辞 凱歌六首 三', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["鳴笳擂鼓擁回軍，破國平蕃昔未聞。","大夫鵲印搖邊月，天將龍旗掣海雲。"]', '["鳴笳擂鼓擁回軍，破国平蕃昔未闻。","大夫鵲印搖邊月，天將龙旗掣海云。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 凱歌六首 三 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38a20ab5-1090-4c1c-8d7c-6faaf729bf1a', '鼓吹曲辭 凱歌六首 四', '鼓吹曲辞 凱歌六首 四', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["月落轅門鼓角鳴，千羣面縛出蕃城。","洗兵魚海雲迎陣，秣馬龍堆月照營。"]', '["月落轅门鼓角鳴，千羣面縛出蕃城。","洗兵鱼海云迎陣，秣马龙堆月照營。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 凱歌六首 四 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('598114d3-1644-44f3-b235-14bd3ad2de87', '鼓吹曲辭 凱歌六首 五', '鼓吹曲辞 凱歌六首 五', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["蕃軍遙見漢家營，滿谷連山徧哭聲。","萬箭千刀一夜殺，平明流血浸空城。"]', '["蕃軍遙见漢家營，满谷連山徧哭声。","万箭千刀一夜殺，平明流血浸空城。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 凱歌六首 五 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddf67260-7dcb-405a-824e-f11c3c9fea2f', '鼓吹曲辭 凱歌六首 六', '鼓吹曲辞 凱歌六首 六', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["暮雨旌旗溼未乾，胡塵白草日光寒。","昨日將軍連曉戰，蕃軍只見馬空鞍。"]', '["暮雨旌旗溼未乾，胡塵白草日光寒。","昨日將軍連晓戰，蕃軍只见马空鞍。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 凱歌六首 六 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df56529b-2c90-46a3-baf8-223faff1c1af', '鼓吹曲辭 鼓吹鐃歌 晉陽武', '鼓吹曲辞 鼓吹鐃歌 晉陽武', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["晉陽武，奮義威。","煬之渝，德焉歸。","氓畢屠，綏者誰。","皇烈烈，專天機。","號以仁，揚其旗。","日之升，九土晞。","斥田圻，流洪輝。","有其二，翼餘隋。","斮梟驁，連熊螭。","枯以肉，勍者羸。","后土蕩，玄穹彌。","合之育，莽然施。","惟德輔，慶無期。"]', '["晉陽武，奮義威。","煬之渝，德焉归。","氓畢屠，綏者誰。","皇烈烈，專天機。","號以仁，揚其旗。","日之升，九土晞。","斥田圻，流洪輝。","有其二，翼餘隋。","斮梟驁，連熊螭。","枯以肉，勍者羸。","后土蕩，玄穹彌。","合之育，莽然施。","惟德輔，慶無期。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 鼓吹鐃歌 晉陽武 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8626b26-a3c0-41d5-ae27-963cbb263b3c', '鼓吹曲辭 鼓吹鐃歌 獸之窮', '鼓吹曲辞 鼓吹鐃歌 獸之窮', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["獸之窮，奔大麓。","天厚黃德，狙獷服。","甲之櫜弓，弭矢箙。","皇旅靖，敵逾蹙。","自亡其徒，匪予戮。","屈𧹁猛，虔慄慄。","縻以尺組，噉以秩。","黎之陽，土茫茫。","富兵戎，盈倉箱。","乏者德，莫能享。","驅豺兕，授我疆。"]', '["獸之窮，奔大麓。","天厚黄德，狙獷服。","甲之櫜弓，弭矢箙。","皇旅靖，敵逾蹙。","自亡其徒，匪予戮。","屈𧹁猛，虔慄慄。","縻以尺組，噉以秩。","黎之陽，土茫茫。","富兵戎，盈倉箱。","乏者德，莫能享。","驱豺兕，授我疆。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 鼓吹鐃歌 獸之窮 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03a00289-c6dd-427b-98d4-1432aaabcbd2', '鼓吹曲辭 鼓吹鐃歌 戰武牢', '鼓吹曲辞 鼓吹鐃歌 戰武牢', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["戰武牢，動河朔。","逆之助，圖掎角。","怒鷇麛，抗喬嶽。","翹萌牙，傲霜雹。","王謀內定，申掌握。","鋪施芟夷，二主縛。","憚華戎，廓封略。","命之瞢，卑以斮。","歸有德，唯先覺。"]', '["戰武牢，动河朔。","逆之助，圖掎角。","怒鷇麛，抗喬嶽。","翹萌牙，傲霜雹。","王謀內定，申掌握。","鋪施芟夷，二主縛。","憚华戎，廓封略。","命之瞢，卑以斮。","归有德，唯先覺。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 鼓吹鐃歌 戰武牢 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('578adc6f-5d30-4eb7-875c-748536fdd0cd', '鼓吹曲辭 鼓吹鐃歌 涇水黃', '鼓吹曲辞 鼓吹鐃歌 涇水黄', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["涇水黃，隴野茫。","負太白，騰天狼。","有鳥鷙立，羽翼張。","鉤喙決前，鉅趯傍。","怒飛飢嘯，翾不可當。","老雄死，子復良。","巢岐飲渭，肆翱翔。","頓地紘，提天綱。","列缺掉幟，招搖耀鋩。","鬼神來助，夢嘉祥。","腦塗原野，魂飛揚。","星辰復，恢一方。"]', '["涇水黄，隴野茫。","負太白，腾天狼。","有鸟鷙立，羽翼張。","鉤喙決前，鉅趯傍。","怒飞飢嘯，翾不可當。","老雄死，子复良。","巢岐饮渭，肆翱翔。","頓地紘，提天綱。","列缺掉幟，招搖耀鋩。","鬼神来助，梦嘉祥。","腦塗原野，魂飞揚。","星辰复，恢一方。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 鼓吹鐃歌 涇水黃 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc07032c-9261-4b47-9bf4-b35ed3be83a2', '鼓吹曲辭 鼓吹鐃歌 奔鯨沛', '鼓吹曲辞 鼓吹鐃歌 奔鯨沛', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["奔鯨沛，盪海垠。","吐霓翳日，腥浮雲。","帝怒下顧，哀墊昏。","[授]以神柄，推元臣。","手援天矛，截修鱗。","披攘蒙霿，開海門。","地平水靜，浮天垠。","羲和顯耀，乘清氛。","赫炎溥暢，融大鈞。"]', '["奔鯨沛，盪海垠。","吐霓翳日，腥浮云。","帝怒下顧，哀墊昏。","[授]以神柄，推元臣。","手援天矛，截修鱗。","披攘蒙霿，开海门。","地平水静，浮天垠。","羲和显耀，乘清氛。","赫炎溥暢，融大鈞。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 鼓吹鐃歌 奔鯨沛 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cccc58b6-dfdb-425f-804a-3bf29a755a83', '鼓吹曲辭 鼓吹鐃歌 苞枿', '鼓吹曲辞 鼓吹鐃歌 苞枿', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["苞枿𪒶矣，惟根之蟠。","彌巴蔽荆，負南極以安。","曰我舊梁氏，輯綏艱難。","江漢之阻，都邑固以完。","聖人作，神武用。","有臣勇智，奮不以衆。","投跡死地，謀猷縱。","化敵爲家，慮則中。","浩浩海裔，不威而同。","係縲降王，定厥功。","澶漫萬里，宣唐風。","蠻夷九譯，咸來從。","凱旋金奏，象形容。","震赫萬國，罔不龔。"]', '["苞枿𪒶矣，惟根之蟠。","彌巴蔽荆，負南極以安。","曰我旧梁氏，輯綏艱难。","江漢之阻，都邑固以完。","聖人作，神武用。","有臣勇智，奮不以衆。","投跡死地，謀猷縱。","化敵爲家，慮則中。","浩浩海裔，不威而同。","係縲降王，定厥功。","澶漫万里，宣唐风。","蠻夷九譯，咸来從。","凱旋金奏，象形容。","震赫万国，罔不龔。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 鼓吹鐃歌 苞枿 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1264668-8b25-4c5a-9260-904b20979589', '鼓吹曲辭 鼓吹鐃歌 河右平', '鼓吹曲辞 鼓吹鐃歌 河右平', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["河右澶漫，頑爲之魁。","王師如雷震，崑崙以頹。","上聾下聰，驁不可迴。","助讎抗有德，惟人之災。","乃潰乃奮，執縛歸厥命。","萬室蒙其仁，一夫則病。","濡以鴻澤，皇之聖。","威畏德懷，功以定。","順之于理，物咸遂厥性。"]', '["河右澶漫，頑爲之魁。","王師如雷震，崑崙以頹。","上聾下聰，驁不可迴。","助讎抗有德，惟人之災。","乃潰乃奮，執縛归厥命。","万室蒙其仁，一夫則病。","濡以鴻澤，皇之聖。","威畏德懷，功以定。","順之于理，物咸遂厥性。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 鼓吹鐃歌 河右平 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21173c18-b7d0-4c57-a29b-3cde7a7a0af4', '鼓吹曲辭 鼓吹鐃歌 鐵山碎', '鼓吹曲辞 鼓吹鐃歌 鐵山碎', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["鐵山碎，大漠舒。","二虜勁，連穹廬。","背北海，專坤隅。","歲來侵邊，或傅于都。","天子命元帥，奮其雄圖。","破定襄，降魁渠。","窮竟窟宅，斥余吾。","百蠻破膽，邊氓蘇。","威武輝耀，明鬼區。","利澤彌萬祀，功不可踰。","官臣拜手，惟帝之謨。"]', '["鐵山碎，大漠舒。","二虜勁，連穹廬。","背北海，專坤隅。","歲来侵邊，或傅于都。","天子命元帥，奮其雄圖。","破定襄，降魁渠。","窮竟窟宅，斥余吾。","百蠻破膽，邊氓蘇。","威武輝耀，明鬼區。","利澤彌万祀，功不可踰。","官臣拜手，惟帝之謨。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 鼓吹鐃歌 鐵山碎 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b0a825b-9e1e-4f34-b831-49ce8fd7f97c', '鼓吹曲辭 鼓吹鐃歌 靖本邦', '鼓吹曲辞 鼓吹鐃歌 靖本邦', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["本邦伊晉，惟時不靖。","根柢之搖，枝葉攸病。","守臣不任，勩於神聖。","惟鉞之興，翦焉則定。","洪惟我理，式和以敬。","羣頑既夷，庶績咸正。","皇謨載大，惟人之慶。"]', '["本邦伊晉，惟时不靖。","根柢之搖，枝葉攸病。","守臣不任，勩於神聖。","惟鉞之兴，翦焉則定。","洪惟我理，式和以敬。","羣頑既夷，庶績咸正。","皇謨載大，惟人之慶。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 鼓吹鐃歌 靖本邦 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbde2fca-6bfe-4f14-bf89-5df0f900b277', '鼓吹曲辭 鼓吹鐃歌 吐谷渾', '鼓吹曲辞 鼓吹鐃歌 吐谷渾', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["吐谷渾盛彊，背西海以夸。","歲侵擾我疆，退匿險且遐。","帝謂神武師，往征靖皇家。","烈烈斾其旗，熊虎雜龍蛇。","王旅千萬人，銜枚默無譁。","束刃踰山徼，張翼縱漠沙。","一舉刈羶腥，尸骸積如麻。","除惡務本根，況敢遺萌芽。","洋洋西海水，威命窮天涯。","係虜來王都，犒樂窮休嘉。","登高望還師，竟野如春華。","行者靡不歸，親戚讙要遮。","凱旋獻清廟，萬國思無邪。"]', '["吐谷渾盛彊，背西海以夸。","歲侵擾我疆，退匿險且遐。","帝謂神武師，往征靖皇家。","烈烈斾其旗，熊虎杂龙蛇。","王旅千万人，銜枚默無譁。","束刃踰山徼，張翼縱漠沙。","一舉刈羶腥，尸骸積如麻。","除惡務本根，況敢遺萌芽。","洋洋西海水，威命窮天涯。","係虜来王都，犒乐窮休嘉。","登高望還師，竟野如春华。","行者靡不归，親戚讙要遮。","凱旋獻清廟，万国思無邪。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 鼓吹鐃歌 吐谷渾 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9acb857-f038-4a86-a5a5-8a3266306b8e', '鼓吹曲辭 鼓吹鐃歌 高昌', '鼓吹曲辞 鼓吹鐃歌 高昌', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["麴氏雄西北，別絕臣外區。","既恃遠且險，縱傲不我虞。","烈烈王者師，熊螭以爲徒。","龍旂飜海浪，馹騎馳坤隅。","賁育搏嬰兒，一掃不復餘。","平沙際天極，但見黃雲驅。","臣靖執長纓，智勇伏囚拘。","文皇南面坐，夷狄千羣趨。","咸稱天子神，往古不得俱。","獻號天可汗，以覆我國都。","兵戎不交害，各保性與軀。"]', '["麴氏雄西北，別絕臣外區。","既恃远且險，縱傲不我虞。","烈烈王者師，熊螭以爲徒。","龙旂飜海浪，馹騎驰坤隅。","賁育搏嬰兒，一掃不复餘。","平沙際天極，但见黄云驱。","臣靖執长纓，智勇伏囚拘。","文皇南面坐，夷狄千羣趨。","咸稱天子神，往古不得俱。","獻號天可汗，以覆我国都。","兵戎不交害，各保性與軀。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 鼓吹鐃歌 高昌 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d402fecd-b9e6-422c-bba2-d85184b69622', '鼓吹曲辭 鼓吹鐃歌 東蠻', '鼓吹曲辞 鼓吹鐃歌 东蠻', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["東蠻有謝氏，冠帶理海中。","自言我異世，雖聖莫能通。","王卒如飛翰，鵬鶱駭羣龍。","轟然自天墜，乃信神武功。","繫虜君臣人，累累來自東。","無思不服從，唐業如山崇。","百辟拜稽首，咸願圖形容。","如周王會書，永永傳無窮。","睢盱萬狀乖，咿嗢九譯重。","廣輪撫四海，浩浩知皇風。","歌詩鐃鼓間，以壯我元戎。"]', '["东蠻有謝氏，冠带理海中。","自言我異世，雖聖莫能通。","王卒如飞翰，鵬鶱駭羣龙。","轟然自天墜，乃信神武功。","繫虜君臣人，累累来自东。","無思不服從，唐業如山崇。","百辟拜稽首，咸願圖形容。","如周王會书，永永傳無窮。","睢盱万狀乖，咿嗢九譯重。","廣輪撫四海，浩浩知皇风。","歌诗鐃鼓间，以壯我元戎。"]', '诗', 'shi', '', NULL, '鼓吹曲辭 鼓吹鐃歌 東蠻 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bde2cd8e-b62c-4b95-b396-94467a949e6b', '橫吹曲辭 隴頭', '橫吹曲辞 隴头', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["隴頭已斷人不行，胡騎夜入涼州城。","漢家處處格鬬死，一朝盡沒隴西地。","驅我邊人胡中去，散放牛羊食禾黍。","去年中國養子孫，今著氈裘學胡語。","誰能更使李輕車，收取涼州屬漢家。"]', '["隴头已斷人不行，胡騎夜入涼州城。","漢家处处格鬬死，一朝尽沒隴西地。","驱我邊人胡中去，散放牛羊食禾黍。","去年中国養子孫，今著氈裘学胡語。","誰能更使李轻车，收取涼州屬漢家。"]', '诗', 'shi', '', NULL, '橫吹曲辭 隴頭 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc0d85da-2fc0-4cd0-9163-b23561e07541', '橫吹曲辭 隴頭吟', '橫吹曲辞 隴头吟', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["長安少年遊俠客，夜上戍樓看太白。","隴頭明月迥臨關，隴上行人夜吹笛。","關西老將不勝愁，駐馬聽之雙淚流。","身經大小百餘戰，麾下偏裨萬戶侯。","蘇武纔爲典屬國，節旄空盡海西頭。"]', '["长安少年游俠客，夜上戍楼看太白。","隴头明月迥臨关，隴上行人夜吹笛。","关西老將不勝愁，駐马听之雙泪流。","身經大小百餘戰，麾下偏裨万戶侯。","蘇武纔爲典屬国，節旄空尽海西头。"]', '诗', 'shi', '', NULL, '橫吹曲辭 隴頭吟 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b423f06b-4c05-4892-a409-7933ccf2edf8', '橫吹曲辭 隴頭吟', '橫吹曲辞 隴头吟', '60e56738-e921-4ab7-a3b3-c2203aac059b', '唐', '["隴水潺湲隴樹黃，征人隴上盡思鄉。","馬嘶斜日朔風急，雁過寒雲邊思長。","殘月出林明劒戟，平沙隔水見牛羊。","橫行俱足封侯者，誰斬樓蘭獻未央。"]', '["隴水潺湲隴樹黄，征人隴上尽思乡。","马嘶斜日朔风急，雁過寒云邊思长。","殘月出林明劒戟，平沙隔水见牛羊。","橫行俱足封侯者，誰斬楼蘭獻未央。"]', '诗', 'shi', '', NULL, '橫吹曲辭 隴頭吟 翁綬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7dbf19d4-6bb7-4e82-8d6a-c2cf8ac02ec7', '橫吹曲辭 隴頭水', '橫吹曲辞 隴头水', '7d3c6801-907a-4338-9040-ac5767a7b007', '唐', '["隴頭秋月明，隴水帶關城。","笳添離別曲，風送斷腸聲。","映雪峰猶暗，乘冰馬屢驚。","霧中寒雁至，沙上轉蓬輕。","天山傳羽檄，漢地急徵兵。","陣開都護道，劒聚伏波營。","於茲覺無度，方共濯胡纓。"]', '["隴头秋月明，隴水带关城。","笳添離別曲，风送斷腸声。","映雪峰猶暗，乘冰马屢驚。","霧中寒雁至，沙上轉蓬轻。","天山傳羽檄，漢地急徵兵。","陣开都護道，劒聚伏波營。","於茲覺無度，方共濯胡纓。"]', '诗', 'shi', '', NULL, '橫吹曲辭 隴頭水 楊師道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5b4927a-9a37-4e40-87ee-e75fff02d48a', '橫吹曲辭 隴頭水', '橫吹曲辞 隴头水', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["隴坂高無極，征人一望鄉。","關河別去水，沙塞斷歸腸。","馬繫千年樹，旌懸九月霜。","從來共嗚咽，皆是爲勤王。"]', '["隴坂高無極，征人一望乡。","关河別去水，沙塞斷归腸。","马繫千年樹，旌懸九月霜。","從来共嗚咽，皆是爲勤王。"]', '诗', 'shi', '', NULL, '橫吹曲辭 隴頭水 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25651b06-a58e-405f-a539-a86385e96468', '橫吹曲辭 隴頭水', '橫吹曲辞 隴头水', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["隴水何年隴頭別，不在山中亦嗚咽。","征人塞耳馬不行，未到隴頭聞水聲。","謂是西流入蒲海，還聞北海繞龍城。","隴東隴西多屈曲，野麋飲水長簇簇。","胡兵夜回水傍住，憶著來時磨劒處。","向前無井復無泉，放馬回看隴頭樹。"]', '["隴水何年隴头別，不在山中亦嗚咽。","征人塞耳马不行，未到隴头闻水声。","謂是西流入蒲海，還闻北海繞龙城。","隴东隴西多屈曲，野麋饮水长簇簇。","胡兵夜回水傍住，憶著来时磨劒处。","向前無井复無泉，放马回看隴头樹。"]', '诗', 'shi', '', NULL, '橫吹曲辭 隴頭水 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de0c30f3-bf7b-4870-b0fa-53222f2d27a0', '橫吹曲辭 隴頭水', '橫吹曲辞 隴头水', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["借問隴頭水，終年恨何事。","深疑嗚咽聲，中有征人淚。","昨日上山下，達曙不能寐。","何處接長波？東流入清渭。"]', '["借问隴头水，終年恨何事。","深疑嗚咽声，中有征人泪。","昨日上山下，達曙不能寐。","何处接长波？东流入清渭。"]', '诗', 'shi', '', NULL, '橫吹曲辭 隴頭水 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d531f315-bcc5-45b6-af4d-8752eef92780', '橫吹曲辭 隴頭水 一', '橫吹曲辞 隴头水 一', 'd031d511-00fb-47fd-8345-864309b121e2', '唐', '["隴頭心欲絕，隴水不堪聞。","碎影搖槍壘，寒聲咽帳軍。","素從鹽海積，綠帶柳城分。","日落天邊望，逶迤入塞雲。"]', '["隴头心欲絕，隴水不堪闻。","碎影搖槍壘，寒声咽帳軍。","素從鹽海積，綠带柳城分。","日落天邊望，逶迤入塞云。"]', '诗', 'shi', '', NULL, '橫吹曲辭 隴頭水 一 僧皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16178e3c-c37a-4d17-baaf-ff160cbe4d98', '橫吹曲辭 隴頭水 二', '橫吹曲辞 隴头水 二', 'd031d511-00fb-47fd-8345-864309b121e2', '唐', '["秦隴逼氐羌，征人去未央。","如何幽咽水，幷欲斷君腸。","西注悲窮漠，東分憶故鄉。","旅魂聲攪亂，無夢到遼陽。"]', '["秦隴逼氐羌，征人去未央。","如何幽咽水，幷欲斷君腸。","西注悲窮漠，东分憶故乡。","旅魂声攪亂，無梦到遼陽。"]', '诗', 'shi', '', NULL, '橫吹曲辭 隴頭水 二 僧皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e38232f-f517-43be-8d90-4945ae90b92b', '橫吹曲辭 隴頭水', '橫吹曲辞 隴头水', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["隴頭水，千古不堪聞。","生歸蘇屬國，死別李將軍。","細響風凋草，清哀雁落雲。"]', '["隴头水，千古不堪闻。","生归蘇屬国，死別李將軍。","細响风凋草，清哀雁落云。"]', '诗', 'shi', '', NULL, '橫吹曲辭 隴頭水 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca2d41ce-a190-4d9b-b000-1670b6ffc9f6', '橫吹曲辭 隴頭水', '橫吹曲辞 隴头水', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["借問隴頭水，年年恨何事。","全疑嗚咽聲，中有征人淚。","自古無長策，況我非深智。","何計謝潺湲，一宵空不寐。"]', '["借问隴头水，年年恨何事。","全疑嗚咽声，中有征人泪。","自古無长策，況我非深智。","何計謝潺湲，一宵空不寐。"]', '诗', 'shi', '', NULL, '橫吹曲辭 隴頭水 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed0d4f1c-f300-48b1-8139-706fb3a1aa2c', '橫吹曲辭 出關', '橫吹曲辞 出关', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["中原還逐鹿，投筆事戎軒。","縱橫計不就，慷慨志猶存。","策杖謁天子，驅馬出關門。","請纓羈南越，憑軾下東藩。","鬱紆陟高岫，出沒望平原。","古木吟寒鳥，空山啼夜猨。","既傷千里目，還驚九折魂。","豈不憚艱險，深懷國士恩。","季布無二諾，侯嬴重一言。","人生感意氣，功名誰復論。"]', '["中原還逐鹿，投笔事戎軒。","縱橫計不就，慷慨志猶存。","策杖謁天子，驱马出关门。","請纓羈南越，憑軾下东藩。","鬱紆陟高岫，出沒望平原。","古木吟寒鸟，空山啼夜猨。","既傷千里目，還驚九折魂。","豈不憚艱險，深懷国士恩。","季布無二諾，侯嬴重一言。","人生感意氣，功名誰复論。"]', '诗', 'shi', '', NULL, '橫吹曲辭 出關 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f918987-407c-4c93-a9dd-a3d975988a70', '橫吹曲辭 入關', '橫吹曲辞 入关', 'd93add19-48bd-4978-b27c-0501386290fb', '唐', '["河上微風來，關頭樹初溼。","今朝關城吏，又見孤客入。","上國誰與期，西來徒自急。"]', '["河上微风来，关头樹初溼。","今朝关城吏，又见孤客入。","上国誰與期，西来徒自急。"]', '诗', 'shi', '', NULL, '橫吹曲辭 入關 賈馳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3699e7b-dd2c-4d73-8e85-30e42f7363da', '橫吹曲辭 入關', '橫吹曲辞 入关', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["都城連百二，雄險北回環。","地勢遙尊岳，河流側讓關。","秦皇曾虎視，漢祖亦龍顏。","何事梟兇輩，干戈自不閑。"]', '["都城連百二，雄險北回环。","地勢遙尊岳，河流側讓关。","秦皇曾虎視，漢祖亦龙顏。","何事梟兇輩，干戈自不闲。"]', '诗', 'shi', '', NULL, '橫吹曲辭 入關 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('095c38dc-90fd-452f-812f-7dbf7c5662a2', '橫吹曲辭 出塞', '橫吹曲辞 出塞', 'c1fedae5-e7a5-4a8f-888b-1bf1e4629b80', '唐', '["匈奴屢不平，漢將欲縱橫。","看雲方結陣，却月始連營。","潛軍度馬邑，揚斾掩龍城。","會勒燕然石，方傳車騎名。"]', '["匈奴屢不平，漢將欲縱橫。","看云方結陣，却月始連營。","潛軍度马邑，揚斾掩龙城。","會勒燕然石，方傳车騎名。"]', '诗', 'shi', '', NULL, '橫吹曲辭 出塞 竇威 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('252c40ba-d76c-4893-925b-41883a6f254c', '橫吹曲辭 出塞', '橫吹曲辞 出塞', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["忽聞天上將，關塞重橫行。","始返樓蘭國，還向朔方城。","黃金裝戰馬，白羽集神兵。","星月開天陣，山川列地營。","晚風吹畫角，春色耀飛旌。","寧知班定遠，獨是一書生。"]', '["忽闻天上將，关塞重橫行。","始返楼蘭国，還向朔方城。","黄金裝戰马，白羽集神兵。","星月开天陣，山川列地營。","晚风吹畫角，春色耀飞旌。","寧知班定远，独是一书生。"]', '诗', 'shi', '', NULL, '橫吹曲辭 出塞 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57239e87-5c37-4c28-b253-a7bc96649ea4', '橫吹曲辭 出塞', '橫吹曲辞 出塞', '8c6d0222-cd7a-4245-84ee-9243a6a08e1c', '唐', '["俠客重恩光，驄馬飾金裝。","瞥聞傳羽檄，馳突救邊荒。","轉戰磨筓地，橫行戴斗鄉。","將軍占太白，小婦怨流黃。","騕褭青絲騎，娉婷紅粉妝。","一春鶯度曲，八月雁成行。","誰堪坐秋思，羅袖拂空牀。"]', '["俠客重恩光，驄马飾金裝。","瞥闻傳羽檄，驰突救邊荒。","轉戰磨筓地，橫行戴斗乡。","將軍占太白，小婦怨流黄。","騕褭青絲騎，娉婷紅粉妝。","一春鶯度曲，八月雁成行。","誰堪坐秋思，羅袖拂空牀。"]', '诗', 'shi', '', NULL, '橫吹曲辭 出塞 張易之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c22b677-c55e-4870-ace3-3450f93b17c1', '橫吹曲辭 出塞', '橫吹曲辞 出塞', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["十年通大漠，萬里出長平。","寒日生戈劒，陰雲搖斾旌。","飢烏啼舊壘，疲馬戀空城。","辛苦[皋蘭]北，胡霜損漢兵。"]', '["十年通大漠，万里出长平。","寒日生戈劒，陰云搖斾旌。","飢烏啼旧壘，疲马戀空城。","辛苦[皋蘭]北，胡霜損漢兵。"]', '诗', 'shi', '', NULL, '橫吹曲辭 出塞 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4fdb460-0944-4976-85a9-527bc87f7d7a', '橫吹曲辭 出塞', '橫吹曲辞 出塞', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["居延城外獵天驕，白草連天野火燒。","暮雲空磧時驅馬，秋日平原好射鵰。","護羌校尉朝乘障，破虜將軍夜渡遼。","玉靶角弓珠勒馬，漢家將賜霍嫖姚。"]', '["居延城外獵天驕，白草連天野火燒。","暮云空磧时驱马，秋日平原好射鵰。","護羌校尉朝乘障，破虜將軍夜渡遼。","玉靶角弓珠勒马，漢家將賜霍嫖姚。"]', '诗', 'shi', '', NULL, '橫吹曲辭 出塞 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d0385e7-0c72-423f-a538-f66acc9d4c46', '橫吹曲辭 出塞 一', '橫吹曲辞 出塞 一', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["秦時明月漢時關，萬里長征人未還。","但使龍城飛將在，不教胡馬度陰山。"]', '["秦时明月漢时关，万里长征人未還。","但使龙城飞將在，不教胡马度陰山。"]', '诗', 'shi', '', NULL, '橫吹曲辭 出塞 一 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('762e0a43-b8ed-4a11-bb82-28958998d354', '橫吹曲辭 出塞 二', '橫吹曲辞 出塞 二', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["白花垣上望京師，黃河水流無盡時。","窮秋曠野行人絕，馬首東來知是誰。"]', '["白花垣上望京師，黄河水流無尽时。","窮秋曠野行人絕，马首东来知是誰。"]', '诗', 'shi', '', NULL, '橫吹曲辭 出塞 二 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2898783-b22c-4ded-b6c0-492b879a3b2d', '橫吹曲辭 出塞', '橫吹曲辞 出塞', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["金帶連環束戰袍，馬頭衝雪度臨洮。","卷旗夜劫單于帳，亂斫胡兵缺寶刀。"]', '["金带連环束戰袍，马头衝雪度臨洮。","卷旗夜劫單于帳，亂斫胡兵缺寶刀。"]', '诗', 'shi', '', NULL, '橫吹曲辭 出塞 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acd96031-2a20-4c02-bed0-033329160c8d', '橫吹曲辭 前出塞九首 一', '橫吹曲辞 前出塞九首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["戚戚去故里，悠悠赴交河。","公家有程期，亡命嬰禍羅。","君已富土境，開邊一何多？","棄絕父母恩，吞聲行負戈。"]', '["戚戚去故里，悠悠赴交河。","公家有程期，亡命嬰禍羅。","君已富土境，开邊一何多？","棄絕父母恩，吞声行負戈。"]', '诗', 'shi', '', NULL, '橫吹曲辭 前出塞九首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d572cc60-44fc-40c3-9c2f-08e966153fdd', '橫吹曲辭 前出塞九首 二', '橫吹曲辞 前出塞九首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["出門日已遠，不受徒旅欺。","骨肉恩豈斷，男兒死無時。","走馬脫轡頭，手中挑青絲。","捷下萬仞岡，俯身試搴旗。"]', '["出门日已远，不受徒旅欺。","骨肉恩豈斷，男兒死無时。","走马脫轡头，手中挑青絲。","捷下万仞岡，俯身試搴旗。"]', '诗', 'shi', '', NULL, '橫吹曲辭 前出塞九首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8e0db16-f56c-4180-bc8f-9724551bd8fc', '橫吹曲辭 前出塞九首 三', '橫吹曲辞 前出塞九首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["磨刀嗚咽水，水赤刃傷手。","欲輕腸斷聲，心緒亂已久。","丈夫誓許國，憤惋復何有？","功名圖麒麟，戰骨當速朽。"]', '["磨刀嗚咽水，水赤刃傷手。","欲轻腸斷声，心緒亂已久。","丈夫誓許国，憤惋复何有？","功名圖麒麟，戰骨當速朽。"]', '诗', 'shi', '', NULL, '橫吹曲辭 前出塞九首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef9d3efd-0eb2-413e-a455-2ee05bc16f7d', '橫吹曲辭 前出塞九首 四', '橫吹曲辞 前出塞九首 四', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["送徒既有長，遠戍亦有身。","生死向前去，不勞吏怒嗔。","路逢相識人，附書與六親。","哀哉兩決絕，不復同苦辛。"]', '["送徒既有长，远戍亦有身。","生死向前去，不勞吏怒嗔。","路逢相識人，附书與六親。","哀哉兩決絕，不复同苦辛。"]', '诗', 'shi', '', NULL, '橫吹曲辭 前出塞九首 四 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d98f9148-c34c-47fb-9ec5-256813983782', '橫吹曲辭 前出塞九首 五', '橫吹曲辞 前出塞九首 五', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["迢迢萬餘里，領我赴三軍。","軍中異苦樂，主將寧盡聞。","隔河見胡騎，倏忽數百羣。","我始爲奴僕，幾時樹功勳。"]', '["迢迢万餘里，領我赴三軍。","軍中異苦乐，主將寧尽闻。","隔河见胡騎，倏忽數百羣。","我始爲奴僕，幾时樹功勳。"]', '诗', 'shi', '', NULL, '橫吹曲辭 前出塞九首 五 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5683781e-f55a-49ad-8c3a-de7a2f217a35', '橫吹曲辭 前出塞九首 六', '橫吹曲辞 前出塞九首 六', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["挽弓當挽彊，用箭當用長。","射人先射馬，擒賊先擒王。","殺人亦有限，列國自有疆。","苟能制侵陵，豈在多殺傷。"]', '["挽弓當挽彊，用箭當用长。","射人先射马，擒賊先擒王。","殺人亦有限，列国自有疆。","苟能制侵陵，豈在多殺傷。"]', '诗', 'shi', '', NULL, '橫吹曲辭 前出塞九首 六 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68f3ddee-deaa-484e-b375-0b6eed8bb3b9', '橫吹曲辭 前出塞九首 七', '橫吹曲辞 前出塞九首 七', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["驅馬天雨雪，軍行入高山。","逕危抱寒石，指落曾冰間。","已去漢月遠，何時築城還？","浮雲暮南征，可望不可攀。"]', '["驱马天雨雪，軍行入高山。","逕危抱寒石，指落曾冰间。","已去漢月远，何时築城還？","浮云暮南征，可望不可攀。"]', '诗', 'shi', '', NULL, '橫吹曲辭 前出塞九首 七 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('673d52b8-9294-415e-a813-70dbb937e446', '橫吹曲辭 前出塞九首 八', '橫吹曲辞 前出塞九首 八', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["單于寇我壘，百里風塵昏。","雄劒四五動，彼軍爲我奔。","虜其名王歸，繫頸授轅門。","潛身備行列，一勝何足論。"]', '["單于寇我壘，百里风塵昏。","雄劒四五动，彼軍爲我奔。","虜其名王归，繫頸授轅门。","潛身備行列，一勝何足論。"]', '诗', 'shi', '', NULL, '橫吹曲辭 前出塞九首 八 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90f09f62-6f50-4e25-a5ba-a20b6a345311', '橫吹曲辭 前出塞九首 九', '橫吹曲辞 前出塞九首 九', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["從軍十年餘，能無分寸功。","衆人貴苟得，欲語羞雷同。","中原有鬬爭，況在狄與戎。","丈夫四方志，安可辭固窮。"]', '["從軍十年餘，能無分寸功。","衆人貴苟得，欲語羞雷同。","中原有鬬爭，況在狄與戎。","丈夫四方志，安可辞固窮。"]', '诗', 'shi', '', NULL, '橫吹曲辭 前出塞九首 九 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72fc17eb-8b81-4de1-b38e-eb035f412a2b', '橫吹曲辭 後出塞五首 一', '橫吹曲辞 後出塞五首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["男兒生世間，及壯當封侯。","戰伐有功業，焉能守舊丘。","召募赴薊門，軍動不可留。","千金買馬鞭，百金裝刀頭。","閭里送我行，親戚擁道周。","斑白居上列，酒酣進庶羞。","少年別有贈，含笑看吳鉤。"]', '["男兒生世间，及壯當封侯。","戰伐有功業，焉能守旧丘。","召募赴薊门，軍动不可留。","千金買马鞭，百金裝刀头。","閭里送我行，親戚擁道周。","斑白居上列，酒酣進庶羞。","少年別有贈，含笑看吳鉤。"]', '诗', 'shi', '', NULL, '橫吹曲辭 後出塞五首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be5ce2f9-2aaf-40b1-8f05-1a5817447ed3', '橫吹曲辭 後出塞五首 二', '橫吹曲辞 後出塞五首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["朝進東門營，暮上河陽橋。","落日照大旗，馬鳴風蕭蕭。","平沙列萬幕，部伍各見招。","中天懸明月，令嚴夜寂寥。","悲笳數聲動，壯士慘不驕。","借問大將誰，恐是霍嫖姚。"]', '["朝進东门營，暮上河陽橋。","落日照大旗，马鳴风蕭蕭。","平沙列万幕，部伍各见招。","中天懸明月，令嚴夜寂寥。","悲笳數声动，壯士慘不驕。","借问大將誰，恐是霍嫖姚。"]', '诗', 'shi', '', NULL, '橫吹曲辭 後出塞五首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dffcc914-3b19-401d-963b-59c75a017857', '橫吹曲辭 後出塞五首 三', '橫吹曲辞 後出塞五首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["古人重守邊，今人重高勳。","豈知英雄主，出師亙長雲。","六合已一家，四夷且孤軍。","遂使貔虎士，奮身勇所聞。","拔劒擊大荒，日牧胡馬羣。","誓開玄冥北，持以奉吾君。"]', '["古人重守邊，今人重高勳。","豈知英雄主，出師亙长云。","六合已一家，四夷且孤軍。","遂使貔虎士，奮身勇所闻。","拔劒擊大荒，日牧胡马羣。","誓开玄冥北，持以奉吾君。"]', '诗', 'shi', '', NULL, '橫吹曲辭 後出塞五首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e5677e0-c5ef-4f85-8cf0-1cbb318caba3', '橫吹曲辭 後出塞五首 四', '橫吹曲辞 後出塞五首 四', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["獻凱日繼踵，兩蕃靜無虞。","漁陽豪俠地，擊鼓吹笙竽。","雲帆轉遼海，粳稻來東吳。","越羅與楚練，照耀輿臺軀。","主將位益崇，氣驕陵上都。","邊人不敢議，議者死路衢。"]', '["獻凱日繼踵，兩蕃静無虞。","漁陽豪俠地，擊鼓吹笙竽。","云帆轉遼海，粳稻来东吳。","越羅與楚練，照耀輿台軀。","主將位益崇，氣驕陵上都。","邊人不敢議，議者死路衢。"]', '诗', 'shi', '', NULL, '橫吹曲辭 後出塞五首 四 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0beb32d-c5fb-4a7b-a4b9-14f24dcdc148', '橫吹曲辭 後出塞五首 五', '橫吹曲辞 後出塞五首 五', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["我本良家子，出師亦多門。","將驕益愁思，身貴不足論。","躍馬二十年，恐辜明主恩。","坐見幽州騎，長驅河洛昏。","中夜間道歸，故里但空村。","惡名幸脫免，窮老無兒孫。"]', '["我本良家子，出師亦多门。","將驕益愁思，身貴不足論。","躍马二十年，恐辜明主恩。","坐见幽州騎，长驱河洛昏。","中夜间道归，故里但空村。","惡名幸脫免，窮老無兒孫。"]', '诗', 'shi', '', NULL, '橫吹曲辭 後出塞五首 五 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2490ba49-411c-4172-bb14-75bba4ebe6e8', '橫吹曲辭 出塞', '橫吹曲辞 出塞', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["吹角出塞門，前瞻即胡地。","三軍盡回首，皆灑望鄉淚。","轉念關山長，行看風景異。","由來征戍客，各負輕生義。"]', '["吹角出塞门，前瞻即胡地。","三軍尽回首，皆灑望乡泪。","轉念关山长，行看风景異。","由来征戍客，各負轻生義。"]', '诗', 'shi', '', NULL, '橫吹曲辭 出塞 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcdf6f13-4cb9-418f-9279-c690522e0a27', '橫吹曲辭 出塞', '橫吹曲辞 出塞', 'af2de6ea-bee2-4c52-a3b6-185b2321d1a7', '唐', '["黃砂直上白雲間，一片孤城萬仞山。","羌笛何須怨楊柳，春風不度玉門關。"]', '["黄砂直上白云间，一片孤城万仞山。","羌笛何須怨楊柳，春风不度玉门关。"]', '诗', 'shi', '', NULL, '橫吹曲辭 出塞 王之渙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02da7d16-a042-4720-95e6-f4528b25db22', '橫吹曲辭 出塞', '橫吹曲辞 出塞', '7c891598-5c2d-4135-b2cd-60fcb5f29523', '唐', '["漢家邊事重，竇憲出臨戎。","絕漠秋山在，陽關舊路通。","列營依茂草，吹角向高風。","更就燕然石，看銘破虜功。"]', '["漢家邊事重，竇憲出臨戎。","絕漠秋山在，陽关旧路通。","列營依茂草，吹角向高风。","更就燕然石，看銘破虜功。"]', '诗', 'shi', '', NULL, '橫吹曲辭 出塞 耿[湋] shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66c91188-9381-4c8c-a58a-55b575e30e7e', '橫吹曲辭 出塞', '橫吹曲辞 出塞', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["秋塞雪初下，將軍遠出師。","分營長記火，放馬不收旗。","月冷邊帳溼，沙昏夜探遲。","征人皆白首，誰見滅胡時。"]', '["秋塞雪初下，將軍远出師。","分營长記火，放马不收旗。","月冷邊帳溼，沙昏夜探遲。","征人皆白首，誰见滅胡时。"]', '诗', 'shi', '', NULL, '橫吹曲辭 出塞 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('431d41ca-23ac-4372-961a-2433f18d1318', '橫吹曲辭 出塞', '橫吹曲辞 出塞', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["胡風不開花，四氣多作雪。","北人尚凍死，況我本南越。","古來犬羊地，巡狩無遺轍。","九土耕不盡，武皇猶征伐。","中天有高閣，圖畫何時歇？","坐恐塞上山，低於砂中骨。"]', '["胡风不开花，四氣多作雪。","北人尚凍死，況我本南越。","古来犬羊地，巡狩無遺轍。","九土耕不尽，武皇猶征伐。","中天有高閣，圖畫何时歇？","坐恐塞上山，低於砂中骨。"]', '诗', 'shi', '', NULL, '橫吹曲辭 出塞 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ece9f6a-9b24-427a-9ef7-dce93f2f388e', '橫吹曲辭 出塞曲', '橫吹曲辞 出塞曲', 'da5a7490-653b-4c06-ab52-60383bd0ee9f', '唐', '["將軍在重圍，音信絕不通。","羽書如流星，飛人甘泉宮。","倚是幷州兒，少年心膽雄。","一朝隨召募，百戰爭王公。","去年桑乾北，今年桑乾東。","死是征人死，功是將軍功。","汗馬牧秋月，疲兵臥霜風。","仍聞左賢王，更欲圖雲中。"]', '["將軍在重圍，音信絕不通。","羽书如流星，飞人甘泉宮。","倚是幷州兒，少年心膽雄。","一朝隨召募，百戰爭王公。","去年桑乾北，今年桑乾东。","死是征人死，功是將軍功。","汗马牧秋月，疲兵臥霜风。","仍闻左賢王，更欲圖云中。"]', '诗', 'shi', '', NULL, '橫吹曲辭 出塞曲 劉濟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74f0a8c9-85dc-4c78-b342-91128d6302f1', '橫吹曲辭 出塞曲 一', '橫吹曲辞 出塞曲 一', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["微雪將軍出，吹笳天未明。","觀兵登古戍，斬將對雙旌。","分陣瞻山勢，潛軍制馬鳴。","如今新史上，已有滅胡名。"]', '["微雪將軍出，吹笳天未明。","观兵登古戍，斬將对雙旌。","分陣瞻山勢，潛軍制马鳴。","如今新史上，已有滅胡名。"]', '诗', 'shi', '', NULL, '橫吹曲辭 出塞曲 一 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db605400-358d-4cb3-93af-2b6316ae9620', '橫吹曲辭 出塞曲 二', '橫吹曲辞 出塞曲 二', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["單于驕愛獵，放火到軍城。","待月調新弩，防秋置遠營。","空山朱戟影，寒磧鐵衣聲。","逢著降胡說，陰山有伏兵。"]', '["單于驕愛獵，放火到軍城。","待月調新弩，防秋置远營。","空山朱戟影，寒磧鐵衣声。","逢著降胡说，陰山有伏兵。"]', '诗', 'shi', '', NULL, '橫吹曲辭 出塞曲 二 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3e9b8e1-20e3-4118-982f-2c86532449e3', '橫吹曲辭 出塞曲 一', '橫吹曲辞 出塞曲 一', '2f390450-2daa-424a-9330-8269402ce797', '唐', '["埽盡狂胡跡，回戈望故關。","相逢唯死鬬，豈易得生還。","縱宴參胡樂，收兵過雪山。","不封十萬戶，此事亦應閑。"]', '["埽尽狂胡跡，回戈望故关。","相逢唯死鬬，豈易得生還。","縱宴參胡乐，收兵過雪山。","不封十万戶，此事亦應闲。"]', '诗', 'shi', '', NULL, '橫吹曲辭 出塞曲 一 僧貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de9b3a1a-925d-445a-9e23-d03b0f64d388', '橫吹曲辭 出塞曲 二', '橫吹曲辞 出塞曲 二', '2f390450-2daa-424a-9330-8269402ce797', '唐', '["玉帳將軍意，慇懃把酒論。","功高寧在我，陣沒與招魂。","塞色干戈束，軍容喜氣屯。","男兒今始是，敢出玉關門。"]', '["玉帳將軍意，慇懃把酒論。","功高寧在我，陣沒與招魂。","塞色干戈束，軍容喜氣屯。","男兒今始是，敢出玉关门。"]', '诗', 'shi', '', NULL, '橫吹曲辭 出塞曲 二 僧貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ff26c9f-21a5-4f39-a073-48588fa2d692', '橫吹曲辭 出塞曲 三', '橫吹曲辞 出塞曲 三', '2f390450-2daa-424a-9330-8269402ce797', '唐', '["回首隴山頭，連天草木秋。","聖君應入夢，半路遣封侯。","水不擔陰雪，柴令倒戍樓。","歸來麟閣上，春色滿皇州。"]', '["回首隴山头，連天草木秋。","聖君應入梦，半路遣封侯。","水不擔陰雪，柴令倒戍楼。","归来麟閣上，春色满皇州。"]', '诗', 'shi', '', NULL, '橫吹曲辭 出塞曲 三 僧貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7351d633-de1e-4ea8-a6e3-f273b0c5dfe4', '橫吹曲辭 入塞', '橫吹曲辞 入塞', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["將軍陷虜圍，邊務息戎機。","霜雪交河盡，旌旗入塞飛。","曉光隨馬度，春色伴人歸。","課績朝明主，臨軒拜武威。"]', '["將軍陷虜圍，邊務息戎機。","霜雪交河尽，旌旗入塞飞。","晓光隨马度，春色伴人归。","課績朝明主，臨軒拜武威。"]', '诗', 'shi', '', NULL, '橫吹曲辭 入塞 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b589b292-8d99-4cc9-9680-59b25cf3a7ce', '橫吹曲辭 入塞曲', '橫吹曲辞 入塞曲', '7c891598-5c2d-4135-b2cd-60fcb5f29523', '唐', '["將軍帶十圍，重錦製戎衣。","猨臂銷弓力，虯鬚長劒威。","首登平樂宴，新破大宛歸。","樓上姝姬笑，門前問客稀。","暮烽玄菟急，秋草紫騮肥。","未奉君主詔，高槐晝掩扉。"]', '["將軍带十圍，重錦製戎衣。","猨臂銷弓力，虯鬚长劒威。","首登平乐宴，新破大宛归。","楼上姝姬笑，门前问客稀。","暮烽玄菟急，秋草紫騮肥。","未奉君主詔，高槐晝掩扉。"]', '诗', 'shi', '', NULL, '橫吹曲辭 入塞曲 耿[湋] shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5dd824cf-e4bc-4a99-a85a-48e2688ebbb2', '橫吹曲辭 入塞曲 一', '橫吹曲辞 入塞曲 一', '2f390450-2daa-424a-9330-8269402ce797', '唐', '["單于烽火動，都護去天涯。","別賜黃金甲，親臨白玉墀。","塞垣須靜謐，師旅審安危。","定遠條支寵，如今勝古時。"]', '["單于烽火动，都護去天涯。","別賜黄金甲，親臨白玉墀。","塞垣須静謐，師旅審安危。","定远條支寵，如今勝古时。"]', '诗', 'shi', '', NULL, '橫吹曲辭 入塞曲 一 僧貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5c68f7a-8b75-42f3-b211-39bad532530b', '橫吹曲辭 入塞曲 二', '橫吹曲辞 入塞曲 二', '2f390450-2daa-424a-9330-8269402ce797', '唐', '["方見將軍貴，分明對冕旒。","聖恩如遠被，狂虜不難收。","臣節唯期死，功勳敢望侯。","終辭修里第，從此出皇州。"]', '["方见將軍貴，分明对冕旒。","聖恩如远被，狂虜不难收。","臣節唯期死，功勳敢望侯。","終辞修里第，從此出皇州。"]', '诗', 'shi', '', NULL, '橫吹曲辭 入塞曲 二 僧貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3158200-d1f5-4b2b-9da9-d392e57f8555', '橫吹曲辭 入塞曲 三', '橫吹曲辞 入塞曲 三', '2f390450-2daa-424a-9330-8269402ce797', '唐', '["百里精兵動，參差便渡遼。","如何好白日，亦照此天驕。","遠樹深疑賊，驚蓬迥似鵰。","凱歌何日唱？磧路共天遙。"]', '["百里精兵动，參差便渡遼。","如何好白日，亦照此天驕。","远樹深疑賊，驚蓬迥似鵰。","凱歌何日唱？磧路共天遙。"]', '诗', 'shi', '', NULL, '橫吹曲辭 入塞曲 三 僧貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6281fbf0-c461-4efe-ac5d-26e86d33fc49', '橫吹曲辭 入塞曲 一', '橫吹曲辞 入塞曲 一', '49d09d65-92ee-43dd-a9f1-1d23f75b9ff0', '唐', '["欲爲皇王服遠戎，萬人金甲鼓鼙中。","陣雲暗塞三邊黑，兵血愁天一片紅。","半夜飜營旗攪月，深秋防戍劒磨風。","謗書未及明君爇，臥骨將軍已歿功。"]', '["欲爲皇王服远戎，万人金甲鼓鼙中。","陣云暗塞三邊黑，兵血愁天一片紅。","半夜飜營旗攪月，深秋防戍劒磨风。","謗书未及明君爇，臥骨將軍已歿功。"]', '诗', 'shi', '', NULL, '橫吹曲辭 入塞曲 一 沈彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('888fd3d3-d777-401d-8b4a-e94d3ab3607f', '橫吹曲辭 入塞曲 二', '橫吹曲辞 入塞曲 二', '49d09d65-92ee-43dd-a9f1-1d23f75b9ff0', '唐', '["苦戰沙間臥箭痕，戍樓閑上望星文。","生希國澤分偏將，死奪河源荅聖君。","鳶覰敗兵眠白草，馬驚邊鬼哭陰雲。","功多地遠無人紀，漢閣笙歌日又曛。"]', '["苦戰沙间臥箭痕，戍楼闲上望星文。","生希国澤分偏將，死奪河源荅聖君。","鳶覰敗兵眠白草，马驚邊鬼哭陰云。","功多地远無人紀，漢閣笙歌日又曛。"]', '诗', 'shi', '', NULL, '橫吹曲辭 入塞曲 二 沈彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70b41da6-9b4d-4392-b0fb-23ef70a1cd78', '橫吹曲辭 折楊柳', '橫吹曲辞 折楊柳', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["倡樓啓曙扉，園柳正依依。","鳥鳴知歲隔，條變識春歸。","露葉疑啼臉，風花亂舞衣。","攀折聊將寄，軍中書信稀。"]', '["倡楼啓曙扉，园柳正依依。","鸟鳴知歲隔，條变識春归。","露葉疑啼臉，风花亂舞衣。","攀折聊將寄，軍中书信稀。"]', '诗', 'shi', '', NULL, '橫吹曲辭 折楊柳 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34bac317-4e11-40fa-abae-731bfb0e8d9c', '橫吹曲辭 折楊柳', '橫吹曲辞 折楊柳', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["玉窗朝日映，羅帳春風吹。","拭淚攀楊柳，長條宛地垂。","白花飛歷亂，黃鳥思參差。","妾自肝腸斷，旁人那得知。"]', '["玉窗朝日映，羅帳春风吹。","拭泪攀楊柳，长條宛地垂。","白花飞歷亂，黄鸟思參差。","妾自肝腸斷，旁人那得知。"]', '诗', 'shi', '', NULL, '橫吹曲辭 折楊柳 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d5532a1-5286-4ccb-abdc-6118ad48504d', '橫吹曲辭 折楊柳', '橫吹曲辞 折楊柳', '5fbbb254-1f00-4d96-a79a-1a7d570b22ca', '唐', '["可憐濯濯春楊柳，攀折將來就纖手。","妾容與此同盛衰，何必君恩獨能久。"]', '["可怜濯濯春楊柳，攀折將来就纖手。","妾容與此同盛衰，何必君恩独能久。"]', '诗', 'shi', '', NULL, '橫吹曲辭 折楊柳 喬知之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35c4618c-3896-45f8-9b24-51764c90383f', '橫吹曲辭 折楊柳', '橫吹曲辞 折楊柳', '5b300b57-f5e8-470e-a5fb-166618c1fd98', '唐', '["沙塞三河道，金閨二月春。","碧煙楊柳色，紅粉綺羅人。","露葉憐啼臉，風花思舞巾。","攀持君不見，爲聽曲中新。"]', '["沙塞三河道，金閨二月春。","碧煙楊柳色，紅粉綺羅人。","露葉怜啼臉，风花思舞巾。","攀持君不见，爲听曲中新。"]', '诗', 'shi', '', NULL, '橫吹曲辭 折楊柳 劉憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e77033d-2c4f-4e60-8d42-3b1529f3c93c', '橫吹曲辭 折楊柳', '橫吹曲辞 折楊柳', '6dff31b1-c51d-4a3b-9a3d-4bd24d82e015', '唐', '["二月風光半，三邊戍不還。","年華妾自惜，楊柳爲君攀。","落絮緣衫袖，垂條拂髻鬟。","那堪音信斷，流涕望陽關。"]', '["二月风光半，三邊戍不還。","年华妾自惜，楊柳爲君攀。","落絮緣衫袖，垂條拂髻鬟。","那堪音信斷，流涕望陽关。"]', '诗', 'shi', '', NULL, '橫吹曲辭 折楊柳 崔湜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e651edd-1bc8-49c9-bd85-b49df84c9743', '橫吹曲辭 折楊柳', '橫吹曲辞 折楊柳', '1a2f17fc-4959-4965-acd0-6e6c5c735a73', '唐', '["萬里邊城地，三春楊柳節。","葉似鏡中眉，花如關外雪。","征人遠鄉思，倡婦高樓別。","不忍擲年華，含情寄攀折。"]', '["万里邊城地，三春楊柳節。","葉似镜中眉，花如关外雪。","征人远乡思，倡婦高楼別。","不忍擲年华，含情寄攀折。"]', '诗', 'shi', '', NULL, '橫吹曲辭 折楊柳 韋承慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba115d1b-606c-4751-af66-e617b670babd', '橫吹曲辭 折楊柳', '橫吹曲辞 折楊柳', 'fac6668d-5959-42b6-bc5f-b0059f44cf39', '唐', '["垂柳拂妝臺，葳蕤葉半開。","年華枝上見，邊思曲中來。","嫩色宜新雨，輕花伴落梅。","朝朝倦攀折，征戍幾時回。"]', '["垂柳拂妝台，葳蕤葉半开。","年华枝上见，邊思曲中来。","嫩色宜新雨，轻花伴落梅。","朝朝倦攀折，征戍幾时回。"]', '诗', 'shi', '', NULL, '橫吹曲辭 折楊柳 歐陽瑾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afb30a8c-345b-471d-bf80-9f1828f8e097', '橫吹曲辭 折楊柳', '橫吹曲辞 折楊柳', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["紅粉青樓曙，垂楊仲月春。","懷君重攀折，非妾妒腰身。","舞帶縈絲斷，嬌娥向葉嚬。","橫吹凡幾曲，獨自最愁人。"]', '["紅粉青楼曙，垂楊仲月春。","懷君重攀折，非妾妒腰身。","舞带縈絲斷，嬌娥向葉嚬。","橫吹凡幾曲，独自最愁人。"]', '诗', 'shi', '', NULL, '橫吹曲辭 折楊柳 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83057247-91ce-43d8-8aee-2eccfdcc8773', '橫吹曲辭 折楊柳', '橫吹曲辞 折楊柳', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["纖纖折楊柳，持此寄情人。","一枝何足貴，憐是故園春。","遲景那能久，流芳不及新。","更愁征戍客，鬢老邊城塵。"]', '["纖纖折楊柳，持此寄情人。","一枝何足貴，怜是故园春。","遲景那能久，流芳不及新。","更愁征戍客，鬢老邊城塵。"]', '诗', 'shi', '', NULL, '橫吹曲辭 折楊柳 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fd7fb7a-8fd1-45bc-9dcb-803c52590d34', '橫吹曲辭 折楊柳', '橫吹曲辞 折楊柳', '989cf688-5b65-440e-955a-6154c39ee7c3', '唐', '["大道連國門，東西種楊柳。","葳蕤君不見，褭娜垂來久。","緣枝棲暝禽，雄去雌獨吟。","餘花怨春盡，微月起秋陰。","坐望窗中蝶，起攀枝上葉。","好風吹長條，妸娜何如妾。","妾見柳園新，高樓四五春。","莫吹胡塞曲，愁殺隴頭人。"]', '["大道連国门，东西種楊柳。","葳蕤君不见，褭娜垂来久。","緣枝棲暝禽，雄去雌独吟。","餘花怨春尽，微月起秋陰。","坐望窗中蝶，起攀枝上葉。","好风吹长條，妸娜何如妾。","妾见柳园新，高楼四五春。","莫吹胡塞曲，愁殺隴头人。"]', '诗', 'shi', '', NULL, '橫吹曲辭 折楊柳 余延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e70730a9-552c-481c-aadc-364713afd410', '橫吹曲辭 折楊柳', '橫吹曲辞 折楊柳', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["垂楊拂綠水，搖豔東風年。","花明玉關雪，葉暖金窗煙。","美人結長恨，相對心悽然。","攀條折春色，遠寄龍庭前。"]', '["垂楊拂綠水，搖豔东风年。","花明玉关雪，葉暖金窗煙。","美人結长恨，相对心悽然。","攀條折春色，远寄龙庭前。"]', '诗', 'shi', '', NULL, '橫吹曲辭 折楊柳 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8e50d0a-dd19-4fa2-b07e-95882090e9d7', '橫吹曲辭 折楊柳 一', '橫吹曲辞 折楊柳 一', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["楊柳多短枝，短枝多別離。","贈遠累攀折，柔條安得垂。","青春有定節，離別無定時。","但恐人別促，不怨來遲遲。","莫言短枝條，中有長相思。","朱顏與綠楊，幷在別離期。"]', '["楊柳多短枝，短枝多別離。","贈远累攀折，柔條安得垂。","青春有定節，離別無定时。","但恐人別促，不怨来遲遲。","莫言短枝條，中有长相思。","朱顏與綠楊，幷在別離期。"]', '诗', 'shi', '', NULL, '橫吹曲辭 折楊柳 一 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f3bd134-ac28-4961-b0c9-141140f72e47', '橫吹曲辭 折楊柳 二', '橫吹曲辞 折楊柳 二', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["樓上春風過，風前楊柳歌。","枝疎緣別苦，曲怨爲年多。","花驚燕地雪，葉映楚池波。","誰堪別離此，征戍在交河。"]', '["楼上春风過，风前楊柳歌。","枝疎緣別苦，曲怨爲年多。","花驚燕地雪，葉映楚池波。","誰堪別離此，征戍在交河。"]', '诗', 'shi', '', NULL, '橫吹曲辭 折楊柳 二 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b2c85ac-3edd-43b7-aa6d-b32c31d01bd0', '橫吹曲辭 折楊柳', '橫吹曲辞 折楊柳', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["東城攀柳葉，柳葉低著草。","少壯莫輕年，輕年有人老。","柳發徧川崗，登高堪斷腸。","雨煙輕漠漠，何樹近君鄉？","贈君折楊柳，顏色豈能久。","上客莫霑巾，佳人正回首。","新柳送君行，古柳傷君情。","突兀臨荒渡，婆娑出舊營。","隋家兩岸盡，陶宅五株平。","日暮偏愁望，春山有鳥聲。"]', '["东城攀柳葉，柳葉低著草。","少壯莫轻年，轻年有人老。","柳發徧川崗，登高堪斷腸。","雨煙轻漠漠，何樹近君乡？","贈君折楊柳，顏色豈能久。","上客莫霑巾，佳人正回首。","新柳送君行，古柳傷君情。","突兀臨荒渡，婆娑出旧營。","隋家兩岸尽，陶宅五株平。","日暮偏愁望，春山有鸟声。"]', '诗', 'shi', '', NULL, '橫吹曲辭 折楊柳 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32744451-b4f4-47d1-866c-44b2675377c3', '橫吹曲辭 折楊柳', '橫吹曲辞 折楊柳', '60e56738-e921-4ab7-a3b3-c2203aac059b', '唐', '["紫陌金堤映綺羅，遊人處處動離歌。","陰移古戍迷荒草，花帶殘陽落遠波。","臺上少年吹白雪，樓中思婦斂青蛾。","殷勤攀折贈行客，此去關山雨雪多。"]', '["紫陌金堤映綺羅，游人处处动離歌。","陰移古戍迷荒草，花带殘陽落远波。","台上少年吹白雪，楼中思婦斂青蛾。","殷勤攀折贈行客，此去关山雨雪多。"]', '诗', 'shi', '', NULL, '橫吹曲辭 折楊柳 翁綬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f79c370b-2d76-4435-a1f5-b02ead762def', '橫吹曲辭 望行人', '橫吹曲辞 望行人', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["自從江樹秋，日日上江樓。","夢見離珠浦，書來在桂州。","不同魚比目，終恨水分流。","久不開明鏡，多應是白頭。"]', '["自從江樹秋，日日上江楼。","梦见離珠浦，书来在桂州。","不同鱼比目，終恨水分流。","久不开明镜，多應是白头。"]', '诗', 'shi', '', NULL, '橫吹曲辭 望行人 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce87b1d6-f5db-47fd-a979-034eb4888e26', '橫吹曲辭 望行人', '橫吹曲辞 望行人', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["秋風窗下起，旅雁向南飛。","日日出門望，家家行客歸。","無因見邊使，空待寄寒衣。","獨閉青樓暮，煙深鳥雀稀。"]', '["秋风窗下起，旅雁向南飞。","日日出门望，家家行客归。","無因见邊使，空待寄寒衣。","独閉青楼暮，煙深鸟雀稀。"]', '诗', 'shi', '', NULL, '橫吹曲辭 望行人 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d399e98-b466-4b4b-a451-5ab18ce88f35', '橫吹曲辭 關山月', '橫吹曲辞 关山月', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["塞垣通碣石，虜障抵祈連。","相思在萬里，明月正孤懸。","影移金岫北，光斷玉門前。","寄書謝中婦，時看鴻雁天。"]', '["塞垣通碣石，虜障抵祈連。","相思在万里，明月正孤懸。","影移金岫北，光斷玉门前。","寄书謝中婦，时看鴻雁天。"]', '诗', 'shi', '', NULL, '橫吹曲辭 關山月 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31df356e-d9f2-4984-8f0e-66349cab666e', '橫吹曲辭 關山月', '橫吹曲辞 关山月', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["漢月生遼海，曈曨出半暉。","合昏玄兔郡，中夜白登圍。","暈落關山迥，光合霜霰微。","將軍聽曉角，戰馬欲南歸。"]', '["漢月生遼海，曈曨出半暉。","合昏玄兔郡，中夜白登圍。","暈落关山迥，光合霜霰微。","將軍听晓角，戰马欲南归。"]', '诗', 'shi', '', NULL, '橫吹曲辭 關山月 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0167687e-8325-48bf-8da4-3749c9ce0a74', '橫吹曲辭 關山月', '橫吹曲辞 关山月', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["明月出天山，蒼茫雲海間。","長風幾萬里，吹度玉門關。","漢下白登道，胡窺青海灣。","由來征戰地，不見有人還。","戍客望邊色，思歸多苦顏。","高樓當此夜，歎息未應閑。"]', '["明月出天山，蒼茫云海间。","长风幾万里，吹度玉门关。","漢下白登道，胡窺青海灣。","由来征戰地，不见有人還。","戍客望邊色，思归多苦顏。","高楼當此夜，歎息未應闲。"]', '诗', 'shi', '', NULL, '橫吹曲辭 關山月 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da42362f-b22f-4ca6-a18e-69284623c195', '橫吹曲辭 關山月', '橫吹曲辞 关山月', 'd3148703-6408-4197-b38c-1604c89122c6', '唐', '["淒淒還切切，戍客多離別。","何處最傷心？關山見秋月。","關月竟如何？由來遠近過。","始經玄兔塞，終繞白狼河。","忽憶秦樓婦，流光應共有。","已得竝蛾眉，還知攬纖手。","去歲照同行，比翼復連形。","今宵照獨立，顧影自煢煢。","餘暉漸西落，夜夜看如昨。","借問映旌旗，何如鑒帷幕。","拂曉朔風悲，蓬驚雁不飛。","幾時征戍罷，還向月中歸。"]', '["淒淒還切切，戍客多離別。","何处最傷心？关山见秋月。","关月竟如何？由来远近過。","始經玄兔塞，終繞白狼河。","忽憶秦楼婦，流光應共有。","已得竝蛾眉，還知攬纖手。","去歲照同行，比翼复連形。","今宵照独立，顧影自煢煢。","餘暉漸西落，夜夜看如昨。","借问映旌旗，何如鑒帷幕。","拂晓朔风悲，蓬驚雁不飞。","幾时征戍罷，還向月中归。"]', '诗', 'shi', '', NULL, '橫吹曲辭 關山月 長孫佐輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea0efc2b-125c-4680-a02b-16da31a0908b', '橫吹曲辭 關山月', '橫吹曲辞 关山月', '7c891598-5c2d-4135-b2cd-60fcb5f29523', '唐', '["月明邊徼靜，戍客望鄉時。","塞古柳衰盡，關寒榆發遲。","蒼蒼萬里道，戚戚十年悲。","今夜青樓上，還應照所思。"]', '["月明邊徼静，戍客望乡时。","塞古柳衰尽，关寒榆發遲。","蒼蒼万里道，戚戚十年悲。","今夜青楼上，還應照所思。"]', '诗', 'shi', '', NULL, '橫吹曲辭 關山月 耿[湋] shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6795674b-74d6-4ac8-94ef-792c9892c714', '橫吹曲辭 關山月二首 一', '橫吹曲辞 关山月二首 一', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["月出照關山，秋風人未還。","清光無遠近，鄉淚半書間。"]', '["月出照关山，秋风人未還。","清光無远近，乡泪半书间。"]', '诗', 'shi', '', NULL, '橫吹曲辭 關山月二首 一 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8a62427-62ef-45a8-9b30-e0fc90d5b78f', '橫吹曲辭 關山月二首 二', '橫吹曲辞 关山月二首 二', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["一雁過連營，繁霜覆古城。","胡笳在何處？半夜起邊聲。"]', '["一雁過連營，繁霜覆古城。","胡笳在何处？半夜起邊声。"]', '诗', 'shi', '', NULL, '橫吹曲辭 關山月二首 二 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b14de1b5-e97d-4ff0-a6d5-02468166e04d', '橫吹曲辭 關山月', '橫吹曲辞 关山月', 'fee52be3-9dbf-49b0-811a-7fa71985b765', '唐', '["月生西海上，氣逐邊風壯。","萬里度關山，蒼茫非一狀。","漢兵開郡國，胡馬窺亭障。","夜夜聞悲笳，征人起南望。"]', '["月生西海上，氣逐邊风壯。","万里度关山，蒼茫非一狀。","漢兵开郡国，胡马窺亭障。","夜夜闻悲笳，征人起南望。"]', '诗', 'shi', '', NULL, '橫吹曲辭 關山月 崔融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfa56f27-ecce-4c1e-81a0-439155849540', '橫吹曲辭 關山月', '橫吹曲辞 关山月', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["露溼月蒼蒼，關頭榆葉黃。","回輪照海遠，分彩上樓長。","水凍頻移幕，兵疲數望鄉。","祗應城影外，萬里共如霜。"]', '["露溼月蒼蒼，关头榆葉黄。","回輪照海远，分彩上楼长。","水凍頻移幕，兵疲數望乡。","祗應城影外，万里共如霜。"]', '诗', 'shi', '', NULL, '橫吹曲辭 關山月 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3fde978-e64b-4480-994a-ac04f81d5adc', '橫吹曲辭 關山月', '橫吹曲辞 关山月', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["關山月，營開道白前軍發。","凍輪當磧光悠悠，照見三堆兩堆骨。","邊風割面天欲明，金莎嶺西看看沒。"]', '["关山月，營开道白前軍發。","凍輪當磧光悠悠，照见三堆兩堆骨。","邊风割面天欲明，金莎嶺西看看沒。"]', '诗', 'shi', '', NULL, '橫吹曲辭 關山月 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10ef9dd5-f761-4463-9d90-fa9a426ac89c', '橫吹曲辭 關山月', '橫吹曲辞 关山月', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["秋月朗朗關山上，山中行人馬蹄響。","關山秋來雨雪多，行人見月唱邊歌。","海邊漠漠天氣白，胡兒夜度黃龍磧。","軍中探騎暮出城，伏兵暗處低旌戟。","溪水連地霜草平，野駞尋水磧中鳴。","隴頭風急雁不下，沙場苦戰多流星。","可憐萬國關山道，年年戰骨多秋草。"]', '["秋月朗朗关山上，山中行人马蹄响。","关山秋来雨雪多，行人见月唱邊歌。","海邊漠漠天氣白，胡兒夜度黄龙磧。","軍中探騎暮出城，伏兵暗处低旌戟。","溪水連地霜草平，野駞尋水磧中鳴。","隴头风急雁不下，沙場苦戰多流星。","可怜万国关山道，年年戰骨多秋草。"]', '诗', 'shi', '', NULL, '橫吹曲辭 關山月 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f73ad3c7-1f64-4825-b47d-c1e5a570758e', '橫吹曲辭 關山月', '橫吹曲辞 关山月', '60e56738-e921-4ab7-a3b3-c2203aac059b', '唐', '["裴回漢月滿邊州，照盡天涯到隴頭。","影轉銀河寰海靜，光分玉塞古今愁。","笳吹遠戍孤烽滅，雁下平沙萬里秋。","況是故園搖落夜，那堪少婦獨登樓。"]', '["裴回漢月满邊州，照尽天涯到隴头。","影轉銀河寰海静，光分玉塞古今愁。","笳吹远戍孤烽滅，雁下平沙万里秋。","況是故园搖落夜，那堪少婦独登楼。"]', '诗', 'shi', '', NULL, '橫吹曲辭 關山月 翁綬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe228ab0-4162-418d-8d88-3c760016ebfe', '橫吹曲辭 關山月', '橫吹曲辞 关山月', '43f9ef1b-5f74-48ec-99b5-650c37a65f49', '唐', '["高高秋月明，北照遼陽城。","塞迥光初滿，風多暈更生。","征人望鄉思，戰馬聞鞞驚。","朔風悲邊草，胡沙昏虜營。","霜疑匣中劒，風憊原上旌。","早晚謁金闕，不聞刁斗聲。"]', '["高高秋月明，北照遼陽城。","塞迥光初满，风多暈更生。","征人望乡思，戰马闻鞞驚。","朔风悲邊草，胡沙昏虜營。","霜疑匣中劒，风憊原上旌。","早晚謁金闕，不闻刁斗声。"]', '诗', 'shi', '', NULL, '橫吹曲辭 關山月 鮑氏君[徽]微 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef02ddad-16dc-47e8-b7fc-f5afd4c8c593', '橫吹曲辭 洛陽道', '橫吹曲辞 洛陽道', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["浮世若浮雲，千回故復新。","旋添青草冢，更有白頭人。","歲暮客將老，雪晴山欲春。","行行車與馬，不盡洛陽塵。"]', '["浮世若浮云，千回故复新。","旋添青草冢，更有白头人。","歲暮客將老，雪晴山欲春。","行行车與马，不尽洛陽塵。"]', '诗', 'shi', '', NULL, '橫吹曲辭 洛陽道 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9997e88a-f75c-47ec-a336-359bb426fcf4', '橫吹曲辭 洛陽道', '橫吹曲辞 洛陽道', 'a684e3a8-270e-4df1-aec8-ac36b0288dd3', '唐', '["客亭門外路東西，多少喧騰事不齊。","楊柳惹鞭公子醉，紵麻掩淚魯人迷。","通宵塵土飛山月，是處經營夾御堤。","頃刻知音幾存歿，半回依約認輪蹄。"]', '["客亭门外路东西，多少喧腾事不齊。","楊柳惹鞭公子醉，紵麻掩泪魯人迷。","通宵塵土飞山月，是处經營夾御堤。","頃刻知音幾存歿，半回依約認輪蹄。"]', '诗', 'shi', '', NULL, '橫吹曲辭 洛陽道 鄭渥 shi');
